namespace AiKv.Core.Errors;

/// <summary>
/// Stable error codes used across CLI, Local API, and GUI.
/// Error codes must not contain temporary implementation names.
/// </summary>
public enum ErrorCode
{
    // General
    Unknown = 0,
    InvalidArgument = 1001,
    NotSupported = 1002,
    OperationCancelled = 1003,

    // Workspace
    WorkspaceNotFound = 2001,
    WorkspaceNotUnique = 2002,
    WorkspacePathEscape = 2003,
    WorkspaceAlreadyExists = 2004,
    WorkspaceArchived = 2005,

    // Index
    IndexNotFound = 3001,
    IndexSnapshotMismatch = 3002,
    IndexCorrupted = 3003,

    // Context
    ContextPackageNotFound = 4001,
    ContextBudgetExceeded = 4002,
    ContextBuildFailed = 4003,
    ContextExpandFailed = 4004,

    // Security
    SecurityPolicyViolation = 5001,
    SecretDetected = 5002,
    CloudSendDenied = 5003,
    PathTraversalDetected = 5004,

    // Repository
    RepositoryCloneFailed = 6001,
    RepositoryPullConflict = 6002,
    RepositoryUrlInvalid = 6003,

    // Gateway
    GatewayUnavailable = 7001,
    ProviderError = 7002,
}

using System.Diagnostics.CodeAnalysis;

namespace AiKv.Core.Errors;

/// <summary>
/// Exception carrying a stable <see cref="ErrorCode"/> and structured details.
/// CLI/API error responses must derive from this exception, not from exception message strings.
/// </summary>
[Serializable]
public sealed class AiKvException : Exception
{
    public ErrorCode Code { get; }

    public string? TraceId { get; init; }

    public IReadOnlyDictionary<string, object?> Details { get; }

    public bool Recoverable { get; init; }

    public AiKvException(ErrorCode code, string message)
        : this(code, message, null, null, false)
    {
    }

    public AiKvException(ErrorCode code, string message, Exception? innerException)
        : this(code, message, innerException, null, false)
    {
    }

    public AiKvException(
        ErrorCode code,
        string message,
        Exception? innerException,
        IReadOnlyDictionary<string, object?>? details,
        bool recoverable)
        : base(message, innerException)
    {
        Code = code;
        Details = details ?? new Dictionary<string, object?>();
        Recoverable = recoverable;
    }

    [ExcludeFromCodeCoverage]
    private AiKvException(
        System.Runtime.Serialization.SerializationInfo info,
        System.Runtime.Serialization.StreamingContext context)
        : base(info, context)
    {
        Code = (ErrorCode)(info.GetValue(nameof(Code), typeof(int)) ?? ErrorCode.Unknown);
        TraceId = info.GetString(nameof(TraceId));
        Recoverable = info.GetBoolean(nameof(Recoverable));
        Details = new Dictionary<string, object?>();
    }

    [ExcludeFromCodeCoverage]
    public override void GetObjectData(
        System.Runtime.Serialization.SerializationInfo info,
        System.Runtime.Serialization.StreamingContext context)
    {
        base.GetObjectData(info, context);
        info.AddValue(nameof(Code), (int)Code);
        info.AddValue(nameof(TraceId), TraceId);
        info.AddValue(nameof(Recoverable), Recoverable);
    }
}

namespace AiKv.Core.Results;

/// <summary>
/// Discriminated result that carries either a value or an error.
/// Avoids throwing exceptions for expected failure paths.
/// </summary>
public readonly record struct Result<T>
{
    public bool IsSuccess { get; }

    public T? Value { get; }

    public Errors.ErrorCode? Error { get; }

    public string? ErrorMessage { get; }

    private Result(T value)
    {
        IsSuccess = true;
        Value = value;
        Error = null;
        ErrorMessage = null;
    }

    private Result(Errors.ErrorCode code, string message)
    {
        IsSuccess = false;
        Value = default;
        Error = code;
        ErrorMessage = message;
    }

    public static Result<T> Success(T value) => new(value);

    public static Result<T> Failure(Errors.ErrorCode code, string message) => new(code, message);

    public static Result<T> Failure(Errors.AiKvException ex) => new(ex.Code, ex.Message);

    public TResult Match<TResult>(
        Func<T, TResult> onSuccess,
        Func<Errors.ErrorCode, string, TResult> onFailure)
        => IsSuccess ? onSuccess(Value!) : onFailure(Error!.Value, ErrorMessage!);

    public void Match(
        Action<T> onSuccess,
        Action<Errors.ErrorCode, string> onFailure)
    {
        if (IsSuccess)
        {
            onSuccess(Value!);
        }
        else
        {
            onFailure(Error!.Value, ErrorMessage!);
        }
    }
}

using AiKv.Core.Errors;
using AiKv.Core.Results;

namespace AiKv.Tests;

public class ErrorModelTests
{
    [Fact]
    public void AiKvException_ShouldCarryErrorCode()
    {
        var ex = new AiKvException(ErrorCode.WorkspaceNotFound, "Workspace not found");

        Assert.Equal(ErrorCode.WorkspaceNotFound, ex.Code);
        Assert.Equal("Workspace not found", ex.Message);
        Assert.False(ex.Recoverable);
        Assert.Empty(ex.Details);
    }

    [Fact]
    public void AiKvException_ShouldAcceptInnerException()
    {
        var inner = new InvalidOperationException("io error");
        var ex = new AiKvException(ErrorCode.IndexCorrupted, "Index corrupted", inner);

        Assert.Equal(ErrorCode.IndexCorrupted, ex.Code);
        Assert.Same(inner, ex.InnerException);
    }

    [Fact]
    public void AiKvException_ShouldAcceptDetailsAndRecoverable()
    {
        var details = new Dictionary<string, object?> { ["field"] = "path" };
        var ex = new AiKvException(
            ErrorCode.WorkspacePathEscape,
            "Path escape",
            null,
            details,
            recoverable: true);

        Assert.True(ex.Recoverable);
        Assert.Single(ex.Details);
        Assert.Equal("path", ex.Details["field"]);
    }

    [Fact]
    public void Result_Success_ShouldCarryValue()
    {
        var result = Result<int>.Success(42);

        Assert.True(result.IsSuccess);
        Assert.Equal(42, result.Value);
        Assert.Null(result.Error);
    }

    [Fact]
    public void Result_Failure_ShouldCarryError()
    {
        var result = Result<int>.Failure(ErrorCode.WorkspaceNotFound, "not found");

        Assert.False(result.IsSuccess);
        Assert.Equal(ErrorCode.WorkspaceNotFound, result.Error);
        Assert.Equal("not found", result.ErrorMessage);
    }

    [Fact]
    public void Result_Failure_FromException_ShouldExtractCode()
    {
        var ex = new AiKvException(ErrorCode.InvalidArgument, "bad arg");
        var result = Result<string>.Failure(ex);

        Assert.False(result.IsSuccess);
        Assert.Equal(ErrorCode.InvalidArgument, result.Error);
    }

    [Fact]
    public void Result_Match_ShouldInvokeCorrectBranch()
    {
        var success = Result<int>.Success(10);
        var failure = Result<int>.Failure(ErrorCode.Unknown, "err");

        var s = success.Match(v => v * 2, (c, m) => -1);
        var f = failure.Match(v => v * 2, (c, m) => -1);

        Assert.Equal(20, s);
        Assert.Equal(-1, f);
    }

    [Fact]
    public void ErrorCode_ShouldHaveStableIntegerValues()
    {
        // Error codes must be stable integers, not auto-assigned.
        Assert.Equal(2001, (int)ErrorCode.WorkspaceNotFound);
        Assert.Equal(2003, (int)ErrorCode.WorkspacePathEscape);
        Assert.Equal(5001, (int)ErrorCode.SecurityPolicyViolation);
    }
}

namespace AiKv.Core.Errors;

/// <summary>
/// Exception carrying a stable <see cref="ErrorCode"/> and structured details.
/// CLI/API error responses must derive from this exception, not from exception message strings.
/// </summary>
public sealed class AiKvException : Exception
{
    public ErrorCode Code { get; }

    public string? TraceId { get; init; }

    public IReadOnlyDictionary<string, object?> Details { get; }

    public bool Recoverable { get; init; }

    public AiKvException(ErrorCode code, string message)
        : this(code, message, null, null, false)
    {
    }

    public AiKvException(ErrorCode code, string message, Exception? innerException)
        : this(code, message, innerException, null, false)
    {
    }

    public AiKvException(
        ErrorCode code,
        string message,
        Exception? innerException,
        IReadOnlyDictionary<string, object?>? details,
