namespace AiKv.Core.Identifiers;

/// <summary>
/// Base for strongly-typed identifiers.
/// Prevents mixing different ID types (WorkspaceId, FileId, etc.) at compile time.
/// </summary>
/// <typeparam name="TSelf">The concrete ID type (CRTP).</typeparam>
public abstract record StrongId<TSelf>(string Value) : IComparable<StrongId<TSelf>>, IEquatable<StrongId<TSelf>>
    where TSelf : StrongId<TSelf>, new()
{
    public string Value { get; } = !string.IsNullOrWhiteSpace(Value)
        ? Value
        : throw new ArgumentException("ID value cannot be null or whitespace.", nameof(Value));

    public static TSelf New() => new(Guid.NewGuid().ToString("N"));

    public static TSelf Parse(string value) => (TSelf)Activator.CreateInstance(typeof(TSelf), value)!;

    public int CompareTo(StrongId<TSelf>? other) =>
        other is null ? 1 : string.Compare(Value, other.Value, StringComparison.Ordinal);

    public override string ToString() => Value;

    public static bool operator ==(StrongId<TSelf>? left, StrongId<TSelf>? right) =>
        left?.Equals(right) ?? right is null;

    public static bool operator !=(StrongId<TSelf>? left, StrongId<TSelf>? right) => !(left == right);

    public bool Equals(StrongId<TSelf>? other) =>
        other is not null && Value == other.Value;

    public override int GetHashCode() => Value.GetHashCode(StringComparison.Ordinal);
}

namespace AiKv.Core.Identifiers;

/// <summary>
/// Unique identifier for a workspace.
/// </summary>
public sealed record WorkspaceId(string Value) : StrongId<WorkspaceId>(Value);

/// <summary>
/// Unique identifier for a repository within a workspace.
/// </summary>
public sealed record RepositoryId(string Value) : StrongId<RepositoryId>(Value);

/// <summary>
/// Unique identifier for a component within a workspace.
/// </summary>
public sealed record ComponentId(string Value) : StrongId<ComponentId>(Value);

/// <summary>
/// Unique identifier for an indexed file.
/// </summary>
public sealed record FileId(string Value) : StrongId<FileId>(Value);

/// <summary>
/// Unique identifier for an index snapshot.
/// </summary>
public sealed record IndexSnapshotId(string Value) : StrongId<IndexSnapshotId>(Value);

/// <summary>
/// Unique identifier for a Context Package.
/// </summary>
public sealed record ContextPackageId(string Value) : StrongId<ContextPackageId>(Value);

/// <summary>
/// Unique identifier for a background job.
/// </summary>
public sealed record JobId(string Value) : StrongId<JobId>(Value);

using AiKv.Core.Identifiers;

namespace AiKv.Tests;

public class StrongIdTests
{
    [Fact]
    public void StrongId_ShouldRejectEmptyValue()
    {
        Assert.Throws<ArgumentException>(() => new WorkspaceId(""));
        Assert.Throws<ArgumentException>(() => new WorkspaceId("  "));
        Assert.Throws<ArgumentException>(() => new WorkspaceId(null!));
    }

    [Fact]
    public void StrongId_ShouldStoreValue()
    {
        var id = new WorkspaceId("ws_abc123");
        Assert.Equal("ws_abc123", id.Value);
        Assert.Equal("ws_abc123", id.ToString());
    }

    [Fact]
    public void StrongId_New_ShouldGenerateNonEmptyId()
    {
        var id = WorkspaceId.New();
        Assert.False(string.IsNullOrWhiteSpace(id.Value));
        Assert.Equal(32, id.Value.Length); // Guid.ToString("N") = 32 chars
    }

    [Fact]
    public void StrongId_Parse_ShouldCreateFromValue()
    {
        var id = FileId.Parse("file_001");
        Assert.Equal("file_001", id.Value);
    }

    [Fact]
    public void StrongId_Equality_ShouldCompareByValue()
    {
        var a = new WorkspaceId("ws_001");
        var b = new WorkspaceId("ws_001");
        var c = new WorkspaceId("ws_002");

        Assert.Equal(a, b);
        Assert.True(a == b);
        Assert.True(a != c);
    }

    [Fact]
    public void StrongId_ShouldNotMixDifferentTypes()
    {
        // Even if values are equal, different ID types should not be equal.
        var wsId = new WorkspaceId("abc");
        var fileId = new FileId("abc");

        // Different types cannot be compared with == since they are different record types.
        Assert.False(wsId.Equals(fileId));
    }

    [Fact]
    public void StrongId_CompareTo_ShouldOrderCorrectly()
    {
        var a = new JobId("job_001");
        var b = new JobId("job_002");

        Assert.True(a.CompareTo(b) < 0);
        Assert.True(b.CompareTo(a) > 0);
        Assert.Equal(0, a.CompareTo(new JobId("job_001")));
    }

    [Fact]
    public void StrongId_GetHashCode_ShouldBeConsistent()
    {
        var a = new ContextPackageId("ctx_001");
        var b = new ContextPackageId("ctx_001");

        Assert.Equal(a.GetHashCode(), b.GetHashCode());
    }
}

namespace AiKv.Core.Identifiers;

/// <summary>
