    [Fact]
    public void Payload_CanBeCreated_WithRequiredFields()
    {
        var payload = new ContextPackagePayload
        {
            ContextPackageId = "ctx_test001",
            Format = PayloadFormat.Markdown,
            Items =
            [
                new PayloadItem
                {
                    Path = "src/auth/token.ts",
