using System.Text.Json.Serialization;

namespace AiKv.Core.Capabilities;

/// <summary>
/// Capability discovery response returned by CLI and Local API.
/// Allows clients to detect available modules and protocol version.
/// </summary>
public sealed record CapabilityDiscovery
{
    [JsonPropertyName("version")]
    public required string Version { get; init; }

    [JsonPropertyName("protocolVersion")]
    public required string ProtocolVersion { get; init; }

    [JsonPropertyName("capabilities")]
    public required CapabilityFlags Capabilities { get; init; }

    [JsonPropertyName("schemaVersions")]
    public IReadOnlyDictionary<string, int>? SchemaVersions { get; init; }

    [JsonPropertyName("limitations")]
    public IReadOnlyList<string>? Limitations { get; init; }
}

/// <summary>
/// Flags indicating which AI_KV modules are available.
/// All flags default to false; specific phases enable them as implemented.
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter))]
public enum CapabilityFlag
{
    WorkspaceImport,
    ContextBuild,
    ContextExpand,
    ContextFeedback,
    ContextExplain,
    RepositoryClone,
    RepositoryPull,
    ProjectDetection,
    Gateway,
    Semantic,
    Lsp,
    FileExport,
    Cache,
}

public sealed record CapabilityFlags
{
    private readonly HashSet<CapabilityFlag> _enabled;

    public CapabilityFlags() => _enabled = [];

    public CapabilityFlags(IEnumerable<CapabilityFlag> enabled) =>
        _enabled = [.. enabled];

    [JsonPropertyName("workspaceImport")]
    public bool WorkspaceImport => _enabled.Contains(CapabilityFlag.WorkspaceImport);

    [JsonPropertyName("contextBuild")]
    public bool ContextBuild => _enabled.Contains(CapabilityFlag.ContextBuild);

    [JsonPropertyName("contextExpand")]
    public bool ContextExpand => _enabled.Contains(CapabilityFlag.ContextExpand);

    [JsonPropertyName("contextFeedback")]
    public bool ContextFeedback => _enabled.Contains(CapabilityFlag.ContextFeedback);

    [JsonPropertyName("contextExplain")]
    public bool ContextExplain => _enabled.Contains(CapabilityFlag.ContextExplain);

    [JsonPropertyName("repositoryClone")]
    public bool RepositoryClone => _enabled.Contains(CapabilityFlag.RepositoryClone);

    [JsonPropertyName("repositoryPull")]
    public bool RepositoryPull => _enabled.Contains(CapabilityFlag.RepositoryPull);

    [JsonPropertyName("projectDetection")]
    public bool ProjectDetection => _enabled.Contains(CapabilityFlag.ProjectDetection);

    [JsonPropertyName("gateway")]
    public bool Gateway => _enabled.Contains(CapabilityFlag.Gateway);

    [JsonPropertyName("semantic")]
    public bool Semantic => _enabled.Contains(CapabilityFlag.Semantic);

    [JsonPropertyName("lsp")]
    public bool Lsp => _enabled.Contains(CapabilityFlag.Lsp);

    [JsonPropertyName("fileExport")]
    public bool FileExport => _enabled.Contains(CapabilityFlag.FileExport);

    [JsonPropertyName("cache")]
    public bool Cache => _enabled.Contains(CapabilityFlag.Cache);

    public bool IsEnabled(CapabilityFlag flag) => _enabled.Contains(flag);

    public static CapabilityFlags With(params CapabilityFlag[] flags) => new(flags);
}

using System.Text.Json;
using AiKv.Core.Capabilities;

namespace AiKv.Tests;

public class CapabilityDiscoveryTests
{
    [Fact]
    public void CapabilityDiscovery_CanBeCreated_WithRequiredFields()
    {
        var cd = new CapabilityDiscovery
        {
            Version = "0.1.0-alpha",
            ProtocolVersion = "1.0",
            Capabilities = CapabilityFlags.With(CapabilityFlag.WorkspaceImport, CapabilityFlag.ContextBuild),
        };

        Assert.Equal("0.1.0-alpha", cd.Version);
        Assert.Equal("1.0", cd.ProtocolVersion);
        Assert.True(cd.Capabilities.WorkspaceImport);
        Assert.True(cd.Capabilities.ContextBuild);
        Assert.False(cd.Capabilities.Gateway);
        Assert.False(cd.Capabilities.Semantic);
    }

    [Fact]
    public void CapabilityFlags_Default_AllFalse()
    {
        var flags = new CapabilityFlags();

        Assert.False(flags.WorkspaceImport);
        Assert.False(flags.ContextBuild);
        Assert.False(flags.Gateway);
        Assert.False(flags.Lsp);
    }

    [Fact]
    public void CapabilityDiscovery_CanSerializeToJson()
    {
        var cd = new CapabilityDiscovery
        {
            Version = "0.1.0",
            ProtocolVersion = "1.0",
            Capabilities = CapabilityFlags.With(CapabilityFlag.ContextBuild, CapabilityFlag.ContextExpand),
            SchemaVersions = new Dictionary<string, int>
            {
                ["contextPackage"] = 1,
                ["capabilityDiscovery"] = 1,
            },
            Limitations = ["No GUI", "CLI only"],
        };

        var json = JsonSerializer.Serialize(cd);
        var deserialized = JsonSerializer.Deserialize<CapabilityDiscovery>(json);

        Assert.NotNull(deserialized);
        Assert.Equal("0.1.0", deserialized.Version);
        Assert.True(deserialized.Capabilities.ContextBuild);
        Assert.True(deserialized.Capabilities.ContextExpand);
        Assert.False(deserialized.Capabilities.Gateway);
        Assert.NotNull(deserialized.SchemaVersions);
        Assert.Equal(1, deserialized.SchemaVersions["contextPackage"]);
        Assert.NotNull(deserialized.Limitations);
        Assert.Equal(2, deserialized.Limitations.Count);
    }

    [Fact]
    public void CapabilityFlags_IsEnabled_ChecksCorrectFlag()
    {
        var flags = CapabilityFlags.With(CapabilityFlag.Cache, CapabilityFlag.FileExport);

        Assert.True(flags.IsEnabled(CapabilityFlag.Cache));
        Assert.True(flags.IsEnabled(CapabilityFlag.FileExport));
        Assert.False(flags.IsEnabled(CapabilityFlag.Gateway));
    }
}

