namespace AiKv.Storage;

/// <summary>
/// Manages AI_KV application data directory structure.
/// All AI_KV data (config, index, cache, logs, temp) lives here, never in user source directories.
/// </summary>
public sealed class AppDataDirectory
{
    public string Root { get; }
    public string ConfigPath { get; }
    public string IndexPath { get; }
    public string CachePath { get; }
    public string LogsPath { get; }
    public string TempPath { get; }

    public AppDataDirectory(string? rootPath = null)
    {
        Root = rootPath ?? GetDefaultRoot();
        ConfigPath = Path.Combine(Root, "config");
        IndexPath = Path.Combine(Root, "index");
        CachePath = Path.Combine(Root, "cache");
        LogsPath = Path.Combine(Root, "logs");
        TempPath = Path.Combine(Root, "temp");
    }

    /// <summary>
    /// Ensures all subdirectories exist. Creates them if missing.
    /// </summary>
    public void EnsureCreated()
    {
        foreach (var dir in new[] { Root, ConfigPath, IndexPath, CachePath, LogsPath, TempPath })
        {
            Directory.CreateDirectory(dir);
        }
    }

    /// <summary>
    /// Returns the database path for a specific workspace.
    /// </summary>
    public string GetWorkspaceDatabasePath(string workspaceId) =>
        Path.Combine(IndexPath, $"{workspaceId}.db");

    /// <summary>
    /// Returns the cache directory for a specific workspace.
    /// </summary>
    public string GetWorkspaceCachePath(string workspaceId) =>
        Path.Combine(CachePath, workspaceId);

    /// <summary>
    /// Cleans temporary files older than the specified cutoff.
    /// </summary>
    public void CleanTempOlderThan(TimeSpan age)
    {
        if (!Directory.Exists(TempPath)) return;

        var cutoff = DateTimeOffset.UtcNow - age;
        foreach (var file in Directory.EnumerateFiles(TempPath))
        {
            var lastWrite = new DateTimeOffset(File.GetLastWriteTimeUtc(file));
            if (lastWrite < cutoff)
            {
                File.Delete(file);
            }
        }
    }

    private static string GetDefaultRoot()
    {
        var baseDir = Environment.GetFolderPath(
            Environment.SpecialFolder.LocalApplicationData,
            Environment.SpecialFolderOption.DoNotVerify);
        return Path.Combine(baseDir, "AI_KV");
    }
}

using AiKv.Storage;

namespace AiKv.Tests;

public class AppDataDirectoryTests
{
    [Fact]
    public void AppDataDirectory_ShouldHaveDistinctSubdirectories()
    {
        using var temp = new TempDir();
        var appData = new AppDataDirectory(temp.Path);

        Assert.NotEqual(appData.ConfigPath, appData.IndexPath);
        Assert.NotEqual(appData.ConfigPath, appData.CachePath);
        Assert.NotEqual(appData.ConfigPath, appData.LogsPath);
        Assert.NotEqual(appData.ConfigPath, appData.TempPath);
        Assert.NotEqual(appData.IndexPath, appData.CachePath);
        Assert.NotEqual(appData.IndexPath, appData.LogsPath);
        Assert.NotEqual(appData.IndexPath, appData.TempPath);
    }

    [Fact]
    public void EnsureCreated_ShouldCreateAllDirectories()
    {
        using var temp = new TempDir();
        var appData = new AppDataDirectory(temp.Path);

        appData.EnsureCreated();

        Assert.True(Directory.Exists(appData.ConfigPath));
        Assert.True(Directory.Exists(appData.IndexPath));
        Assert.True(Directory.Exists(appData.CachePath));
        Assert.True(Directory.Exists(appData.LogsPath));
        Assert.True(Directory.Exists(appData.TempPath));
    }

    [Fact]
    public void GetWorkspaceDatabasePath_ShouldReturnPathInIndexDir()
    {
        using var temp = new TempDir();
        var appData = new AppDataDirectory(temp.Path);

        var dbPath = appData.GetWorkspaceDatabasePath("ws_001");

        Assert.Contains("ws_001.db", dbPath);
        Assert.Contains(appData.IndexPath, dbPath);
    }

    [Fact]
    public void GetWorkspaceCachePath_ShouldReturnPathInCacheDir()
    {
        using var temp = new TempDir();
        var appData = new AppDataDirectory(temp.Path);

        var cachePath = appData.GetWorkspaceCachePath("ws_001");

        Assert.Contains("ws_001", cachePath);
        Assert.Contains(appData.CachePath, cachePath);
    }

    [Fact]
    public void CleanTempOlderThan_ShouldDeleteOldFilesOnly()
    {
        using var temp = new TempDir();
        var appData = new AppDataDirectory(temp.Path);
        appData.EnsureCreated();

        var oldFile = Path.Combine(appData.TempPath, "old.tmp");
        var newFile = Path.Combine(appData.TempPath, "new.tmp");
        File.WriteAllText(oldFile, "old");
        File.WriteAllText(newFile, "new");

        // Set old file's last write time to 2 days ago
        File.SetLastWriteTimeUtc(oldFile, DateTime.UtcNow.AddDays(-2));

        appData.CleanTempOlderThan(TimeSpan.FromDays(1));

        Assert.False(File.Exists(oldFile));
        Assert.True(File.Exists(newFile));
    }

    private sealed class TempDir : IDisposable
    {
        public string Path { get; }

        public TempDir()
        {
            Path = System.IO.Path.Combine(
                System.IO.Path.GetTempPath(),
                "aikv_test_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(Path);
        }

        public void Dispose()
        {
            if (Directory.Exists(Path))
            {
                Directory.Delete(Path, recursive: true);
            }
        }
    }
}

using Microsoft.Data.Sqlite;

namespace AiKv.Storage.Database;

/// <summary>
/// Creates SQLite connections with WAL mode, busy timeout, and consistent settings.
/// </summary>
public sealed class SqliteConnectionFactory
{
    private readonly string _connectionString;

    public SqliteConnectionFactory(string databasePath)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(databasePath);
        _connectionString = new SqliteConnectionStringBuilder
        {
            DataSource = databasePath,
            Mode = SqliteOpenMode.ReadWriteCreate,
            Cache = SqliteCacheMode.Shared,
            ForeignKeys = true,
            DefaultTimeout = 30, // seconds
        }.ToString();
    }

    public SqliteConnection CreateOpenConnection()
    {
        var connection = new SqliteConnection(_connectionString);
        connection.Open();
        using var pragma = connection.CreateCommand();
        pragma.CommandText =
            """
            PRAGMA journal_mode = WAL;
            PRAGMA synchronous = NORMAL;
            PRAGMA busy_timeout = 30000;
            PRAGMA foreign_keys = ON;
            """;
        pragma.ExecuteNonQuery();
        return connection;
    }

    public string ConnectionString => _connectionString;
}

using Microsoft.Data.Sqlite;

namespace AiKv.Storage.Database;

/// <summary>
/// Represents a single database migration with a version number.
/// </summary>
public interface IMigration
{
    int Version { get; }
    string Description { get; }
    void Up(SqliteConnection connection, SqliteTransaction transaction);
}

/// <summary>
/// Base class for migrations providing common SQL execution.
/// </summary>
public abstract class MigrationBase(int version, string description) : IMigration
{
    public int Version { get; } = version;
    public string Description { get; } = description;

    public abstract void Up(SqliteConnection connection, SqliteTransaction transaction);

    protected void ExecuteSql(SqliteConnection connection, SqliteTransaction transaction, string sql)
    {
        using var cmd = connection.CreateCommand();
        cmd.Transaction = transaction;
        cmd.CommandText = sql;
        cmd.ExecuteNonQuery();
    }
}

using Microsoft.Data.Sqlite;

namespace AiKv.Storage.Database;

/// <summary>
/// Runs database migrations with schema version tracking.
/// On failure, the old database is preserved; migration is rolled back.
/// </summary>
public sealed class MigrationRunner
{
    private readonly SqliteConnectionFactory _factory;
    private readonly string _databasePath;
    private readonly IReadOnlyList<IMigration> _migrations;

    public MigrationRunner(SqliteConnectionFactory factory, string databasePath, IReadOnlyList<IMigration> migrations)
    {
        _factory = factory;
        _databasePath = databasePath;
        _migrations = migrations.OrderBy(m => m.Version).ToList();
    }

    /// <summary>
    /// Runs all pending migrations. Returns the number of migrations applied.
    /// </summary>
    public int Migrate()
    {
        EnsureSchemaVersionTable();

        var currentVersion = GetCurrentVersion();
        var pending = _migrations.Where(m => m.Version > currentVersion).ToList();

        if (pending.Count == 0) return 0;

        using var connection = _factory.CreateOpenConnection();
        using var transaction = connection.BeginTransaction();

        try
        {
            foreach (var migration in pending)
            {
                migration.Up(connection, transaction);
                UpdateSchemaVersion(connection, transaction, migration.Version, migration.Description);
            }
            transaction.Commit();
            return pending.Count;
        }
        catch
        {
            transaction.Rollback();
            throw;
        }
    }

    public int GetCurrentVersion()
    {
        using var connection = _factory.CreateOpenConnection();
        using var cmd = connection.CreateCommand();
        cmd.CommandText = "SELECT MAX(version) FROM __schema_version WHERE applied = 1";
        var result = cmd.ExecuteScalar();
        return result is int version ? version : 0;
    }

    private void EnsureSchemaVersionTable()
    {
        using var connection = _factory.CreateOpenConnection();
        using var cmd = connection.CreateCommand();
        cmd.CommandText =
            """
            CREATE TABLE IF NOT EXISTS __schema_version (
                version INTEGER PRIMARY KEY,
                description TEXT NOT NULL,
                applied_at TEXT NOT NULL DEFAULT (datetime('now')),
                applied INTEGER NOT NULL DEFAULT 1
            );
            """;
        cmd.ExecuteNonQuery();
    }

    private void UpdateSchemaVersion(SqliteConnection connection, SqliteTransaction transaction, int version, string description)
    {
        using var cmd = connection.CreateCommand();
        cmd.Transaction = transaction;
        cmd.CommandText =
            """
            INSERT INTO __schema_version (version, description) VALUES ($version, $description);
            """;
        cmd.Parameters.AddWithValue("$version", version);
        cmd.Parameters.AddWithValue("$description", description);
        cmd.ExecuteNonQuery();
    }
}

using Microsoft.Data.Sqlite;

namespace AiKv.Storage.Database.Migrations;

/// <summary>
/// Migration 1: Creates base tables for workspaces, files, index snapshots, and jobs.
/// </summary>
public sealed class Migration0001Initial : MigrationBase
{
    public Migration0001Initial() : base(1, "Create base tables") { }

    public override void Up(SqliteConnection connection, SqliteTransaction transaction)
    {
        ExecuteSql(connection, transaction,
            """
            CREATE TABLE IF NOT EXISTS workspaces (
                id TEXT PRIMARY KEY,
                name TEXT NOT NULL,
                root_path TEXT NOT NULL,
                root_path_hash TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'Imported',
                security_policy_version TEXT,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                updated_at TEXT NOT NULL DEFAULT (datetime('now'))
            );

            CREATE TABLE IF NOT EXISTS repositories (
                id TEXT PRIMARY KEY,
                workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
                url TEXT,
                branch TEXT,
                commit_hash TEXT,
                remote_type TEXT,
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            );

            CREATE TABLE IF NOT EXISTS components (
                id TEXT PRIMARY KEY,
                workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
                path TEXT NOT NULL,
                language TEXT,
                framework TEXT,
                build_system TEXT,
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            );

            CREATE TABLE IF NOT EXISTS index_snapshots (
                id TEXT PRIMARY KEY,
                workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
                status TEXT NOT NULL DEFAULT 'Building',
                file_count INTEGER NOT NULL DEFAULT 0,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                completed_at TEXT
            );

            CREATE TABLE IF NOT EXISTS files (
                id TEXT PRIMARY KEY,
                snapshot_id TEXT NOT NULL REFERENCES index_snapshots(id) ON DELETE CASCADE,
                path TEXT NOT NULL,
                normalized_path TEXT NOT NULL,
                size INTEGER NOT NULL,
                content_hash TEXT,
                language TEXT,
                is_binary INTEGER NOT NULL DEFAULT 0,
                status TEXT NOT NULL DEFAULT 'Discovered',
                created_at TEXT NOT NULL DEFAULT (datetime('now'))
            );

            CREATE TABLE IF NOT EXISTS background_jobs (
                id TEXT PRIMARY KEY,
                workspace_id TEXT REFERENCES workspaces(id) ON DELETE CASCADE,
                type TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'Queued',
                progress INTEGER NOT NULL DEFAULT 0,
                total INTEGER NOT NULL DEFAULT 0,
                error_message TEXT,
                created_at TEXT NOT NULL DEFAULT (datetime('now')),
                started_at TEXT,
                completed_at TEXT
            );

            CREATE INDEX IF NOT EXISTS idx_files_snapshot ON files(snapshot_id);
            CREATE INDEX IF NOT EXISTS idx_files_path ON files(normalized_path);
            CREATE INDEX IF NOT EXISTS idx_snapshots_workspace ON index_snapshots(workspace_id);
            CREATE INDEX IF NOT EXISTS idx_jobs_workspace ON background_jobs(workspace_id);
            """);
    }
}

using AiKv.Storage;
using AiKv.Storage.Database;
using AiKv.Storage.Database.Migrations;
using Microsoft.Data.Sqlite;

namespace AiKv.Tests;

public class SqliteDatabaseTests
{
    private static string GetTempDbPath() =>
        Path.Combine(Path.GetTempPath(), $"aikv_test_{Guid.NewGuid():N}.db");

    [Fact]
    public void ConnectionFactory_ShouldCreateConnectionWithWal()
    {
        var dbPath = GetTempDbPath();
        try
        {
            var factory = new SqliteConnectionFactory(dbPath);
            using var connection = factory.CreateOpenConnection();

            using var cmd = connection.CreateCommand();
            cmd.CommandText = "PRAGMA journal_mode;";
            var mode = (string)cmd.ExecuteScalar()!;

            Assert.Equal("wal", mode.ToLowerInvariant());
        }
        finally
        {
            CleanupDb(dbPath);
        }
    }

    [Fact]
    public void MigrationRunner_ShouldCreateBaseTables()
    {
        var dbPath = GetTempDbPath();
        try
        {
            var factory = new SqliteConnectionFactory(dbPath);
            var runner = new MigrationRunner(factory, dbPath, [new Migration0001Initial()]);

            var applied = runner.Migrate();

            Assert.Equal(1, applied);
            Assert.Equal(1, runner.GetCurrentVersion());

            // Verify tables exist
            using var connection = factory.CreateOpenConnection();
            foreach (var table in new[] { "workspaces", "repositories", "components", "index_snapshots", "files", "background_jobs" })
            {
                using var cmd = connection.CreateCommand();
                cmd.CommandText = $"SELECT count(*) FROM sqlite_master WHERE type='table' AND name='{table}';";
                Assert.Equal(1L, cmd.ExecuteScalar());
            }
        }
        finally
        {
            CleanupDb(dbPath);
        }
    }

    [Fact]
    public void MigrationRunner_ShouldBeIdempotent()
    {
