using System.Security.Cryptography;

namespace AiKv.Core.Paths;

/// <summary>
/// Normalizes and validates file system paths.
/// Handles separators, case, UNC, symlinks, and path traversal detection.
/// </summary>
public sealed class PathNormalizer
{
    private static readonly char[] Separators = ['\\', '/'];

    /// <summary>
    /// Normalizes a path to its canonical form.
    /// </summary>
    public string Normalize(string path)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(path);

        var fullPath = Path.GetFullPath(path);
        return fullPath.Replace('\\', '/');
    }

    /// <summary>
    /// Checks if a child path is inside the parent directory.
    /// Prevents path traversal attacks.
    /// </summary>
    public bool IsWithinRoot(string rootPath, string childPath)
    {
        var normalizedRoot = Normalize(rootPath).TrimEnd('/');
        var normalizedChild = Normalize(childPath);

        return normalizedChild.StartsWith(normalizedRoot + "/", StringComparison.OrdinalIgnoreCase)
               || string.Equals(normalizedChild, normalizedRoot, StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Detects path traversal patterns (.., %2e%2e, etc).
    /// </summary>
    public bool ContainsTraversal(string path)
    {
        if (string.IsNullOrWhiteSpace(path)) return false;

        var decoded = path.Replace("%2e", ".", StringComparison.OrdinalIgnoreCase)
                          .Replace("%2E", ".", StringComparison.OrdinalIgnoreCase)
                          .Replace("%2f", "/", StringComparison.OrdinalIgnoreCase)
                          .Replace("%2F", "/", StringComparison.OrdinalIgnoreCase);

        var segments = decoded.Split(Separators, StringSplitOptions.None);
        return segments.Any(s => s == "..");
    }

    /// <summary>
    /// Computes a SHA-256 hash of a path for fingerprinting.
    /// </summary>
    public static string ComputePathHash(string normalizedPath)
    {
        var bytes = System.Text.Encoding.UTF8.GetBytes(normalizedPath.ToLowerInvariant());
        var hash = SHA256.HashData(bytes);
        return Convert.ToHexString(hash).ToLowerInvariant();
    }

    /// <summary>
    /// Gets the relative path from root to target, using forward slashes.
    /// </summary>
    public string GetRelativePath(string rootPath, string targetPath)
    {
        var normalizedRoot = Normalize(rootPath).TrimEnd('/');
        var normalizedTarget = Normalize(targetPath);

        if (!IsWithinRoot(rootPath, targetPath))
        {
            throw new ArgumentException("Target path is not within root path.");
        }

        var relative = normalizedTarget[normalizedRoot.Length..].TrimStart('/');
        return relative;
    }
}

using AiKv.Core.Identifiers;
using AiKv.Core.Paths;

namespace AiKv.Core.Workspaces;

/// <summary>
/// Workspace status state machine.
/// </summary>
public enum WorkspaceStatus
{
    Unregistered,
    Imported,
    Indexing,
    Ready,
    Dirty,
    Degraded,
    Blocked,
    Archived,
}

/// <summary>
/// Workspace aggregate: the highest project container in AI_KV.
/// Can contain a single repo, monorepo, multi-repo collection, or non-Git directory.
/// </summary>
public sealed record Workspace
{
    public required WorkspaceId Id { get; init; }
    public required string Name { get; init; }
    public required string RootPath { get; init; }
    public required string RootPathHash { get; init; }
    public WorkspaceStatus Status { get; init; } = WorkspaceStatus.Imported;
    public string? SecurityPolicyVersion { get; init; }
    public DateTimeOffset CreatedAt { get; init; } = DateTimeOffset.UtcNow;
    public DateTimeOffset UpdatedAt { get; init; } = DateTimeOffset.UtcNow;

    public static Workspace Create(string name, string rootPath)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(name);
        ArgumentException.ThrowIfNullOrWhiteSpace(rootPath);

        var normalizer = new PathNormalizer();
        var normalized = normalizer.Normalize(rootPath);
        var hash = PathNormalizer.ComputePathHash(normalized);

        return new Workspace
        {
            Id = WorkspaceId.New(),
            Name = name,
            RootPath = normalized,
            RootPathHash = hash,
        };
    }
}

using AiKv.Core.Paths;
using AiKv.Core.Workspaces;

namespace AiKv.Tests;

public class PathAndWorkspaceTests
{
    [Fact]
    public void PathNormalizer_Normalize_ShouldUseForwardSlashes()
    {
        var normalizer = new PathNormalizer();
        var path = @"C:\Users\test\project";

        var result = normalizer.Normalize(path);

        Assert.DoesNotContain("\\", result);
        Assert.Contains("/", result);
    }

    [Fact]
    public void PathNormalizer_IsWithinRoot_ShouldAcceptChildPaths()
    {
        var normalizer = new PathNormalizer();

        Assert.True(normalizer.IsWithinRoot(@"C:\root", @"C:\root\sub\file.ts"));
        Assert.True(normalizer.IsWithinRoot(@"C:\root", @"C:\root"));
    }

    [Fact]
    public void PathNormalizer_IsWithinRoot_ShouldRejectOutsidePaths()
    {
        var normalizer = new PathNormalizer();

        Assert.False(normalizer.IsWithinRoot(@"C:\root", @"C:\other\file.ts"));
        Assert.False(normalizer.IsWithinRoot(@"C:\root", @"C:\rootmalicious\file.ts"));
    }

    [Fact]
    public void PathNormalizer_ContainsTraversal_ShouldDetectDotDot()
    {
        var normalizer = new PathNormalizer();

        Assert.True(normalizer.ContainsTraversal("../../../etc/passwd"));
        Assert.True(normalizer.ContainsTraversal("sub/../../escape"));
        Assert.True(normalizer.ContainsTraversal("%2e%2e/escape"));
    }

    [Fact]
    public void PathNormalizer_ContainsTraversal_ShouldAcceptNormalPaths()
    {
        var normalizer = new PathNormalizer();

        Assert.False(normalizer.ContainsTraversal("src/auth/token.ts"));
        Assert.False(normalizer.ContainsTraversal("C:/project/src"));
    }

    [Fact]
    public void PathNormalizer_ComputePathHash_ShouldBeDeterministic()
    {
        var hash1 = PathNormalizer.ComputePathHash("c:/project/src");
        var hash2 = PathNormalizer.ComputePathHash("c:/project/src");

        Assert.Equal(hash1, hash2);
        Assert.Equal(64, hash1.Length); // SHA-256 hex = 64 chars
    }

    [Fact]
    public void PathNormalizer_GetRelativePath_ShouldReturnForwardSlashPath()
    {
        var normalizer = new PathNormalizer();
        var relative = normalizer.GetRelativePath(@"C:\root", @"C:\root\src\auth.ts");

        Assert.Equal("src/auth.ts", relative);
    }

    [Fact]
    public void Workspace_Create_ShouldInitializeCorrectly()
    {
        var ws = Workspace.Create("test-project", @"C:\projects\test");

        Assert.False(string.IsNullOrEmpty(ws.Id.Value));
        Assert.Equal("test-project", ws.Name);
        Assert.DoesNotContain("\\", ws.RootPath);
        Assert.False(string.IsNullOrEmpty(ws.RootPathHash));
        Assert.Equal(WorkspaceStatus.Imported, ws.Status);
    }

    [Fact]
    public void Workspace_Create_ShouldRejectEmptyArgs()
    {
        Assert.Throws<ArgumentException>(() => Workspace.Create("", @"C:\test"));
        Assert.Throws<ArgumentException>(() => Workspace.Create("test", ""));
        Assert.Throws<ArgumentNullException>(() => Workspace.Create(null!, @"C:\test"));
    }

    [Fact]
    public void Workspace_Create_SamePath_ShouldProduceSameHash()
    {
        var ws1 = Workspace.Create("test1", @"C:\projects\test");
        var ws2 = Workspace.Create("test2", @"C:\projects\test");

        Assert.Equal(ws1.RootPathHash, ws2.RootPathHash);
    }
}

