using AiKv.Storage.Database;
using AiKv.Storage.Database.Migrations;
using AiKv.Storage.Repositories;

namespace AiKv.Cli.Commands;

public static class WorkspaceCommands
{
    public static Command Create()
    {
        var workspaceCmd = new Command("workspace", "Manage AI_KV workspaces");

        var importCmd = new Command("import", "Import a local directory as a workspace");
        var pathArg = new Argument<string>("path", "Root directory path");
        var nameOpt = new Option<string>("--name", "Workspace name");
        var dataDirOpt = new Option<string?>("--data-dir", "AI_KV data directory override");
        importCmd.AddArgument(pathArg);
        importCmd.AddOption(nameOpt);
        importCmd.AddOption(dataDirOpt);
        importCmd.SetHandler(async (path, name, dataDir) =>
        {
            var wsName = name ?? new DirectoryInfo(path).Name;
            var appData = new AppDataDirectory(dataDir);
            appData.EnsureCreated();
            var factory = new SqliteConnectionFactory(appData.GetWorkspaceDatabasePath("main"));
            var runner = new MigrationRunner(factory, appData.GetWorkspaceDatabasePath("main"), [new Migration0001Initial()]);
            runner.Migrate();
            var repo = new SqliteWorkspaceRepository(factory);
            var workspace = Workspace.Create(wsName, path);
            await repo.InsertAsync(workspace);
            Console.WriteLine($"Workspace imported: {workspace.Id.Value}");
            Console.WriteLine($"  Name: {workspace.Name}");
            Console.WriteLine($"  Path: {workspace.RootPath}");
            Console.WriteLine($"  Status: {workspace.Status}");
        }, pathArg, nameOpt, dataDirOpt);

        var statusCmd = new Command("status", "Show workspace status");
        var idOpt = new Option<string>("--id", "Workspace ID");
        statusCmd.AddOption(idOpt);
        statusCmd.SetHandler(async (id) =>
        {
            if (string.IsNullOrEmpty(id))
            {
                Console.Error.WriteLine("Error: --id is required");
                return;
            }
            var appData = new AppDataDirectory();
            var factory = new SqliteConnectionFactory(appData.GetWorkspaceDatabasePath("main"));
            var repo = new SqliteWorkspaceRepository(factory);
            var ws = await repo.FindByIdAsync(Core.Identifiers.WorkspaceId.Parse(id));
            if (ws is null)
            {
                Console.Error.WriteLine($"Workspace not found: {id}");
                return;
            }
            Console.WriteLine($"ID: {ws.Id.Value}");
            Console.WriteLine($"Name: {ws.Name}");
            Console.WriteLine($"Path: {ws.RootPath}");
            Console.WriteLine($"Status: {ws.Status}");
            Console.WriteLine($"Created: {ws.CreatedAt:O}");
        }, idOpt);

        var listCmd = new Command("list", "List all workspaces");
        listCmd.SetHandler(async () =>
        {
            var appData = new AppDataDirectory();
            var factory = new SqliteConnectionFactory(appData.GetWorkspaceDatabasePath("main"));
            var repo = new SqliteWorkspaceRepository(factory);
            var workspaces = await repo.ListAllAsync();
            if (workspaces.Count == 0)
            {
                Console.WriteLine("No workspaces registered.");
                return;
            }
            foreach (var ws in workspaces)
            {
                Console.WriteLine($"  {ws.Id.Value,-32}  {ws.Status,-12}  {ws.Name}");
            }
        });

        var removeCmd = new Command("remove", "Remove a workspace (AI_KV data only, not source code)");
        var removeIdOpt = new Option<string>("--id", "Workspace ID to remove");
        removeCmd.AddOption(removeIdOpt);
        removeCmd.SetHandler(async (id) =>
        {
            if (string.IsNullOrEmpty(id))
            {
                Console.Error.WriteLine("Error: --id is required");
                return;
            }
            var appData = new AppDataDirectory();
            var factory = new SqliteConnectionFactory(appData.GetWorkspaceDatabasePath("main"));
            var repo = new SqliteWorkspaceRepository(factory);
            await repo.RemoveAsync(Core.Identifiers.WorkspaceId.Parse(id));
            Console.WriteLine($"Workspace removed: {id}");
            Console.WriteLine("Note: Only AI_KV data was removed. Source code is untouched.");
        }, removeIdOpt);

        workspaceCmd.AddCommand(importCmd);
        workspaceCmd.AddCommand(statusCmd);
        workspaceCmd.AddCommand(listCmd);
        workspaceCmd.AddCommand(removeCmd);

        return workspaceCmd;
    }
}

