using System.Security.Cryptography;
using System.Text;

namespace AiKv.Indexing.IgnoreRules;

/// <summary>
/// Default ignore patterns always applied.
/// </summary>
public static readonly IReadOnlyList<string> DefaultIgnorePatterns =
[
    ".git",
    "node_modules",
    "Library",
    "Temp",
    "Logs",
    "obj",
    "bin",
    "dist",
    "build",
    "target",
    ".venv",
    "DerivedData",
    "Pods",
    "vendor",
    "coverage",
];

/// <summary>
/// Represents a single ignore rule.
/// </summary>
public sealed record IgnoreRule(string Pattern, IgnoreRuleSource Source);

/// <summary>
/// Source of an ignore rule.
/// </summary>
public enum IgnoreRuleSource
{
    Default,
    GitIgnore,
    AiKvIgnore,
    User,
}

/// <summary>
/// Merges ignore rules from default, .gitignore, .aikvignore, and user sources.
/// Provides matching and hash computation for reproducibility.
/// </summary>
public sealed class IgnoreRuleEngine
{
    private readonly List<IgnoreRule> _rules = [];
    private string? _cachedHash;

    public IReadOnlyList<IgnoreRule> Rules => _rules;

    /// <summary>
    /// Loads default ignore patterns.
    /// </summary>
    public IgnoreRuleEngine WithDefaults()
    {
        foreach (var pattern in DefaultIgnorePatterns)
            _rules.Add(new IgnoreRule(pattern, IgnoreRuleSource.Default));
        _cachedHash = null;
        return this;
    }

    /// <summary>
    /// Loads patterns from a .gitignore file.
    /// </summary>
    public IgnoreRuleEngine WithGitIgnore(string? gitignorePath)
    {
        LoadFile(gitignorePath, IgnoreRuleSource.GitIgnore);
        return this;
    }

    /// <summary>
    /// Loads patterns from a .aikvignore file.
    /// </summary>
    public IgnoreRuleEngine WithAiKvIgnore(string? aikvignorePath)
    {
        LoadFile(aikvignorePath, IgnoreRuleSource.AiKvIgnore);
        return this;
    }

    /// <summary>
    /// Adds user-specified patterns.
    /// </summary>
    public IgnoreRuleEngine WithUserRules(IEnumerable<string> patterns)
    {
        foreach (var pattern in patterns)
        {
            var trimmed = pattern.Trim();
            if (trimmed.Length > 0 && !trimmed.StartsWith("#"))
                _rules.Add(new IgnoreRule(trimmed, IgnoreRuleSource.User));
        }
        _cachedHash = null;
        return this;
    }

    /// <summary>
    /// Checks if a path should be ignored.
    /// </summary>
    public bool IsIgnored(string path)
    {
        var normalizedPath = path.Replace('\\', '/');

        foreach (var rule in _rules)
        {
            if (Matches(normalizedPath, rule.Pattern))
                return true;
        }
        return false;
    }

    /// <summary>
    /// Computes a SHA-256 hash of all rules for reproducibility.
    /// </summary>
    public string GetRulesHash()
    {
        if (_cachedHash is not null) return _cachedHash;

        var sb = new StringBuilder();
        foreach (var rule in _rules.OrderBy(r => r.Pattern, StringComparer.Ordinal))
        {
            sb.Append(rule.Pattern).Append('|').Append(rule.Source).Append('\n');
        }

        var bytes = Encoding.UTF8.GetBytes(sb.ToString());
        var hash = SHA256.HashData(bytes);
        _cachedHash = Convert.ToHexString(hash).ToLowerInvariant();
        return _cachedHash;
    }

    private void LoadFile(string? path, IgnoreRuleSource source)
    {
        if (string.IsNullOrEmpty(path) || !File.Exists(path)) return;

        foreach (var line in File.ReadAllLines(path))
        {
            var trimmed = line.Trim();
            if (trimmed.Length > 0 && !trimmed.StartsWith("#"))
                _rules.Add(new IgnoreRule(trimmed, source));
        }
        _cachedHash = null;
    }

    private static bool Matches(string path, string pattern)
    {
        // Simple glob matching: *, directory names, and exact patterns.
        if (pattern.EndsWith("/"))
        {
            var dirName = pattern.TrimEnd('/');
            return path.Split('/').Any(seg => string.Equals(seg, dirName, StringComparison.OrdinalIgnoreCase));
        }

        if (pattern.Contains('*'))
        {
            return GlobMatch(path, pattern);
        }

        return path.Split('/').Any(seg => string.Equals(seg, pattern, StringComparison.OrdinalIgnoreCase));
    }

    private static bool GlobMatch(string path, string pattern)
    {
        // Convert glob to regex: * → [^/]*, ? → [^/]
        var regexPattern = "^" + System.Text.RegularExpressions.Regex.Escape(pattern)
            .Replace("\\*", "[^/]*")
            .Replace("\\?", "[^/]") + "$";

        return System.Text.RegularExpressions.Regex.IsMatch(path, regexPattern, System.Text.RegularExpressions.RegexOptions.IgnoreCase);
    }
}

using AiKv.Indexing.IgnoreRules;

namespace AiKv.Tests;

public class IgnoreRuleEngineTests
{
    [Fact]
    public void WithDefaults_ShouldAddDefaultPatterns()
    {
        var engine = new IgnoreRuleEngine().WithDefaults();

        Assert.NotEmpty(engine.Rules);
        Assert.Contains(engine.Rules, r => r.Pattern == ".git");
        Assert.Contains(engine.Rules, r => r.Pattern == "node_modules");
        Assert.Contains(engine.Rules, r => r.Source == IgnoreRuleSource.Default);
    }

    [Fact]
    public void IsIgnored_ShouldMatchDefaultPatterns()
    {
        var engine = new IgnoreRuleEngine().WithDefaults();

        Assert.True(engine.IsIgnored("src/.git/config"));
        Assert.True(engine.IsIgnored("project/node_modules/express"));
        Assert.True(engine.IsIgnored("app/bin/debug"));
        Assert.True(engine.IsIgnored("app/obj/release"));
    }

    [Fact]
    public void IsIgnored_ShouldNotMatchNormalPaths()
    {
        var engine = new IgnoreRuleEngine().WithDefaults();

        Assert.False(engine.IsIgnored("src/main.ts"));
        Assert.False(engine.IsIgnored("app/Services/UserService.cs"));
    }

    [Fact]
    public void WithUserRules_ShouldAddCustomPatterns()
    {
        var engine = new IgnoreRuleEngine()
            .WithDefaults()
            .WithUserRules(["*.tmp", "secrets/"]);

        Assert.True(engine.IsIgnored("cache.tmp"));
        Assert.True(engine.IsIgnored("config/secrets/key.pem"));
        Assert.False(engine.IsIgnored("src/app.ts"));
    }

    [Fact]
    public void WithUserRules_ShouldSkipCommentsAndEmpty()
    {
        var engine = new IgnoreRuleEngine()
            .WithUserRules(["# comment", "", "  ", "*.log"]);

        Assert.Equal(1, engine.Rules.Count);
        Assert.True(engine.IsIgnored("app.log"));
    }

    [Fact]
    public void WithGitIgnore_ShouldLoadFromFile()
    {
        var tmpFile = Path.GetTempFileName();
        try
        {
            File.WriteAllLines(tmpFile, ["dist/", "# comment", "*.env", ""]);

            var engine = new IgnoreRuleEngine().WithGitIgnore(tmpFile);

            Assert.Equal(2, engine.Rules.Count);
            Assert.True(engine.IsIgnored("build/dist/app.js"));
            Assert.True(engine.IsIgnored("config.env"));
        }
        finally
        {
            File.Delete(tmpFile);
        }
    }

    [Fact]
    public void WithGitIgnore_ShouldHandleMissingFile()
    {
        var engine = new IgnoreRuleEngine().WithGitIgnore(null);

        Assert.Empty(engine.Rules);

        engine = new IgnoreRuleEngine().WithGitIgnore(@"C:\nonexistent\.gitignore");
        Assert.Empty(engine.Rules);
    }

    [Fact]
    public void GetRulesHash_ShouldBeDeterministic()
    {
        var engine1 = new IgnoreRuleEngine().WithDefaults().WithUserRules(["*.tmp"]);
        var engine2 = new IgnoreRuleEngine().WithDefaults().WithUserRules(["*.tmp"]);

        Assert.Equal(engine1.GetRulesHash(), engine2.GetRulesHash());
    }

    [Fact]
    public void GetRulesHash_ShouldDifferForDifferentRules()
    {
        var engine1 = new IgnoreRuleEngine().WithDefaults().WithUserRules(["*.tmp"]);
        var engine2 = new IgnoreRuleEngine().WithDefaults().WithUserRules(["*.log"]);

        Assert.NotEqual(engine1.GetRulesHash(), engine2.GetRulesHash());
    }

    [Fact]
    public void IsIgnored_ShouldMatchGlobPatterns()
    {
        var engine = new IgnoreRuleEngine().WithUserRules(["*.test.ts"]);

        Assert.True(engine.IsIgnored("src/app.test.ts"));
        Assert.False(engine.IsIgnored("src/app.ts"));
    }

    [Fact]
    public void IsIgnored_ShouldMatchDirectoryPatterns()
    {
        var engine = new IgnoreRuleEngine().WithUserRules(["coverage/"]);

        Assert.True(engine.IsIgnored("coverage/lcov.info"));
        Assert.False(engine.IsIgnored("src/app.ts"));
    }
}

