using System.Text;

namespace AiKv.Indexing.Detection;

/// <summary>
/// Detected file category.
/// </summary>
public enum FileCategory
{
    Text,
    Binary,
    Image,
    Archive,
    Certificate,
    Empty,
}

/// <summary>
/// Result of file type detection.
/// </summary>
public sealed record FileTypeInfo
{
    public required FileCategory Category { get; init; }
    public required string Language { get; init; }
    public required bool IsBinary { get; init; }
    public required bool ShouldIndex { get; init; }
}

/// <summary>
/// Detects file type using extension mapping and content sampling.
/// </summary>
public static class FileTypeDetector
{
    private static readonly IReadOnlyDictionary<string, string> ExtensionToLanguage = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
    {
        [".cs"] = "csharp",
        [".ts"] = "typescript",
        [".tsx"] = "typescript",
        [".js"] = "javascript",
        [".jsx"] = "javascript",
        [".py"] = "python",
        [".java"] = "java",
        [".kt"] = "kotlin",
        [".go"] = "go",
        [".rs"] = "rust",
        [".c"] = "c",
        [".cpp"] = "cpp",
        [".cc"] = "cpp",
        [".cxx"] = "cpp",
        [".h"] = "c",
        [".hpp"] = "cpp",
        [".rb"] = "ruby",
        [".php"] = "php",
        [".swift"] = "swift",
        [".ts"] = "typescript",
        [".json"] = "json",
        [".yaml"] = "yaml",
        [".yml"] = "yaml",
        [".xml"] = "xml",
        [".html"] = "html",
        [".css"] = "css",
        [".scss"] = "scss",
        [".sql"] = "sql",
        [".sh"] = "shell",
        [".ps1"] = "powershell",
        [".md"] = "markdown",
        [".toml"] = "toml",
        [".cfg"] = "config",
        [".conf"] = "config",
        [".ini"] = "ini",
        [".txt"] = "text",
        [".dockerfile"] = "dockerfile",
    };

    private static readonly IReadOnlySet<string> BinaryExtensions = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        ".exe", ".dll", ".so", ".dylib", ".a", ".lib", ".o", ".obj",
        ".png", ".jpg", ".jpeg", ".gif", ".bmp", ".ico", ".webp", ".tiff",
        ".zip", ".gz", ".tar", ".bz2", ".7z", ".rar", ".xz",
        ".pdf", ".doc", ".docx", ".xls", ".xlsx", ".ppt", ".pptx",
        ".mp3", ".mp4", ".avi", ".mov", ".wav", ".flac",
        ".class", ".jar", ".war",
        ".pdb", ".apk", ".aab",
        ".dylib", ".bin",
    };

    private static readonly IReadOnlySet<string> CertificateExtensions = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        ".pem", ".key", ".p12", ".pfx", ".crt", ".cer", ".der",
    };

    private const int SampleSize = 8192;

    public static FileTypeInfo Detect(string filePath, long fileSize)
    {
        var ext = Path.GetExtension(filePath).ToLowerInvariant();

        if (fileSize == 0)
        {
            return new FileTypeInfo
            {
                Category = FileCategory.Empty,
                Language = "unknown",
                IsBinary = false,
                ShouldIndex = false,
            };
        }

        if (CertificateExtensions.Contains(ext))
        {
            return new FileTypeInfo
            {
                Category = FileCategory.Certificate,
                Language = "unknown",
                IsBinary = true,
                ShouldIndex = false,
            };
        }

        if (BinaryExtensions.Contains(ext))
        {
            var isImage = ext is ".png" or ".jpg" or ".jpeg" or ".gif" or ".bmp" or ".ico" or ".webp" or ".tiff";
            var isArchive = ext is ".zip" or ".gz" or ".tar" or ".bz2" or ".7z" or ".rar" or ".xz";
            return new FileTypeInfo
            {
                Category = isImage ? FileCategory.Image
                         : isArchive ? FileCategory.Archive
                         : FileCategory.Binary,
                Language = "unknown",
                IsBinary = true,
                ShouldIndex = false,
            };
        }

        var language = ExtensionToLanguage.TryGetValue(ext, out var lang) ? lang : "unknown";

        // For unknown extensions, sample content to detect binary.
        if (language == "unknown")
        {
            var isBinary = IsContentBinary(filePath);
            return new FileTypeInfo
            {
                Category = isBinary ? FileCategory.Binary : FileCategory.Text,
                Language = isBinary ? "unknown" : "text",
                IsBinary = isBinary,
                ShouldIndex = !isBinary,
            };
        }

        return new FileTypeInfo
        {
            Category = FileCategory.Text,
            Language = language,
            IsBinary = false,
            ShouldIndex = true,
        };
    }

    private static bool IsContentBinary(string filePath)
    {
        try
        {
            using var stream = File.OpenRead(filePath);
            var buffer = new byte[SampleSize];
            var read = stream.Read(buffer, 0, Math.Min(SampleSize, (int)stream.Length));

            for (var i = 0; i < read; i++)
            {
                if (buffer[i] == 0) return true;
            }

            // Check for high ratio of non-printable characters.
            var nonPrintable = 0;
            for (var i = 0; i < read; i++)
            {
                if (buffer[i] < 9 || (buffer[i] > 13 && buffer[i] < 32))
                    nonPrintable++;
            }

            return read > 0 && (double)nonPrintable / read > 0.3;
        }
        catch
        {
            return true; // If we can't read it, treat as binary.
        }
    }
}

using System.Security.Cryptography;

namespace AiKv.Indexing.Hashing;

/// <summary>
/// Provides layered file hashing: full SHA-256 for small files, fast fingerprint for large files.
/// </summary>
public static class FileHasher
{
    private const long LargeFileThreshold = 1 * 1024 * 1024; // 1 MB
    private const int FingerprintSampleSize = 4096;

    /// <summary>
    /// Computes hash for a file. Uses full SHA-256 for small files,
    /// fast fingerprint (size + first/last samples) for large files.
    /// </summary>
    public static async Task<FileHash> HashAsync(string filePath, long fileSize, CancellationToken ct = default)
    {
        if (fileSize <= LargeFileThreshold)
        {
            var fullHash = await ComputeFullHashAsync(filePath, ct);
            return new FileHash(fullHash, fileSize, isFullHash: true);
        }

        var fingerprint = await ComputeFastFingerprintAsync(filePath, fileSize, ct);
        return new FileHash(fingerprint, fileSize, isFullHash: false);
    }

    /// <summary>
    /// Computes full SHA-256 hash on demand (e.g., before including in Context Package).
    /// </summary>
    public static async Task<string> ComputeFullHashAsync(string filePath, CancellationToken ct = default)
    {
        await using var stream = File.OpenRead(filePath);
        var hash = await SHA256.HashDataAsync(stream, ct);
        return "sha256:" + Convert.ToHexString(hash).ToLowerInvariant();
    }

    private static async Task<string> ComputeFastFingerprintAsync(string filePath, long fileSize, CancellationToken ct)
    {
        await using var stream = File.OpenRead(filePath);
        var sampleSize = (int)Math.Min(FingerprintSampleSize, fileSize);

        var head = new byte[sampleSize];
        var headRead = await stream.ReadAsync(head, ct);

        var tail = new byte[sampleSize];
        if (fileSize > sampleSize * 2)
        {
            stream.Seek(-sampleSize, SeekOrigin.End);
            await stream.ReadAsync(tail, ct);
        }

        var combined = new byte[headRead + tail.Length];
        Buffer.BlockCopy(head, 0, combined, 0, headRead);
        Buffer.BlockCopy(tail, 0, combined, headRead, tail.Length);

        var hash = SHA256.HashData(combined);
        return $"fp:{fileSize}:{Convert.ToHexString(hash).ToLowerInvariant()}";
    }
}

