using System.Diagnostics;

namespace AiKv.Indexing.Search;

/// <summary>
/// Result source for search operations.
/// </summary>
public enum SearchSource
{
    Fts5,
    Ripgrep,
    Fallback,
}

/// <summary>
/// A single ripgrep search result.
/// </summary>
public sealed record RipgrepResult
{
    public required string Path { get; init; }
    public required int LineNumber { get; init; }
    public required string Line { get; init; }
    public required SearchSource Source { get; init; } = SearchSource.Ripgrep;
}

/// <summary>
/// Wraps ripgrep for real-time disk search, regex, and fallback scenarios.
/// Results are always marked with SearchSource.Ripgrep.
/// </summary>
public sealed class RipgrepSearcher
{
    private readonly string? _ripgrepPath;

    public RipgrepSearcher(string? ripgrepPath = null)
    {
        _ripgrepPath = ripgrepPath ?? FindRipgrep();
    }

    public bool IsAvailable => _ripgrepPath is not null;

    /// <summary>
    /// Searches files using ripgrep with a regex pattern.
    /// </summary>
    public async Task<IReadOnlyList<RipgrepResult>> SearchAsync(
        string directory,
        string pattern,
        bool ignoreCase = false,
        string[]? globs = null,
        CancellationToken ct = default)
    {
        if (_ripgrepPath is null)
            return SearchFallback(directory, pattern, ignoreCase, ct);

        var args = new List<string>
        {
            "--line-number",
            "--no-heading",
            "--color=never",
        };

        if (ignoreCase) args.Add("-i");
        if (globs is not null)
        {
            foreach (var g in globs)
            {
                args.Add("--glob");
                args.Add(g);
            }
        }

        args.Add(pattern);
        args.Add(directory);

        var psi = new ProcessStartInfo
        {
            FileName = _ripgrepPath,
            RedirectStandardOutput = true,
            UseShellExecute = false,
            CreateNoWindow = true,
        };

        foreach (var arg in args)
            psi.ArgumentList.Add(arg);

        using var process = Process.Start(psi);
        if (process is null) return [];

        var results = new List<RipgrepResult>();
        while (!process.StandardOutput.EndOfStream)
        {
            ct.ThrowIfCancellationRequested();
            var line = process.StandardOutput.ReadLine();
            if (line is null) break;

            var parts = line.Split(':', 3);
            if (parts.Length >= 3 && int.TryParse(parts[1], out var lineNum))
            {
                results.Add(new RipgrepResult
                {
                    Path = parts[0],
                    LineNumber = lineNum,
                    Line = parts[2],
                });
            }
        }

        await process.WaitForExitAsync(ct);
        return results;
    }

    /// <summary>
    /// Fallback search using simple in-process text matching.
    /// Results marked with SearchSource.Fallback.
    /// </summary>
    private static List<RipgrepResult> SearchFallback(
        string directory, string pattern, bool ignoreCase, CancellationToken ct)
    {
        var comparison = ignoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
        var results = new List<RipgrepResult>();

        foreach (var file in Directory.EnumerateFiles(directory, "*", SearchOption.AllDirectories))
        {
            ct.ThrowIfCancellationRequested();
            var lines = File.ReadAllLines(file);
            for (var i = 0; i < lines.Length; i++)
            {
                if (lines[i].Contains(pattern, comparison))
                {
                    results.Add(new RipgrepResult
                    {
                        Path = file,
                        LineNumber = i + 1,
                        Line = lines[i],
                        Source = SearchSource.Fallback,
                    });
                }
            }
        }

        return results;
    }

    private static string? FindRipgrep()
    {
        var names = new[] { "rg", "rg.exe" };
        foreach (var name in names)
        {
            var path = Environment.GetEnvironmentVariable("PATH")
                ?.Split(Path.PathSeparator, StringSplitOptions.RemoveEmptyEntries)
                .Select(p => Path.Combine(p, name))
                .FirstOrDefault(File.Exists);
            if (path is not null) return path;
        }
        return null;
    }
}

using System.Collections.Concurrent;

namespace AiKv.Indexing.Watching;

/// <summary>
/// Represents a file system change event.
/// </summary>
public sealed record FileChangeEvent
{
    public required string Path { get; init; }
    public required ChangeType ChangeType { get; init; }
    public DateTimeOffset Timestamp { get; init; } = DateTimeOffset.UtcNow;
}

/// <summary>
/// Type of file system change.
/// </summary>
public enum ChangeType
{
    Created,
    Modified,
    Deleted,
    Renamed,
}

/// <summary>
/// Watches a directory for file changes and enqueues events with debouncing.
/// File system events are acceleration signals only; the final truth is file fingerprint reconciliation.
/// </summary>
public sealed class FileWatcher : IDisposable
{
    private readonly FileSystemWatcher _watcher;
    private readonly ConcurrentQueue<FileChangeEvent> _eventQueue = new();
    private readonly TimeSpan _debounceInterval;
    private readonly Timer _flushTimer;
    private ConcurrentDictionary<string, FileChangeEvent> _pendingEvents = new();
    private int _overflowCount;
    private bool _disposed;

    public int QueueCount => _eventQueue.Count;
    public int OverflowCount => _overflowCount;
    public bool HasOverflow => _overflowCount > 0;

    public FileWatcher(string directory, TimeSpan? debounceInterval = null)
    {
        _debounceInterval = debounceInterval ?? TimeSpan.FromMilliseconds(500);
        _watcher = new FileSystemWatcher(directory)
        {
            IncludeSubdirectories = true,
            NotifyFilter = NotifyFilters.FileName | NotifyFilters.LastWrite | NotifyFilters.Size | NotifyFilters.DirectoryName,
        };

        _watcher.Created += OnCreated;
        _watcher.Changed += OnChanged;
        _watcher.Deleted += OnDeleted;
        _watcher.Renamed += OnRenamed;
        _watcher.Error += OnError;

        _flushTimer = new Timer(FlushPending, null, _debounceInterval, _debounceInterval);
    }

    public void Start() => _watcher.EnableRaisingEvents = true;
    public void Stop() => _watcher.EnableRaisingEvents = false;

    /// <summary>
    /// Dequeues all pending events. Returns empty if no events.
    /// </summary>
    public IReadOnlyList<FileChangeEvent> DequeueAll()
    {
        var results = new List<FileChangeEvent>();
        while (_eventQueue.TryDequeue(out var evt))
            results.Add(evt);
        return results;
    }

    /// <summary>
    /// Clears the overflow counter (e.g., after reconciliation has been triggered).
    /// </summary>
    public void ClearOverflow() => Interlocked.Exchange(ref _overflowCount, 0);

    private void OnCreated(object sender, FileSystemEventArgs e) =>
        EnqueueDebounced(e.FullPath, ChangeType.Created);

    private void OnChanged(object sender, FileSystemEventArgs e) =>
        EnqueueDebounced(e.FullPath, ChangeType.Modified);

    private void OnDeleted(object sender, FileSystemEventArgs e) =>
        EnqueueDebounced(e.FullPath, ChangeType.Deleted);

    private void OnRenamed(object sender, RenamedEventArgs e) =>
        EnqueueDebounced(e.FullPath, ChangeType.Renamed);

    private void OnError(object sender, ErrorEventArgs e)
    {
        // Internal buffer overflow — mark for reconciliation.
        Interlocked.Increment(ref _overflowCount);
    }

    private void EnqueueDebounced(string path, ChangeType type)
    {
        _pendingEvents[path] = new FileChangeEvent
        {
            Path = path,
            ChangeType = type,
        };
    }

    private void FlushPending(object? state)
    {
        if (_pendingEvents.IsEmpty) return;

        var oldPending = Interlocked.Exchange(ref _pendingEvents, new ConcurrentDictionary<string, FileChangeEvent>());

        foreach (var kvp in oldPending)
            _eventQueue.Enqueue(kvp.Value);
    }

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        _flushTimer.Dispose();
        _watcher.Dispose();
    }
}

using AiKv.Indexing.States;

namespace AiKv.Indexing.Reconciliation;

/// <summary>
/// Result of a consistency check between the index and disk.
/// </summary>
public sealed record ReconciliationResult
{
    public required int TotalChecked { get; init; }
    public required int AddedFiles { get; init; }
    public required int ModifiedFiles { get; init; }
    public required int DeletedFiles { get; init; }
    public required int UnchangedFiles { get; init; }
    public required bool IsConsistent { get; init; }

    public IReadOnlyList<string> AddedPaths { get; init; } = [];
    public IReadOnlyList<string> ModifiedPaths { get; init; } = [];
    public IReadOnlyList<string> DeletedPaths { get; init; } = [];
}

/// <summary>
/// Compares the current index snapshot against disk state.
/// Detects added, modified, and deleted files.
/// </summary>
public sealed class ConsistencyReconciler
{
    /// <summary>
    /// Reconciles the index against disk. Compares paths, sizes, and modification times.
    /// </summary>
    public ReconciliationResult Reconcile(
        string rootPath,
        IReadOnlyDictionary<string, long> indexedFiles,
        IReadOnlySet<string>? ignorePatterns = null)
    {
        var diskFiles = ScanDisk(rootPath, ignorePatterns);

        var added = new List<string>();
        var modified = new List<string>();
        var deleted = new List<string>();
        var unchanged = 0;

        // Find added and modified files
        foreach (var (path, size) in diskFiles)
        {
            if (!indexedFiles.TryGetValue(path, out var indexedSize))
            {
                added.Add(path);
            }
            else if (indexedSize != size)
            {
                modified.Add(path);
            }
            else
            {
                unchanged++;
            }
        }

        // Find deleted files
        foreach (var indexedPath in indexedFiles.Keys)
        {
            if (!diskFiles.ContainsKey(indexedPath))
            {
                deleted.Add(indexedPath);
            }
        }

        return new ReconciliationResult
        {
            TotalChecked = diskFiles.Count + deleted.Count,
            AddedFiles = added.Count,
            ModifiedFiles = modified.Count,
            DeletedFiles = deleted.Count,
            UnchangedFiles = unchanged,
            IsConsistent = added.Count == 0 && modified.Count == 0 && deleted.Count == 0,
            AddedPaths = added,
            ModifiedPaths = modified,
            DeletedPaths = deleted,
        };
    }

    /// <summary>
    /// Forces a full re-check (e.g., after branch switch).
    /// </summary>
    public bool NeedsForcedReconcile(string rootPath, string lastKnownCommitHash)
    {
        // If Git HEAD changed, force reconcile.
        var gitDir = Path.Combine(rootPath, ".git");
        if (!Directory.Exists(gitDir)) return false;

        var headFile = Path.Combine(gitDir, "HEAD");
        if (!File.Exists(headFile)) return false;

        var currentHead = File.ReadAllText(headFile).Trim();
        return currentHead != lastKnownCommitHash;
    }

    private static Dictionary<string, long> ScanDisk(string rootPath, IReadOnlySet<string>? ignorePatterns)
    {
        var result = new Dictionary<string, long>(StringComparer.OrdinalIgnoreCase);
        var normalizedRoot = rootPath.Replace('\\', '/').TrimEnd('/');

        foreach (var file in Directory.EnumerateFiles(rootPath, "*", SearchOption.AllDirectories))
        {
            var normalized = file.Replace('\\', '/');

            // Check ignore patterns
            if (ignorePatterns is not null)
            {
                var relativePath = normalized.StartsWith(normalizedRoot, StringComparison.OrdinalIgnoreCase)
                    ? normalized[normalizedRoot.Length..].TrimStart('/')
                    : normalized;

                if (IsIgnored(relativePath, ignorePatterns)) continue;
            }

            try
            {
                var info = new FileInfo(file);
                result[normalized] = info.Length;
            }
            catch (UnauthorizedAccessException) { }
            catch (FileNotFoundException) { }
        }

        return result;
    }

    private static bool IsIgnored(string path, IReadOnlySet<string> patterns)
    {
        var segments = path.Split('/');
        return patterns.Any(p => segments.Any(s => string.Equals(s, p, StringComparison.OrdinalIgnoreCase)));
    }
}

