using System.Text.Json.Serialization;

namespace AiKv.Core.Parsing;

/// <summary>
/// Type of relation/symbol discovered by a parser.
/// Must explicitly mark whether a relation is syntactic, heuristic, or semantic.
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter))]
public enum RelationType
{
    /// <summary>Directly extracted from syntax tree (e.g., import statement).</summary>
    Syntactic,
    /// <summary>Inferred from patterns (e.g., possible call from identifier occurrence).</summary>
    Heuristic,
    /// <summary>Resolved via LSP or dedicated analyzer (e.g., definition reference).</summary>
    Semantic,
}

/// <summary>
/// Type of code symbol.
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter))]
public enum SymbolKind
{
    Namespace,
    Class,
    Interface,
    Struct,
    Enum,
    Function,
    Method,
    Property,
    Field,
    Import,
    Constant,
    TypeAlias,
    Variable,
    Other,
}

/// <summary>
/// A code symbol extracted from a file.
/// </summary>
public sealed record CodeSymbol
{
    public required string Name { get; init; }
    public required SymbolKind Kind { get; init; }
    public required int StartLine { get; init; }
    public required int EndLine { get; init; }
    public string? FullyQualifiedName { get; init; }
    public string? Modifier { get; init; } // public, private, static, etc.
}

/// <summary>
/// An import/dependency declaration found in a file.
/// </summary>
public sealed record ImportDeclaration
{
    public required string Module { get; init; }
    public string? ImportedName { get; init; } // specific named import
    public required int Line { get; init; }
}

/// <summary>
/// A call expression found in a file (heuristic, not semantic).
/// </summary>
public sealed record CallExpression
{
    public required string FunctionName { get; init; }
    public required int Line { get; init; }
}

/// <summary>
/// A relation between symbols or files.
/// </summary>
public sealed record CodeRelation
{
    public required RelationType RelationType { get; init; }
    public required string Relation { get; init; } // e.g., "possible_call", "definition_reference"
    public required string TargetName { get; init; }
    public required double Confidence { get; init; } // 0..1
    public required string Source { get; init; } // parser name
}

/// <summary>
/// Diagnostic message from parsing.
/// </summary>
public sealed record ParseDiagnostic
{
    public required int Line { get; init; }
    public required string Message { get; init; }
    public string? Severity { get; init; } // "error", "warning"
}

/// <summary>
/// Result of parsing a file: symbols, imports, calls, relations, and diagnostics.
/// </summary>
public sealed record ParseResult
{
    public required string ParserId { get; init; }
    public required string ParserVersion { get; init; }
    public required string Language { get; init; }
    public IReadOnlyList<CodeSymbol> Symbols { get; init; } = [];
    public IReadOnlyList<ImportDeclaration> Imports { get; init; } = [];
    public IReadOnlyList<CallExpression> CallExpressions { get; init; } = [];
    public IReadOnlyList<CodeRelation> Relations { get; init; } = [];
    public IReadOnlyList<ParseDiagnostic> Diagnostics { get; init; } = [];
    public bool PartialParse { get; init; } // true if file had syntax errors
}

/// <summary>
/// Parser contract: takes file content, returns structured analysis.
/// </summary>
public interface ICodeParser
{
    string Id { get; }
    string Version { get; }
    IReadOnlySet<string> SupportedExtensions { get; }
    ParseResult Parse(string content, string filePath);
}

using AiKv.Core.Parsing;

namespace AiKv.Indexing.Parsing;

/// <summary>
/// Generic text parser for unknown or unsupported languages.
/// Extracts headings, comments, config keys, Markdown sections, and code block boundaries.
/// Does not produce syntactic relations — only structural text signals.
/// </summary>
public sealed class TextParser : ICodeParser
{
    public string Id => "text";
    public string Version => "1.0";
    public IReadOnlySet<string> SupportedExtensions { get; } = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        ".txt", ".cfg", ".conf", ".ini", ".env.example", ".log",
    };

    public ParseResult Parse(string content, string filePath)
    {
        var lines = content.Split('\n');
        var symbols = new List<CodeSymbol>();
        var imports = new List<ImportDeclaration>();
        var diagnostics = new List<ParseDiagnostic>();

        for (var i = 0; i < lines.Length; i++)
        {
            var line = lines[i].TrimEnd('\r');

            // Markdown headings
            if (line.StartsWith("#"))
            {
                var level = 0;
                while (level < line.Length && line[level] == '#') level++;
                if (level <= 6 && line.Length > level)
                {
                    symbols.Add(new CodeSymbol
                    {
                        Name = line[level..].Trim(),
                        Kind = SymbolKind.Other,
                        StartLine = i + 1,
                        EndLine = i + 1,
                    });
                }
            }

            // INI/Config key-value pairs
            if (line.Contains('=') && !line.StartsWith('#') && !line.StartsWith("//"))
            {
                var eqIdx = line.IndexOf('=');
                var key = line[..eqIdx].Trim();
                if (key.Length > 0 && IsValidIdentifier(key))
                {
                    symbols.Add(new CodeSymbol
                    {
                        Name = key,
                        Kind = SymbolKind.Other,
                        StartLine = i + 1,
                        EndLine = i + 1,
                    });
                }
            }

            // Comments as context
            if (line.StartsWith("//") || line.StartsWith("/*") || line.StartsWith("*"))
            {
                // Comments are not symbols but could be useful for context
            }
        }

        return new ParseResult
        {
            ParserId = Id,
            ParserVersion = Version,
            Language = "text",
            Symbols = symbols,
        };
    }

    private static bool IsValidIdentifier(string s)
    {
        foreach (var c in s)
        {
            if (!char.IsLetterOrDigit(c) && c != '_' && c != '-' && c != '.')
                return false;
        }
        return true;
    }
}

using AiKv.Core.Parsing;

namespace AiKv.Indexing.Parsing;

/// <summary>
/// Markdown parser: extracts headings, code blocks, and section structure.
/// </summary>
public sealed class MarkdownParser : ICodeParser
{
    public string Id => "markdown";
    public string Version => "1.0";
    public IReadOnlySet<string> SupportedExtensions { get; } = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        ".md", ".markdown",
    };

    public ParseResult Parse(string content, string filePath)
    {
        var lines = content.Split('\n');
        var symbols = new List<CodeSymbol>();
        var diagnostics = new List<ParseDiagnostic>();

        for (var i = 0; i < lines.Length; i++)
        {
            var line = lines[i].TrimEnd('\r');

            // Headings
            if (line.StartsWith("#"))
            {
                var level = 0;
                while (level < line.Length && line[level] == '#') level++;
                if (level <= 6 && line.Length > level)
                {
                    symbols.Add(new CodeSymbol
                    {
                        Name = line[level..].Trim(),
                        Kind = SymbolKind.Other,
                        StartLine = i + 1,
                        EndLine = i + 1,
                    });
                }
            }

            // Code block boundaries
            if (line.StartsWith("```"))
            {
                var lang = line[3..].Trim();
                symbols.Add(new CodeSymbol
                {
                    Name = string.IsNullOrEmpty(lang) ? "code-block" : $"code:{lang}",
                    Kind = SymbolKind.Other,
                    StartLine = i + 1,
                    EndLine = i + 1,
                });
            }
        }

        return new ParseResult
        {
            ParserId = Id,
            ParserVersion = Version,
            Language = "markdown",
            Symbols = symbols,
        };
    }
}

using System.Text.RegularExpressions;

namespace AiKv.Indexing.Parsing;

/// <summary>
/// Regex-based C# parser: extracts namespaces, types, methods, properties, and imports.
/// All relations are marked as syntactic — this is NOT a semantic analysis.
/// </summary>
public sealed class CSharpRegexParser : ICodeParser
{
    public string Id => "csharp-regex";
    public string Version => "1.0";
    public IReadOnlySet<string> SupportedExtensions { get; } = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        ".cs",
    };

    public ParseResult Parse(string content, string filePath)
    {
        var lines = content.Split('\n');
        var symbols = new List<CodeSymbol>();
        var imports = new List<ImportDeclaration>();
        var calls = new List<CallExpression>();
        var relations = new List<CodeRelation>();
        var diagnostics = new List<ParseDiagnostic>();

        for (var i = 0; i < lines.Length; i++)
        {
            var line = lines[i].TrimEnd('\r');

            // using/import
            var usingMatch = UsingRegex().Match(line);
            if (usingMatch.Success)
            {
                var module = usingMatch.Groups[1].Value;
                imports.Add(new ImportDeclaration { Module = module, Line = i + 1 });
                symbols.Add(new CodeSymbol
                {
                    Name = module,
                    Kind = SymbolKind.Import,
                    StartLine = i + 1,
                    EndLine = i + 1,
                });
            }

            // namespace
            var nsMatch = NamespaceRegex().Match(line);
            if (nsMatch.Success)
            {
                symbols.Add(new CodeSymbol
                {
                    Name = nsMatch.Groups[1].Value,
                    Kind = SymbolKind.Namespace,
                    StartLine = i + 1,
                    EndLine = i + 1,
                });
            }

            // class/struct/interface/enum
            var typeMatch = TypeRegex().Match(line);
            if (typeMatch.Success)
            {
                var kindStr = typeMatch.Groups[1].Value.ToLowerInvariant();
                var kind = kindStr switch
                {
                    "class" => SymbolKind.Class,
                    "interface" => SymbolKind.Interface,
                    "struct" => SymbolKind.Struct,
                    "enum" => SymbolKind.Enum,
                    _ => SymbolKind.Other,
                };
                var name = typeMatch.Groups[2].Value;
                symbols.Add(new CodeSymbol
                {
                    Name = name,
                    Kind = kind,
                    StartLine = i + 1,
                    EndLine = FindEndOfBlock(lines, i),
                    Modifier = typeMatch.Groups[0].Value.Contains("public") ? "public" : null,
                });
            }

            // method
            var methodMatch = MethodRegex().Match(line);
            if (methodMatch.Success)
            {
                var name = methodMatch.Groups[2].Value;
                symbols.Add(new CodeSymbol
                {
                    Name = name,
                    Kind = SymbolKind.Method,
                    StartLine = i + 1,
                    EndLine = i + 1,
                    Modifier = methodMatch.Groups[1].Value,
                });
            }

            // property
            var propMatch = PropertyRegex().Match(line);
            if (propMatch.Success)
            {
                symbols.Add(new CodeSymbol
                {
                    Name = propMatch.Groups[2].Value,
                    Kind = SymbolKind.Property,
                    StartLine = i + 1,
                    EndLine = i + 1,
                    Modifier = propMatch.Groups[1].Value,
                });
            }

            // call expressions (heuristic)
            var callMatches = CallRegex().Matches(line);
            foreach (System.Text.RegularExpressions.Match call in callMatches)
            {
                var funcName = call.Groups[1].Value;
                calls.Add(new CallExpression { FunctionName = funcName, Line = i + 1 });
                relations.Add(new CodeRelation
                {
                    RelationType = RelationType.Heuristic,
                    Relation = "possible_call",
                    TargetName = funcName,
                    Confidence = 0.6,
                    Source = Id,
                });
            }
        }

        return new ParseResult
        {
            ParserId = Id,
            ParserVersion = Version,
            Language = "csharp",
            Symbols = symbols,
            Imports = imports,
            CallExpressions = calls,
            Relations = relations,
            Diagnostics = diagnostics,
        };
    }

    private static int FindEndOfBlock(string[] lines, int startLine)
    {
        var depth = 0;
        for (var i = startLine; i < lines.Length; i++)
        {
            foreach (var c in lines[i])
            {
                if (c == '{') depth++;
                if (c == '}') depth--;
            }
            if (depth == 0 && i > startLine) return i + 1;
        }
        return startLine + 1;
    }

