    private static partial Regex TypeRegex();

    [GeneratedRegex(@"^\s*(public|private|protected|internal)\s+(?:static\s+|async\s+)*(\w+)\s+(\w+)\s*\(")]
    private static partial Regex MethodRegex();

    [GeneratedRegex(@"^\s*(public|private|protected|internal)\s+(\w+)\s+(\w+)\s*\{")]
    private static partial Regex PropertyRegex();

    [GeneratedRegex(@"(\w+)\s*\(")]
    private static partial Regex CallRegex();
}

using System.Text.RegularExpressions;

namespace AiKv.Indexing.Parsing;

/// <summary>
/// Regex-based TypeScript parser: extracts modules, imports, classes, functions, interfaces.
/// </summary>
public sealed class TypeScriptRegexParser : ICodeParser
{
    public string Id => "typescript-regex";
    public string Version => "1.0";
    public IReadOnlySet<string> SupportedExtensions { get; } = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        ".ts", ".tsx", ".js", ".jsx",
    };

    public ParseResult Parse(string content, string filePath)
    {
        var lines = content.Split('\n');
        var symbols = new List<CodeSymbol>();
        var imports = new List<ImportDeclaration>();
        var calls = new List<CallExpression>();
        var relations = new List<CodeRelation>();

        for (var i = 0; i < lines.Length; i++)
        {
            var line = lines[i].TrimEnd('\r');

            // import
            var importMatch = ImportRegex().Match(line);
            if (importMatch.Success)
            {
                imports.Add(new ImportDeclaration
                {
                    Module = importMatch.Groups[1].Value,
                    ImportedName = importMatch.Groups[2].Value,
                    Line = i + 1,
                });
                symbols.Add(new CodeSymbol
                {
                    Name = importMatch.Groups[1].Value,
                    Kind = SymbolKind.Import,
                    StartLine = i + 1,
                    EndLine = i + 1,
                });
            }

            // export class/function/interface
            var exportMatch = ExportRegex().Match(line);
            if (exportMatch.Success)
            {
                var kindStr = exportMatch.Groups[1].Value;
                var name = exportMatch.Groups[2].Value;
                var kind = kindStr switch
                {
                    "class" => SymbolKind.Class,
                    "interface" => SymbolKind.Interface,
                    "function" => SymbolKind.Function,
                    "enum" => SymbolKind.Enum,
                    "const" => SymbolKind.Variable,
                    "type" => SymbolKind.TypeAlias,
                    _ => SymbolKind.Other,
                };
                symbols.Add(new CodeSymbol
                {
                    Name = name,
                    Kind = kind,
                    StartLine = i + 1,
                    EndLine = i + 1,
                });
            }

            // function declaration (non-export)
            var funcMatch = FunctionRegex().Match(line);
            if (funcMatch.Success)
            {
                symbols.Add(new CodeSymbol
                {
                    Name = funcMatch.Groups[1].Value,
                    Kind = SymbolKind.Function,
                    StartLine = i + 1,
                    EndLine = i + 1,
                });
            }

            // call expressions (heuristic)
            var callMatches = CallRegex().Matches(line);
            foreach (System.Text.RegularExpressions.Match call in callMatches)
            {
                var funcName = call.Groups[1].Value;
                calls.Add(new CallExpression { FunctionName = funcName, Line = i + 1 });
                relations.Add(new CodeRelation
                {
                    RelationType = RelationType.Heuristic,
                    Relation = "possible_call",
                    TargetName = funcName,
                    Confidence = 0.55,
                    Source = Id,
                });
            }
        }

        return new ParseResult
        {
            ParserId = Id,
            ParserVersion = Version,
            Language = "typescript",
            Symbols = symbols,
            Imports = imports,
            CallExpressions = calls,
            Relations = relations,
        };
    }

    [GeneratedRegex(@"import\s+(?:\{([^}]+)\}\s+from\s+)?['""]([^'""]+)['""]")]
    private static partial Regex ImportRegex();

    [GeneratedRegex(@"export\s+(class|interface|function|enum|const|type)\s+(\w+)")]
    private static partial Regex ExportRegex();

    [GeneratedRegex(@"function\s+(\w+)\s*[<(]")]
    private static partial Regex FunctionRegex();

    [GeneratedRegex(@"(\w+)\s*\(")]
    private static partial Regex CallRegex();
}

using System.Text.RegularExpressions;

namespace AiKv.Indexing.Parsing;

/// <summary>
/// Regex-based Python parser: extracts classes, functions, imports, and decorators.
/// </summary>
public sealed class PythonRegexParser : ICodeParser
{
    public string Id => "python-regex";
    public string Version => "1.0";
    public IReadOnlySet<string> SupportedExtensions { get; } = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        ".py",
    };

    public ParseResult Parse(string content, string filePath)
    {
        var lines = content.Split('\n');
        var symbols = new List<CodeSymbol>();
        var imports = new List<ImportDeclaration>();
        var calls = new List<CallExpression>();
        var relations = new List<CodeRelation>();

        for (var i = 0; i < lines.Length; i++)
        {
            var line = lines[i].TrimEnd('\r');

            // import/from import
            var fromMatch = FromImportRegex().Match(line);
            if (fromMatch.Success)
            {
                imports.Add(new ImportDeclaration
                {
                    Module = fromMatch.Groups[1].Value,
                    ImportedName = fromMatch.Groups[2].Value,
                    Line = i + 1,
                });
                symbols.Add(new CodeSymbol
                {
                    Name = fromMatch.Groups[1].Value,
                    Kind = SymbolKind.Import,
                    StartLine = i + 1,
                    EndLine = i + 1,
                });
                continue;
            }

            var importMatch = ImportRegex().Match(line);
            if (importMatch.Success)
            {
                imports.Add(new ImportDeclaration
                {
                    Module = importMatch.Groups[1].Value,
                    Line = i + 1,
                });
                symbols.Add(new CodeSymbol
                {
                    Name = importMatch.Groups[1].Value,
                    Kind = SymbolKind.Import,
                    StartLine = i + 1,
                    EndLine = i + 1,
                });
                continue;
            }

            // class
            var classMatch = ClassRegex().Match(line);
            if (classMatch.Success)
            {
                symbols.Add(new CodeSymbol
                {
                    Name = classMatch.Groups[1].Value,
                    Kind = SymbolKind.Class,
                    StartLine = i + 1,
                    EndLine = FindBlockEnd(lines, i),
                });
            }

            // function/def
            var funcMatch = FunctionRegex().Match(line);
            if (funcMatch.Success)
            {
                symbols.Add(new CodeSymbol
                {
                    Name = funcMatch.Groups[1].Value,
                    Kind = SymbolKind.Function,
                    StartLine = i + 1,
                    EndLine = FindBlockEnd(lines, i),
                });
            }

            // decorator
            var decoMatch = DecoratorRegex().Match(line);
            if (decoMatch.Success)
            {
                symbols.Add(new CodeSymbol
                {
                    Name = decoMatch.Groups[1].Value,
                    Kind = SymbolKind.Other,
                    StartLine = i + 1,
                    EndLine = i + 1,
                });
            }

            // call expressions (heuristic)
            var callMatches = CallRegex().Matches(line);
            foreach (System.Text.RegularExpressions.Match call in callMatches)
            {
                var funcName = call.Groups[1].Value;
                calls.Add(new CallExpression { FunctionName = funcName, Line = i + 1 });
                relations.Add(new CodeRelation
                {
                    RelationType = RelationType.Heuristic,
                    Relation = "possible_call",
                    TargetName = funcName,
                    Confidence = 0.5,
                    Source = Id,
                });
            }
        }

        return new ParseResult
        {
            ParserId = Id,
            ParserVersion = Version,
            Language = "python",
            Symbols = symbols,
            Imports = imports,
            CallExpressions = calls,
            Relations = relations,
        };
    }

    private static int FindBlockEnd(string[] lines, int startLine)
    {
        if (startLine + 1 >= lines.Length) return startLine + 1;
        var indent = GetIndent(lines[startLine]);
        for (var i = startLine + 1; i < lines.Length; i++)
        {
            if (lines[i].Trim().Length == 0) continue;
            if (GetIndent(lines[i]) <= indent && lines[i].Trim().Length > 0) return i;
        }
        return lines.Length;
    }

    private static int GetIndent(string line) => line.TakeWhile(c => c == ' ').Count();

    [GeneratedRegex(@"^\s*from\s+([\w.]+)\s+import\s+(.+)")]
    private static partial Regex FromImportRegex();

    [GeneratedRegex(@"^\s*import\s+([\w.]+)")]
    private static partial Regex ImportRegex();

    [GeneratedRegex(@"^\s*class\s+(\w+)")]
    private static partial Regex ClassRegex();

    [GeneratedRegex(@"^\s*def\s+(\w+)")]
    private static partial Regex FunctionRegex();

    [GeneratedRegex(@"^\s*@(\w+)")]
    private static partial Regex DecoratorRegex();

    [GeneratedRegex(@"(\w+)\s*\(")]
    private static partial Regex CallRegex();
}

using AiKv.Core.Parsing;
using AiKv.Indexing.Parsing;

namespace AiKv.Core.Parsing.Outline;

/// <summary>
/// Generates a deterministic, stable outline from a ParseResult.
/// Sorts symbols by line number, includes imports and key symbols.
/// </summary>
public sealed record OutlineEntry
{
    public required string Name { get; init; }
    public required SymbolKind Kind { get; init; }
    public required int StartLine { get; init; }
    public required int EndLine { get; init; }
    public string? Modifier { get; init; }
}

/// <summary>
/// Deterministic outline of a file.
/// </summary>
public sealed record FileOutline
{
    public required string FilePath { get; init; }
    public required string Language { get; init; }
    public required string ParserId { get; init; }
    public required string ParserVersion { get; init; }
    public required IReadOnlyList<OutlineEntry> Symbols { get; init; }
    public required IReadOnlyList<ImportDeclaration> Imports { get; init; }
}

/// <summary>
/// Generates stable outlines from parse results.
/// </summary>
public static class DeterministicOutlineGenerator
{
    /// <summary>
    /// Creates a deterministic outline from a parse result.
    /// Symbols are sorted by start line, then by name for stability.
    /// </summary>
    public static FileOutline Generate(ParseResult result, string filePath)
    {
        var sortedSymbols = result.Symbols
            .OrderBy(s => s.StartLine)
            .ThenBy(s => s.Name, StringComparer.Ordinal)
            .Select(s => new OutlineEntry
            {
                Name = s.Name,
                Kind = s.Kind,
                StartLine = s.StartLine,
                EndLine = s.EndLine,
                Modifier = s.Modifier,
            })
            .ToList();

        return new FileOutline
        {
            FilePath = filePath,
            Language = result.Language,
            ParserId = result.ParserId,
            ParserVersion = result.ParserVersion,
            Symbols = sortedSymbols,
            Imports = result.Imports,
        };
    }
}

using AiKv.Core.Parsing;
using AiKv.Core.Parsing.Outline;
