using AiKv.Core.Parsing;
using AiKv.Core.Parsing.Outline;

namespace AiKv.Core.Parsing.RepoMap;

/// <summary>
/// A node in the repository map tree.
/// </summary>
public sealed record RepoMapNode
{
    public required string Name { get; init; }
    public required string Path { get; init; }
    public required RepoMapNodeType Type { get; init; }
    public required int SymbolCount { get; init; }
    public IReadOnlyList<RepoMapNode> Children { get; init; } = [];
    public IReadOnlyList<OutlineEntry> KeySymbols { get; init; } = [];
}

/// <summary>
/// Type of node in the repository map.
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter))]
public enum RepoMapNodeType
{
    Directory,
    File,
    Symbol,
}

/// <summary>
/// A repository map: compressed tree of directories, files, and key symbols.
/// Strictly budget-limited for token efficiency.
/// </summary>
public sealed record RepoMap
{
    public required string RootPath { get; init; }
    public required RepoMapNode Root { get; init; }
    public required int TotalFiles { get; init; }
    public required int TotalSymbols { get; init; }
    public required int EstimatedTokens { get; init; }
}

/// <summary>
/// Generates a budget-limited repository map from file outlines.
/// Prioritizes by symbol count and directory depth.
/// </summary>
public static class RepoMapGenerator
{
    /// <summary>
    /// Generates a repo map from a collection of file outlines.
    /// </summary>
    public static RepoMap Generate(
        string rootPath,
        IReadOnlyList<(string relativePath, FileOutline outline)> files,
        int maxEstimatedTokens = 4000)
    {
        var root = BuildTree(rootPath, files, maxEstimatedTokens);
        var totalFiles = files.Count;
        var totalSymbols = files.Sum(f => f.outline.Symbols.Count);
        var estimatedTokens = EstimateTokens(root);

        return new RepoMap
        {
            RootPath = rootPath,
            Root = root,
            TotalFiles = totalFiles,
            TotalSymbols = totalSymbols,
            EstimatedTokens = estimatedTokens,
        };
    }

    private static RepoMapNode BuildTree(
        string rootPath,
        IReadOnlyList<(string relativePath, FileOutline outline)> files,
        int maxTokens)
    {
        var root = new RepoMapNode
        {
            Name = Path.GetFileName(rootPath),
            Path = "",
            Type = RepoMapNodeType.Directory,
            SymbolCount = files.Sum(f => f.outline.Symbols.Count),
        };

        var dirChildren = new Dictionary<string, List<(string relativePath, FileOutline outline)>>(StringComparer.OrdinalIgnoreCase);

        foreach (var file in files)
        {
            var dir = Path.GetDirectoryName(file.relativePath)?.Replace('\\', '/') ?? "";
            if (!dirChildren.TryGetValue(dir, out var list))
            {
                list = [];
                dirChildren[dir] = list;
            }
            list.Add(file);
        }

        var children = new List<RepoMapNode>();
        foreach (var (dir, dirFiles) in dirChildren.OrderBy(kv => kv.Key, StringComparer.Ordinal))
        {
            foreach (var file in dirFiles)
            {
                var keySymbols = file.outline.Symbols
                    .Where(s => s.Kind is SymbolKind.Class or SymbolKind.Interface or SymbolKind.Function or SymbolKind.Method)
                    .Take(5)
                    .ToList();

                children.Add(new RepoMapNode
                {
                    Name = Path.GetFileName(file.relativePath),
                    Path = file.relativePath,
                    Type = RepoMapNodeType.File,
                    SymbolCount = file.outline.Symbols.Count,
                    KeySymbols = keySymbols,
                });
            }
        }

        return root with { Children = children };
    }

    private static int EstimateTokens(RepoMapNode node)
    {
        // Rough estimate: ~4 tokens per symbol name + ~2 tokens per file path.
        var tokens = node.Name.Length / 4 + 2;
        foreach (var child in node.Children)
        {
            tokens += EstimateTokens(child);
        }
        foreach (var sym in node.KeySymbols)
        {
            tokens += sym.Name.Length / 4;
        }
        return tokens;
    }
}

using AiKv.Core.Parsing;
using AiKv.Indexing.Parsing;

namespace AiKv.Indexing.Parsing.Cache;

/// <summary>
/// Caches parse results by file hash + parser ID + parser version + grammar version.
/// Avoids re-parsing unchanged files.
/// </summary>
public sealed class ParserCache
{
    private readonly Dictionary<string, ParseResult> _cache = new();
    private readonly Dictionary<string, string> _hashToKey = new();

    /// <summary>
    /// Gets a cached parse result if available.
    /// </summary>
    public ParseResult? TryGet(string fileHash, string parserId, string parserVersion, string? grammarVersion = null)
    {
        var key = BuildKey(fileHash, parserId, parserVersion, grammarVersion);
        return _cache.TryGetValue(key, out var result) ? result : null;
    }

    /// <summary>
    /// Stores a parse result in the cache.
    /// </summary>
    public void Put(string fileHash, string parserId, string parserVersion, ParseResult result, string? grammarVersion = null)
    {
        var key = BuildKey(fileHash, parserId, parserVersion, grammarVersion);
        _cache[key] = result;
    }

    /// <summary>
    /// Gets or parses a file, using the cache when possible.
    /// </summary>
    public ParseResult GetOrParse(string content, string filePath, string fileHash, ICodeParser parser)
    {
        var cached = TryGet(fileHash, parser.Id, parser.Version);
        if (cached is not null) return cached;

        var result = parser.Parse(content, filePath);
        Put(fileHash, parser.Id, parser.Version, result);
        return result;
    }

    /// <summary>
    /// Removes all cached entries for a specific file hash.
    /// </summary>
    public void Invalidate(string fileHash)
    {
        var keysToRemove = _cache.Keys
            .Where(k => k.StartsWith(fileHash + "|", StringComparison.Ordinal))
            .ToList();
        foreach (var key in keysToRemove)
            _cache.Remove(key);
    }

    /// <summary>
    /// Clears the entire cache.
    /// </summary>
    public void Clear() => _cache.Clear();

    /// <summary>
    /// Returns the number of cached entries.
    /// </summary>
    public int Count => _cache.Count;

    private static string BuildKey(string fileHash, string parserId, string parserVersion, string? grammarVersion)
        => $"{fileHash}|{parserId}|{parserVersion}|{grammarVersion ?? "default"}";
}

using AiKv.Core.Parsing;
using AiKv.Core.Parsing.Outline;
using AiKv.Core.Parsing.RepoMap;
using AiKv.Indexing.Parsing;
using AiKv.Indexing.Parsing.Cache;

namespace AiKv.Tests;

public class RepoMapAndCacheTests
{
    [Fact]
    public void RepoMapGenerator_ShouldCreateTreeFromOutlines()
    {
        var files = new List<(string, FileOutline)>
        {
            ("src/auth.ts", new FileOutline
            {
                FilePath = "src/auth.ts",
                Language = "typescript",
                ParserId = "typescript-regex",
                ParserVersion = "1.0",
                Symbols =
                [
                    new OutlineEntry { Name = "AuthService", Kind = SymbolKind.Class, StartLine = 1, EndLine = 10 },
                    new OutlineEntry { Name = "login", Kind = SymbolKind.Function, StartLine = 3, EndLine = 5 },
                ],
                Imports = [],
            }),
            ("src/api.ts", new FileOutline
            {
                FilePath = "src/api.ts",
                Language = "typescript",
                ParserId = "typescript-regex",
                ParserVersion = "1.0",
                Symbols =
                [
                    new OutlineEntry { Name = "fetchData", Kind = SymbolKind.Function, StartLine = 1, EndLine = 5 },
                ],
                Imports = [],
            }),
        };

        var map = RepoMapGenerator.Generate("project", files);

        Assert.Equal(2, map.TotalFiles);
        Assert.Equal(3, map.TotalSymbols);
        Assert.True(map.EstimatedTokens > 0);
    }

    [Fact]
    public void RepoMapGenerator_ShouldIncludeKeySymbols()
    {
        var files = new List<(string, FileOutline)>
        {
            ("service.cs", new FileOutline
            {
                FilePath = "service.cs",
                Language = "csharp",
                ParserId = "csharp-regex",
                ParserVersion = "1.0",
                Symbols =
                [
                    new OutlineEntry { Name = "UserService", Kind = SymbolKind.Class, StartLine = 1, EndLine = 20 },
                    new OutlineEntry { Name = "GetUser", Kind = SymbolKind.Method, StartLine = 5, EndLine = 8 },
                    new OutlineEntry { Name = "field1", Kind = SymbolKind.Field, StartLine = 2, EndLine = 2 },
                ],
                Imports = [],
            }),
        };

        var map = RepoMapGenerator.Generate("project", files);
        var fileNode = map.Root.Children.First();

        Assert.Equal(RepoMapNodeType.File, fileNode.Type);
        Assert.True(fileNode.KeySymbols.Count <= 5);
        Assert.Contains(fileNode.KeySymbols, s => s.Name == "UserService");
        Assert.Contains(fileNode.KeySymbols, s => s.Name == "GetUser");
        // Fields are not key symbols
        Assert.DoesNotContain(fileNode.KeySymbols, s => s.Name == "field1");
    }

    [Fact]
    public void ParserCache_GetOrParse_ShouldCacheResults()
    {
        var cache = new ParserCache();
        var parser = new CSharpRegexParser();
        var content = "public class Test { }";

        var result1 = cache.GetOrParse(content, "test.cs", "hash123", parser);
        var result2 = cache.GetOrParse(content, "test.cs", "hash123", parser);

        Assert.Same(result1, result2);
        Assert.Equal(1, cache.Count);
    }

    [Fact]
    public void ParserCache_ShouldReturnNullForMiss()
    {
        var cache = new ParserCache();
        var result = cache.TryGet("nonexistent", "parser", "1.0");

        Assert.Null(result);
    }

    [Fact]
    public void ParserCache_Invalidate_ShouldRemoveEntries()
    {
        var cache = new ParserCache();
        var parser = new CSharpRegexParser();

        cache.GetOrParse("public class A { }", "a.cs", "hash_a", parser);
        cache.GetOrParse("public class B { }", "b.cs", "hash_b", parser);
        Assert.Equal(2, cache.Count);

        cache.Invalidate("hash_a");
        Assert.Equal(1, cache.Count);
        Assert.Null(cache.TryGet("hash_a", parser.Id, parser.Version));
        Assert.NotNull(cache.TryGet("hash_b", parser.Id, parser.Version));
    }

    [Fact]
    public void ParserCache_Clear_ShouldEmptyCache()
    {
        var cache = new ParserCache();
        var parser = new CSharpRegexParser();

        cache.GetOrParse("public class A { }", "a.cs", "hash_a", parser);
        cache.Clear();

        Assert.Equal(0, cache.Count);
    }

    [Fact]
    public void ParserCache_DifferentParsers_ShouldStoreSeparately()
    {
        var cache = new ParserCache();
        var csParser = new CSharpRegexParser();
        var mdParser = new MarkdownParser();

        var content = "# Hello\npublic class Test { }";

        cache.Put("hash1", csParser.Id, csParser.Version, csParser.Parse(content, "test.cs"));
        cache.Put("hash1", mdParser.Id, mdParser.Version, mdParser.Parse(content, "test.md"));

        Assert.Equal(2, cache.Count);
        var csResult = cache.TryGet("hash1", csParser.Id, csParser.Version);
        var mdResult = cache.TryGet("hash1", mdParser.Id, mdParser.Version);
        Assert.NotNull(csResult);
        Assert.NotNull(mdResult);
        Assert.NotSame(csResult, mdResult);
    }
}

