using AiKv.Context.Ranking;

namespace AiKv.Context.Chunking;

/// <summary>
/// A chunk of a file with line range and estimated tokens.
/// </summary>
public sealed record FileChunk
{
    public required string Path { get; init; }
    public required int StartLine { get; init; }
    public required int EndLine { get; init; }
    public required string Content { get; init; }
    public required int EstimatedTokens { get; init; }
}

/// <summary>
/// Chunking strategy: splits files into syntax-aware chunks when possible.
/// Version 1: line-window based with overlap control.
/// </summary>
public sealed class ChunkingStrategy
{
    public const string Version = "chunking-v1";

    private const int DefaultChunkSize = 200; // lines
    private const int DefaultOverlap = 10; // lines
    private const int MaxChunkSize = 500;

    /// <summary>
    /// Chunks a file's content based on the selection mode and token budget.
    /// </summary>
    public IReadOnlyList<FileChunk> Chunk(
        string filePath,
        string content,
        SelectionMode mode,
        int maxTokens)
    {
        var lines = content.Split('\n');
        var totalTokens = EstimateTokens(content);

        return mode switch
        {
            SelectionMode.Full => ChunkFull(filePath, content, lines, totalTokens, maxTokens),
            SelectionMode.Chunks => ChunkByLines(filePath, lines, maxTokens),
            SelectionMode.Outline => ChunkOutline(filePath, lines),
            SelectionMode.DeterministicSummary => ChunkSummary(filePath, lines),
            SelectionMode.Metadata => ChunkMetadata(filePath, lines, totalTokens),
            _ => ChunkByLines(filePath, lines, maxTokens),
        };
    }

    private static List<FileChunk> ChunkFull(string path, string content, string[] lines, int totalTokens, int maxTokens)
    {
        if (totalTokens <= maxTokens)
        {
            return [new FileChunk { Path = path, StartLine = 1, EndLine = lines.Length, Content = content, EstimatedTokens = totalTokens }];
        }
        // If too large, fall back to chunking
        return ChunkByLines(path, lines, maxTokens);
    }

    private static List<FileChunk> ChunkByLines(string path, string[] lines, int maxTokens)
    {
        var chunks = new List<FileChunk>();
        var chunkSize = DetermineChunkSize(lines.Length, maxTokens);
        var overlap = Math.Min(DefaultOverlap, chunkSize / 5);

        for (var i = 0; i < lines.Length; i += chunkSize - overlap)
        {
            var end = Math.Min(i + chunkSize, lines.Length);
            var content = string.Join('\n', lines.Skip(i).Take(end - i));
            var tokens = EstimateTokens(content);

            chunks.Add(new FileChunk
            {
                Path = path,
                StartLine = i + 1,
                EndLine = end,
                Content = content,
                EstimatedTokens = tokens,
            });

            if (end >= lines.Length) break;
        }
        return chunks;
    }

    private static List<FileChunk> ChunkOutline(string path, string[] lines)
    {
        // Extract only class/function/interface/namespace declarations
        var outlineLines = new List<string>();
        var lineNums = new List<int>();

        for (var i = 0; i < lines.Length; i++)
        {
            var trimmed = lines[i].TrimStart();
            if (IsDeclarationLine(trimmed))
            {
                outlineLines.Add($"{i + 1}: {trimmed}");
                lineNums.Add(i + 1);
            }
        }

        if (outlineLines.Count == 0) return [];

        var content = string.Join('\n', outlineLines);
        return
        [
            new FileChunk
            {
                Path = path,
                StartLine = lineNums.FirstOrDefault(),
                EndLine = lineNums.LastOrDefault(),
                Content = content,
                EstimatedTokens = EstimateTokens(content),
            },
        ];
    }

    private static List<FileChunk> ChunkSummary(string path, string[] lines)
    {
        // Deterministic summary: first N lines + imports + last N lines
        var head = lines.Take(Math.Min(20, lines.Length)).ToList();
        var imports = lines.Where(l => l.Contains("import ") || l.Contains("using ")).Take(10).ToList();
        var tail = lines.Skip(Math.Max(0, lines.Length - 10)).Take(10).ToList();

        var content = string.Join('\n', head.Concat(imports).Concat(tail).Distinct());
        return
        [
            new FileChunk
            {
                Path = path,
                StartLine = 1,
                EndLine = lines.Length,
                Content = content,
                EstimatedTokens = EstimateTokens(content),
            },
        ];
    }

    private static List<FileChunk> ChunkMetadata(string path, string[] lines, int totalTokens)
    {
        var content = $"Path: {path}\nLines: {lines.Length}\nEstTokens: {totalTokens}";
        return
        [
            new FileChunk
            {
                Path = path,
                StartLine = 0,
                EndLine = 0,
                Content = content,
                EstimatedTokens = EstimateTokens(content),
            },
        ];
    }

    private static int DetermineChunkSize(int totalLines, int maxTokens)
    {
        // Rough: ~4 chars per token, ~40 chars per line
        var tokensPerLine = 10;
        var linesForBudget = maxTokens / tokensPerLine;
        return Math.Clamp(linesForBudget, 50, MaxChunkSize);
    }

    private static bool IsDeclarationLine(string line) =>
        line.StartsWith("public ", StringComparison.Ordinal) ||
        line.StartsWith("private ", StringComparison.Ordinal) ||
        line.StartsWith("protected ", StringComparison.Ordinal) ||
        line.StartsWith("internal ", StringComparison.Ordinal) ||
        line.StartsWith("export ", StringComparison.Ordinal) ||
        line.StartsWith("class ", StringComparison.Ordinal) ||
        line.StartsWith("interface ", StringComparison.Ordinal) ||
        line.StartsWith("enum ", StringComparison.Ordinal) ||
        line.StartsWith("struct ", StringComparison.Ordinal) ||
        line.StartsWith("namespace ", StringComparison.Ordinal) ||
        line.StartsWith("def ", StringComparison.Ordinal) ||
        line.StartsWith("async def ", StringComparison.Ordinal) ||
        line.StartsWith("function ", StringComparison.Ordinal);

    /// <summary>
    /// Rough token estimation: ~4 chars per token.
    /// </summary>
    public static int EstimateTokens(string text) => text.Length / 4;
}

namespace AiKv.Context.Budget;

/// <summary>
/// Token budget configuration for a context build request.
/// Budget must distinguish model window, agent reserved, response reserved, target, hard limit, and safety margin.
/// </summary>
public sealed record TokenBudget
{
    public required int ModelContextWindow { get; init; }
    public required int AgentReservedTokens { get; init; }
    public required int ResponseReservedTokens { get; init; }
    public required int ContextTarget { get; init; }
    public required int ContextHardLimit { get; init; }
    public required int SafetyMargin { get; init; }
    public string? Tokenizer { get; init; }
    public string? TokenizerVersion { get; init; }

    /// <summary>
    /// The effective available budget: min(target, hardLimit - safetyMargin).
    /// </summary>
    public int EffectiveBudget => Math.Min(ContextTarget, ContextHardLimit - SafetyMargin);

    /// <summary>
    /// Whether a given token count fits within the hard limit.
    /// </summary>
    public bool FitsHardLimit(int tokens) => tokens <= ContextHardLimit - SafetyMargin;

    /// <summary>
    /// Whether a given token count fits within the effective budget.
    /// </summary>
    public bool FitsEffective(int tokens) => tokens <= EffectiveBudget;
}

/// <summary>
/// Default token budget policy (version 1).
/// </summary>
public static class DefaultTokenBudgetPolicy
{
    public const string Version = "budget-v1";

    /// <summary>
    /// Creates a budget for a standard 128K context window model.
    /// </summary>
    public static TokenBudget Create(
        int modelContextWindow = 128_000,
        int agentReservedTokens = 18_000,
        int responseReservedTokens = 12_000,
        double targetRatio = 0.625, // 80K of 128K
        double hardLimitRatio = 0.703, // 90K
        int safetyMargin = 10_000)
    {
        var contextTarget = (int)(modelContextWindow * targetRatio);
        var contextHardLimit = (int)(modelContextWindow * hardLimitRatio);

        return new TokenBudget
        {
            ModelContextWindow = modelContextWindow,
            AgentReservedTokens = agentReservedTokens,
            ResponseReservedTokens = responseReservedTokens,
            ContextTarget = contextTarget,
            ContextHardLimit = contextHardLimit,
            SafetyMargin = safetyMargin,
            Tokenizer = "rough-estimate",
            TokenizerVersion = "v1",
        };
    }
}

using AiKv.Context.Budget;
using AiKv.Context.Chunking;
using AiKv.Context.Ranking;
using AiKv.Core.Context;

namespace AiKv.Context.Selection;

/// <summary>
/// Result of the selection process: selected files with mode and token estimates.
/// </summary>
public sealed record SelectionResult
{
    public required IReadOnlyList<SelectedFileItem> SelectedFiles { get; init; }
    public required IReadOnlyList<ExcludedFileItem> ExcludedCandidates { get; init; }
    public required int TotalEstimatedTokens { get; init; }
    public required int BudgetTarget { get; init; }
    public required int BudgetHardLimit { get; init; }
    public required bool BudgetExceeded { get; init; }
}

public sealed record SelectedFileItem
{
    public required string Path { get; init; }
    public required string ContentHash { get; init; }
    public required SelectionMode Mode { get; init; }
    public required double Score { get; init; }
    public required IReadOnlyList<string> Reasons { get; init; }
    public required int EstimatedTokens { get; init; }
    public IReadOnlyList<LineRange>? Ranges { get; init; }
}

public sealed record ExcludedFileItem
{
    public required string Path { get; init; }
    public required double Score { get; init; }
    public required string Reason { get; init; }
}

/// <summary>
/// Selects files and chunks within the token budget.
/// Determines selection mode per file based on score and size.
/// </summary>
public sealed class SelectionEngine
{
    private readonly ChunkingStrategy _chunker = new();

    /// <summary>
    /// Selects files from ranked candidates within the token budget.
    /// </summary>
    public SelectionResult Select(
        IReadOnlyList<RankedCandidate> rankedCandidates,
        TokenBudget budget,
        Func<string, string> contentProvider,
        Func<string, string> hashProvider)
    {
        var selected = new List<SelectedFileItem>();
        var excluded = new List<ExcludedFileItem>();
        var totalTokens = 0;
        var effectiveBudget = budget.EffectiveBudget;

        foreach (var candidate in rankedCandidates)
        {
            var content = contentProvider(candidate.Path);
            var tokens = ChunkingStrategy.EstimateTokens(content);
            var mode = DetermineMode(candidate, tokens, budget);

            var (actualTokens, ranges) = ApplyMode(candidate.Path, content, mode, effectiveBudget - totalTokens);

            if (totalTokens + actualTokens > effectiveBudget)
            {
                // Try to fit as chunks
                if (mode != SelectionMode.Metadata)
                {
                    mode = SelectionMode.Chunks;
                    (actualTokens, ranges) = ApplyMode(candidate.Path, content, mode, effectiveBudget - totalTokens);

                    if (actualTokens == 0 || totalTokens + actualTokens > effectiveBudget)
                    {
                        mode = SelectionMode.Outline;
                        (actualTokens, ranges) = ApplyMode(candidate.Path, content, mode, effectiveBudget - totalTokens);
                    }
                }

                if (totalTokens + actualTokens > effectiveBudget)
                {
                    excluded.Add(new ExcludedFileItem
                    {
                        Path = candidate.Path,
                        Score = candidate.Score,
                        Reason = "Token 预算不足",
                    });
                    continue;
                }
            }

            selected.Add(new SelectedFileItem
            {
                Path = candidate.Path,
                ContentHash = hashProvider(candidate.Path),
                Mode = mode,
                Score = candidate.Score,
                Reasons = candidate.Reasons,
                EstimatedTokens = actualTokens,
                Ranges = ranges,
            });
            totalTokens += actualTokens;
        }

        return new SelectionResult
        {
            SelectedFiles = selected,
            ExcludedCandidates = excluded,
            TotalEstimatedTokens = totalTokens,
            BudgetTarget = budget.ContextTarget,
            BudgetHardLimit = budget.ContextHardLimit,
            BudgetExceeded = totalTokens > budget.ContextHardLimit,
        };
    }

    private static SelectionMode DetermineMode(RankedCandidate candidate, int tokens, TokenBudget budget)
    {
        // Small files: full
        if (tokens < 500) return SelectionMode.Full;

        // High score + medium: chunks
        if (candidate.Score > 0.5 && tokens < 5000) return SelectionMode.Chunks;

        // Medium score: outline
        if (candidate.Score > 0.3) return SelectionMode.Outline;

        // Low score: metadata
        return SelectionMode.Metadata;
    }

    private (int tokens, IReadOnlyList<LineRange>? ranges) ApplyMode(
        string path, string content, SelectionMode mode, int remainingBudget)
    {
        var chunks = _chunker.Chunk(path, content, mode, remainingBudget);

        if (chunks.Count == 0) return (0, null);

        var totalTokens = chunks.Sum(c => c.EstimatedTokens);
        var ranges = chunks
            .Where(c => c.StartLine > 0)
            .Select(c => new Core.Context.LineRange { StartLine = c.StartLine, EndLine = c.EndLine })
            .ToList();

        return (totalTokens, ranges.Count > 0 ? ranges : null);
    }
}

using AiKv.Context.Budget;
using AiKv.Context.Chunking;
