namespace AiKv.Context.Explain;

/// <summary>
/// Explanation of why a file was selected or excluded.
/// </summary>
public sealed record FileExplanation
{
    public required string Path { get; init; }
    public required bool Selected { get; init; }
    public required double Score { get; init; }
    public required IReadOnlyList<string> Reasons { get; init; }
    public required FeatureBreakdown? Features { get; init; }
    public required string? ExclusionReason { get; init; }
}

/// <summary>
/// Breakdown of feature scores.
/// </summary>
public sealed record FeatureBreakdown
{
    public double SymbolMatch { get; init; }
    public double TextMatch { get; init; }
    public double PathMatch { get; init; }
    public double GitDiff { get; init; }
    public double CurrentFileRelation { get; init; }
}

/// <summary>
/// Context explain: explains selection, score composition, budget eviction, potential misses.
/// </summary>
public static class ContextExplainer
{
    /// <summary>
    /// Produces explanations for selected and excluded files.
    /// </summary>
    public static IReadOnlyList<FileExplanation> Explain(ContextPackageManifest manifest)
    {
        var explanations = new List<FileExplanation>();

        foreach (var file in manifest.SelectedFiles)
        {
            explanations.Add(new FileExplanation
            {
                Path = file.Path,
                Selected = true,
                Score = file.Score,
                Reasons = file.Reasons,
                Features = null, // Features not stored in manifest
                ExclusionReason = null,
            });
        }

        foreach (var excluded in manifest.ExcludedCandidates)
        {
            explanations.Add(new FileExplanation
            {
                Path = excluded.Path,
                Selected = false,
                Score = excluded.Score,
                Reasons = [],
                Features = null,
                ExclusionReason = excluded.Reason,
            });
        }

        return explanations;
    }

    /// <summary>
    /// Detects potential missing context: high-score excluded files.
    /// </summary>
    public static IReadOnlyList<string> DetectPotentialMisses(ContextPackageManifest manifest)
    {
        return manifest.ExcludedCandidates
            .Where(e => e.Score > 0.3)
            .Select(e => e.Path)
            .ToList();
    }

    /// <summary>
    /// Budget summary for human-readable explanation.
    /// </summary>
    public static string BudgetSummary(ContextPackageManifest manifest)
    {
        var b = manifest.Budget;
        return $"已用 {b.ActualEstimate} / {b.ContextTarget} (硬限制 {b.ContextHardLimit}), 安全余量 {b.SafetyMargin}";
    }
}

using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using AiKv.Core.Context;

namespace AiKv.Context.Cache;

/// <summary>
/// Cache key components for a Context Package.
/// </summary>
public sealed record CacheKey
{
    public required string TaskHash { get; init; }
    public required string SnapshotHash { get; init; }
    public required string ProfileHash { get; init; }
    public required string BudgetHash { get; init; }
    public required string SecurityHash { get; init; }

    public string FullKey => $"{TaskHash}|{SnapshotHash}|{ProfileHash}|{BudgetHash}|{SecurityHash}";

    public static CacheKey Build(
        string task,
        string indexSnapshotId,
        string rankingProfileId,
        int rankingProfileVersion,
        int contextTarget,
        int contextHardLimit,
        string? securityPolicyVersion,
        string? ignoreRulesHash)
    {
        var taskHash = Hash(task);
        var snapshotHash = Hash(indexSnapshotId);
        var profileHash = Hash($"{rankingProfileId}:{rankingProfileVersion}");
        var budgetHash = Hash($"{contextTarget}:{contextHardLimit}");
        var securityHash = Hash($"{securityPolicyVersion ?? "none"}|{ignoreRulesHash ?? "none"}");

        return new CacheKey
        {
            TaskHash = taskHash,
            SnapshotHash = snapshotHash,
            ProfileHash = profileHash,
            BudgetHash = budgetHash,
            SecurityHash = securityHash,
        };
    }

    private static string Hash(string input)
    {
        var bytes = Encoding.UTF8.GetBytes(input);
        var hash = SHA256.HashData(bytes);
        return Convert.ToHexString(hash).ToLowerInvariant()[..16];
    }
}

/// <summary>
/// Cache for Context Package manifests.
/// Strictly bound to task, snapshot, profile, budget, security, and version.
/// </summary>
public sealed class ContextPackageCache
{
    private readonly Dictionary<string, ContextPackageManifest> _cache = new();

    public ContextPackageManifest? TryGet(CacheKey key)
        => _cache.TryGetValue(key.FullKey, out var manifest) ? manifest : null;

    public void Put(CacheKey key, ContextPackageManifest manifest)
        => _cache[key.FullKey] = manifest;

    public bool TryGetOrBuild(CacheKey key, Func<ContextPackageManifest> builder, out ContextPackageManifest manifest)
    {
        if (_cache.TryGetValue(key.FullKey, out var cached))
        {
            manifest = cached;
            return true;
        }
        manifest = builder();
        _cache[key.FullKey] = manifest;
        return false;
    }

    public void Invalidate(CacheKey key) => _cache.Remove(key.FullKey);
    public void Clear() => _cache.Clear();
    public int Count => _cache.Count;
}

using AiKv.Context.Budget;
using AiKv.Context.Cache;
using AiKv.Context.Engine;
using AiKv.Context.Expand;
