using System.Text.Json;
using System.Text.Json.Serialization;

namespace AiKv.Core.Feedback;

/// <summary>
/// Feedback from a client about a Context Package.
/// Used to improve ranking quality and detect misses.
/// </summary>
public sealed record ContextFeedback
{
    [JsonPropertyName("context_package_id")]
    public required string ContextPackageId { get; init; }

    [JsonPropertyName("client_id")]
    public string? ClientId { get; init; }

    [JsonPropertyName("client_version")]
    public string? ClientVersion { get; init; }

    [JsonPropertyName("model")]
    public string? Model { get; init; }

    [JsonPropertyName("files_actually_read")]
    public IReadOnlyList<string> FilesActuallyRead { get; init; } = [];

    [JsonPropertyName("additional_files_requested")]
    public IReadOnlyList<string> AdditionalFilesRequested { get; init; } = [];

    [JsonPropertyName("selected_files_used")]
    public IReadOnlyList<string> SelectedFilesUsed { get; init; } = [];

    [JsonPropertyName("selected_files_ignored")]
    public IReadOnlyList<string> SelectedFilesIgnored { get; init; } = [];

    [JsonPropertyName("patch_files")]
    public IReadOnlyList<string> PatchFiles { get; init; } = [];

    [JsonPropertyName("tests_run")]
    public IReadOnlyList<string> TestsRun { get; init; } = [];

    [JsonPropertyName("tests_passed")]
    public bool? TestsPassed { get; init; }

    [JsonPropertyName("task_completed")]
    public bool TaskCompleted { get; init; }

    [JsonPropertyName("missing_context_reported")]
    public bool MissingContextReported { get; init; }

    [JsonPropertyName("user_intervention_count")]
    public int UserInterventionCount { get; init; }

    [JsonPropertyName("total_workflow_input_tokens")]
    public int? TotalWorkflowInputTokens { get; init; }

    [JsonPropertyName("total_workflow_output_tokens")]
    public int? TotalWorkflowOutputTokens { get; init; }

    public static ContextFeedback? ParseJson(string json)
        => JsonSerializer.Deserialize<ContextFeedback>(json);
}

using AiKv.Core.Feedback;

namespace AiKv.Tests;

public class FeedbackProtocolTests
{
    [Fact]
    public void ContextFeedback_CanBeCreated_WithRequiredFields()
    {
        var fb = new ContextFeedback
        {
            ContextPackageId = "ctx_001",
            ClientId = "generic-agent",
            TaskCompleted = true,
        };

        Assert.Equal("ctx_001", fb.ContextPackageId);
        Assert.True(fb.TaskCompleted);
        Assert.Empty(fb.FilesActuallyRead);
    }

    [Fact]
    public void ContextFeedback_CanSerializeToJson()
    {
        var fb = new ContextFeedback
        {
            ContextPackageId = "ctx_001",
            ClientId = "test-agent",
            FilesActuallyRead = ["src/auth.ts", "src/token.ts"],
            AdditionalFilesRequested = ["src/utils.ts"],
            TaskCompleted = true,
            MissingContextReported = false,
            TotalWorkflowInputTokens = 15000,
            TotalWorkflowOutputTokens = 3000,
        };

        var json = JsonSerializer.Serialize(fb);
        var deserialized = ContextFeedback.ParseJson(json);

        Assert.NotNull(deserialized);
        Assert.Equal("ctx_001", deserialized!.ContextPackageId);
        Assert.Equal(2, deserialized.FilesActuallyRead.Count);
        Assert.Single(deserialized.AdditionalFilesRequested);
        Assert.True(deserialized.TaskCompleted);
        Assert.Equal(15000, deserialized.TotalWorkflowInputTokens);
    }

    [Fact]
    public void ContextFeedback_ParseJson_ShouldHandleInvalidInput()
    {
        var result = ContextFeedback.ParseJson("{}");
        // Empty JSON should produce a null result (required fields missing)
        // or a default instance depending on serialization options.
        // Either is acceptable for this test.
        Assert.True(result is null || result.ContextPackageId is null);
    }

    [Fact]
    public void ContextFeedback_DefaultCollections_ShouldBeEmpty()
    {
        var fb = new ContextFeedback { ContextPackageId = "ctx_test" };

        Assert.Empty(fb.FilesActuallyRead);
        Assert.Empty(fb.AdditionalFilesRequested);
        Assert.Empty(fb.SelectedFilesUsed);
        Assert.Empty(fb.SelectedFilesIgnored);
        Assert.Empty(fb.PatchFiles);
        Assert.Empty(fb.TestsRun);
    }
}

