using System.Text.Json.Serialization;

namespace AiKv.Core.Benchmarks;

/// <summary>
/// A benchmark task definition.
/// </summary>
public sealed record BenchmarkTask
{
    public required string Id { get; init; }
    public required string RepositoryId { get; init; }
    public required string Language { get; init; }
    public required string TaskDescription { get; init; }
    public required string CommitHash { get; init; }
    public IReadOnlyList<string> RequiredFiles { get; init; } = [];
    public IReadOnlyList<string> HelpfulFiles { get; init; } = [];
    public IReadOnlyList<string> DistractorFiles { get; init; } = [];
}

/// <summary>
/// Ground truth annotation for a benchmark task.
/// Required = must be present for task success.
/// Helpful = useful but not necessary.
/// Distractor = contains keywords but irrelevant.
/// </summary>
public sealed record GroundTruth
{
    public required string TaskId { get; init; }
    public required IReadOnlySet<string> RequiredFiles { get; init; }
    public required IReadOnlySet<string> HelpfulFiles { get; init; }
    public required IReadOnlySet<string> DistractorFiles { get; init; }
}

/// <summary>
/// Configuration for a benchmark run.
/// </summary>
public sealed record BenchmarkConfig
{
    public required string ModelId { get; init; }
    public required string AgentId { get; init; }
    public required string SystemPrompt { get; init; }
    public required int RunsPerTask { get; init; } = 3;
    public required bool ResetBetweenRuns { get; init; } = true;
    public required bool ShareBuildCache { get; init; } = false;
    public string? ToolPermissions { get; init; }
    public string? TestEnvironment { get; init; }
}

/// <summary>
/// Metrics for a single task run.
/// </summary>
public sealed record TaskMetrics
{
    public required string TaskId { get; init; }
    public required int RunNumber { get; init; }
    public required bool TaskCompleted { get; init; }
    public required int TotalInputTokens { get; init; }
    public required int TotalOutputTokens { get; init; }
    public required int Rounds { get; init; }
    public required double FileRecallAt10 { get; init; }
    public required double SymbolRecallAt10 { get; init; }
    public required double ContextPrecision { get; init; }
    public required bool MissingContext { get; init; }
    public required bool StaleContext { get; init; }
    public required IReadOnlyList<string> SelectedFiles { get; init; }
    public required IReadOnlyList<string> ActuallyReadFiles { get; init; }
}

/// <summary>
/// Aggregated metrics for a task across multiple runs.
/// </summary>
public sealed record AggregatedMetrics
{
    public required string TaskId { get; init; }
    public required double MeanFileRecall { get; init; }
    public required double StdDevFileRecall { get; init; }
    public required double WorstFileRecall { get; init; }
    public required double MeanPrecision { get; init; }
    public required double SuccessRate { get; init; }
    public required double MeanRounds { get; init; }
    public required double MeanInputTokens { get; init; }
    public required double MissingContextRate { get; init; }
    public required double StaleContextRate { get; init; }
    public required int RunCount { get; init; }
}

/// <summary>
/// Failure attribution category.
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter))]
public enum FailureCategory
{
    Retrieval,
    Ranking,
    Budget,
    AgentNonCompliance,
    ModelRandom,
    Environment,
    None,
}

/// <summary>
/// Attributed failure for a task.
/// </summary>
public sealed record FailureAttribution
{
    public required string TaskId { get; init; }
    public required FailureCategory Category { get; init; }
    public required string Description { get; init; }
}

/// <summary>
/// Phase gate thresholds.
/// </summary>
public sealed record PhaseGateThresholds
{
    public required double MinFileRecallAt10 { get; init; } = 0.90;
    public required double MaxMissingContextFailureRate { get; init; } = 0.10;
    public required double MinTestPassRatio { get; init; } = 0.95;
    public required double MinMeanTokenReduction { get; init; } = 0.20;
    public required double MinPositiveTokenTaskRatio { get; init; } = 0.60;
    public required double MaxStaleContextErrorRate { get; init; } = 0.01;
}

/// <summary>
/// Phase gate evaluation result.
/// </summary>
public sealed record PhaseGateResult
{
    public required bool Passed { get; init; }
    public required double ActualFileRecallAt10 { get; init; }
    public required double ActualMissingContextRate { get; init; }
    public required double ActualTestPassRatio { get; init; }
    public required double ActualMeanTokenReduction { get; init; }
    public required double ActualPositiveTokenTaskRatio { get; init; }
    public required double ActualStaleContextErrorRate { get; init; }
    public required IReadOnlyList<string> FailedGates { get; init; }
}

using AiKv.Core.Benchmarks;

namespace AiKv.Core.Benchmarks.Engine;

/// <summary>
/// Computes benchmark metrics from task results.
/// </summary>
public static class MetricsCalculator
{
    /// <summary>
    /// Computes metrics for a single task run.
    /// </summary>
    public static TaskMetrics ComputeTaskMetrics(
        string taskId,
        int runNumber,
        bool taskCompleted,
        int inputTokens,
        int outputTokens,
        int rounds,
        IReadOnlyList<string> selectedFiles,
        IReadOnlyList<string> actuallyRead,
        GroundTruth groundTruth)
    {
        var topK = selectedFiles.Take(10).ToHashSet(StringComparer.OrdinalIgnoreCase);
        var readSet = actuallyRead.ToHashSet(StringComparer.OrdinalIgnoreCase);

        var fileRecall = ComputeRecall(topK, groundTruth.RequiredFiles);
        var symbolRecall = ComputeRecall(readSet, groundTruth.RequiredFiles);
        var precision = ComputePrecision(topK, groundTruth);

        var missingContext = !groundTruth.RequiredFiles.All(r =>
            readSet.Contains(r) || selectedFiles.Any(s => s.Equals(r, StringComparison.OrdinalIgnoreCase)));

        return new TaskMetrics
        {
            TaskId = taskId,
            RunNumber = runNumber,
            TaskCompleted = taskCompleted,
            TotalInputTokens = inputTokens,
            TotalOutputTokens = outputTokens,
            Rounds = rounds,
            FileRecallAt10 = fileRecall,
            SymbolRecallAt10 = symbolRecall,
            ContextPrecision = precision,
            MissingContext = missingContext,
            StaleContext = false, // Requires version comparison (later)
            SelectedFiles = selectedFiles,
            ActuallyReadFiles = actuallyRead,
        };
    }

    /// <summary>
    /// Aggregates metrics across multiple runs of the same task.
    /// </summary>
    public static AggregatedMetrics Aggregate(string taskId, IReadOnlyList<TaskMetrics> runs)
    {
        if (runs.Count == 0)
            return new AggregatedMetrics
            {
                TaskId = taskId,
                RunCount = 0,
            };

        var recalls = runs.Select(r => r.FileRecallAt10).ToArray();
        var precisions = runs.Select(r => r.ContextPrecision).ToArray();
        var tokens = runs.Select(r => r.TotalInputTokens).ToArray();
        var rounds = runs.Select(r => (double)r.Rounds).ToArray();

        return new AggregatedMetrics
        {
            TaskId = taskId,
            MeanFileRecall = Mean(recalls),
            StdDevFileRecall = StdDev(recalls),
            WorstFileRecall = recalls.Min(),
            MeanPrecision = Mean(precisions),
            SuccessRate = (double)runs.Count(r => r.TaskCompleted) / runs.Count,
            MeanRounds = Mean(rounds),
            MeanInputTokens = Mean(tokens),
            MissingContextRate = (double)runs.Count(r => r.MissingContext) / runs.Count,
            StaleContextRate = (double)runs.Count(r => r.StaleContext) / runs.Count,
            RunCount = runs.Count,
        };
    }

    /// <summary>
    /// Computes Recall@K: fraction of required files in top-K.
    /// </summary>
    public static double ComputeRecall(IReadOnlySet<string> selected, IReadOnlySet<string> required)
    {
        if (required.Count == 0) return 1.0;
        var hits = required.Count(r => selected.Any(s => s.Equals(r, StringComparison.OrdinalIgnoreCase)));
        return (double)hits / required.Count;
    }

    /// <summary>
    /// Computes Precision: fraction of selected files that are required or helpful (not distractor).
    /// </summary>
    public static double ComputePrecision(IReadOnlySet<string> selected, GroundTruth groundTruth)
    {
        if (selected.Count == 0) return 0.0;
        var relevant = selected.Count(s =>
            groundTruth.RequiredFiles.Any(r => r.Equals(s, StringComparison.OrdinalIgnoreCase)) ||
            groundTruth.HelpfulFiles.Any(h => h.Equals(s, StringComparison.OrdinalIgnoreCase)));
        return (double)relevant / selected.Count;
    }

    /// <summary>
    /// Evaluates phase gate against thresholds.
    /// </summary>
    public static PhaseGateResult EvaluatePhaseGate(
        IReadOnlyList<AggregatedMetrics> allTasks,
        IReadOnlyList<AggregatedMetrics> baselineTasks,
        PhaseGateThresholds thresholds)
    {
        var actualRecall = allTasks.Any() ? allTasks.Average(t => t.MeanFileRecall) : 0;
        var actualMissingRate = allTasks.Any() ? allTasks.Average(t => t.MissingContextRate) : 1;
        var actualSuccessRate = allTasks.Any() ? allTasks.Average(t => t.SuccessRate) : 0;
        var actualStaleRate = allTasks.Any() ? allTasks.Average(t => t.StaleContextRate) : 1;

        var baselineTokens = baselineTasks.Any() ? baselineTasks.Average(t => t.MeanInputTokens) : 0;
        var aikvTokens = allTasks.Any() ? allTasks.Average(t => t.MeanInputTokens) : 0;
        var tokenReduction = baselineTokens > 0 ? (baselineTokens - aikvTokens) / baselineTokens : 0;

        var positiveTokenTasks = allTasks.Count(t =>
            baselineTasks.FirstOrDefault(b => b.TaskId == t.TaskId)?.MeanInputTokens is var baselineToken
            && baselineToken > 0
            && t.MeanInputTokens < baselineToken);
        var positiveRatio = allTasks.Count > 0 ? (double)positiveTokenTasks / allTasks.Count : 0;

        var failedGates = new List<string>();
        if (actualRecall < thresholds.MinFileRecallAt10)
            failedGates.Add($"File Recall@10: {actualRecall:F2} < {thresholds.MinFileRecallAt10}");
        if (actualMissingRate > thresholds.MaxMissingContextFailureRate)
            failedGates.Add($"Missing Context Rate: {actualMissingRate:F2} > {thresholds.MaxMissingContextFailureRate}");
        if (actualSuccessRate < thresholds.MinTestPassRatio)
            failedGates.Add($"Success Rate: {actualSuccessRate:F2} < {thresholds.MinTestPassRatio}");
        if (tokenReduction < thresholds.MinMeanTokenReduction)
            failedGates.Add($"Token Reduction: {tokenReduction:F2} < {thresholds.MinMeanTokenReduction}");
        if (positiveRatio < thresholds.MinPositiveTokenTaskRatio)
            failedGates.Add($"Positive Token Task Ratio: {positiveRatio:F2} < {thresholds.MinPositiveTokenTaskRatio}");
        if (actualStaleRate > thresholds.MaxStaleContextErrorRate)
            failedGates.Add($"Stale Context Rate: {actualStaleRate:F2} > {thresholds.MaxStaleContextErrorRate}");

        return new PhaseGateResult
        {
            Passed = failedGates.Count == 0,
            ActualFileRecallAt10 = actualRecall,
            ActualMissingContextRate = actualMissingRate,
            ActualTestPassRatio = actualSuccessRate,
            ActualMeanTokenReduction = tokenReduction,
            ActualPositiveTokenTaskRatio = positiveRatio,
            ActualStaleContextErrorRate = actualStaleRate,
            FailedGates = failedGates,
        };
    }

    /// <summary>
    /// Attributes a failure to a category based on metrics.
    /// </summary>
    public static FailureAttribution AttributeFailure(TaskMetrics metrics, GroundTruth groundTruth)
    {
        if (metrics.TaskCompleted) return new FailureAttribution
        {
            TaskId = metrics.TaskId,
            Category = FailureCategory.None,
            Description = "Task completed successfully",
        };

        if (metrics.FileRecallAt10 < 0.3)
            return new FailureAttribution
            {
                TaskId = metrics.TaskId,
                Category = FailureCategory.Retrieval,
                Description = $"Low recall ({metrics.FileRecallAt10:F2}): required files not found",
            };

        if (metrics.ContextPrecision < 0.3)
            return new FailureAttribution
            {
                TaskId = metrics.TaskId,
                Category = FailureCategory.Ranking,
                Description = $"Low precision ({metrics.ContextPrecision:F2}): too many irrelevant files",
            };

        if (metrics.MissingContext)
            return new FailureAttribution
            {
                TaskId = metrics.TaskId,
                Category = FailureCategory.Budget,
                Description = "Required files were excluded due to budget",
            };

        return new FailureAttribution
        {
            TaskId = metrics.TaskId,
            Category = FailureCategory.ModelRandom,
            Description = "Task failed despite good context; likely model randomness",
        };
    }

    private static double Mean(double[] values) =>
        values.Length == 0 ? 0 : values.Average();

    private static double StdDev(double[] values)
    {
        if (values.Length < 2) return 0;
        var mean = values.Average();
        var sumSq = values.Sum(v => (v - mean) * (v - mean));
        return Math.Sqrt(sumSq / values.Length);
    }
}

using System.Text.Json;
using AiKv.Core.Benchmarks;
using AiKv.Core.Benchmarks.Engine;

namespace AiKv.Core.Benchmarks.Reporting;

/// <summary>
/// Generates a public benchmark report.
/// </summary>
public static class ReportGenerator
{
    /// <summary>
    /// Generates a JSON report from aggregated metrics and phase gate result.
    /// </summary>
    public static string GenerateJson(
        BenchmarkConfig config,
        IReadOnlyList<AggregatedMetrics> taskMetrics,
        IReadOnlyList<FailureAttribution> failures,
        PhaseGateResult phaseGate)
    {
        var report = new
        {
            generatedAt = DateTimeOffset.UtcNow.ToString("O"),
            config = new
            {
                modelId = config.ModelId,
                agentId = config.AgentId,
                runsPerTask = config.RunsPerTask,
                resetBetweenRuns = config.ResetBetweenRuns,
            },
            summary = new
            {
                totalTasks = taskMetrics.Count,
                phaseGatePassed = phaseGate.Passed,
                meanFileRecallAt10 = taskMetrics.Any() ? taskMetrics.Average(t => t.MeanFileRecall) : 0,
                meanSuccessRate = taskMetrics.Any() ? taskMetrics.Average(t => t.SuccessRate) : 0,
                meanInputTokens = taskMetrics.Any() ? taskMetrics.Average(t => t.MeanInputTokens) : 0,
                missingContextRate = taskMetrics.Any() ? taskMetrics.Average(t => t.MissingContextRate) : 0,
            },
            phaseGate = new
            {
                passed = phaseGate.Passed,
                fileRecallAt10 = phaseGate.ActualFileRecallAt10,
                missingContextRate = phaseGate.ActualMissingContextRate,
                testPassRatio = phaseGate.ActualTestPassRatio,
                tokenReduction = phaseGate.ActualMeanTokenReduction,
                positiveTokenTaskRatio = phaseGate.ActualPositiveTokenTaskRatio,
                staleContextErrorRate = phaseGate.ActualStaleContextErrorRate,
                failedGates = phaseGate.FailedGates,
            },
            tasks = taskMetrics.Select(t => new
            {
                taskId = t.TaskId,
                meanFileRecall = Math.Round(t.MeanFileRecall, 4),
                stdDevFileRecall = Math.Round(t.StdDevFileRecall, 4),
                worstFileRecall = Math.Round(t.WorstFileRecall, 4),
                meanPrecision = Math.Round(t.MeanPrecision, 4),
                successRate = Math.Round(t.SuccessRate, 4),
                meanRounds = Math.Round(t.MeanRounds, 2),
                meanInputTokens = Math.Round(t.MeanInputTokens, 0),
                missingContextRate = Math.Round(t.MissingContextRate, 4),
                staleContextRate = Math.Round(t.StaleContextRate, 4),
                runCount = t.RunCount,
            }),
            failures = failures.Where(f => f.Category != FailureCategory.None).Select(f => new
            {
                taskId = f.TaskId,
                category = f.Category.ToString().ToLowerInvariant(),
                description = f.Description,
            }),
            limitations = new[]
            {
                "Tokenizer is rough estimate (chars/4)",
                "Model randomness may affect results",
                "Results are specific to the configured model and agent",
            },
        };

        return JsonSerializer.Serialize(report, new JsonSerializerOptions { WriteIndented = true });
    }
}

