using System.Text.Json.Serialization;

namespace AiKv.Core.Detection;

/// <summary>
/// Detected project component.
/// </summary>
public sealed record DetectedComponent
{
    public required string Id { get; init; }
    public required string Path { get; init; }
    public required string Language { get; init; }
    public string? Framework { get; init; }
    public string? BuildSystem { get; init; }
    public string? PackageManager { get; init; }
    public double Confidence { get; init; } = 1.0;
    public IReadOnlyList<string> Evidence { get; init; } = [];
}

/// <summary>
/// Result of project detection.
/// </summary>
public sealed record DetectionResult
{
    public required string RootPath { get; init; }
    public required IReadOnlyList<DetectedComponent> Components { get; init; }
    public required IReadOnlyDictionary<string, int> LanguageStats { get; init; }
    public required bool IsMonorepo { get; init; }
    public IReadOnlyList<string> MissingTools { get; init; } = [];
}

/// <summary>
/// Detector contract: evidence-based, read-only, with confidence.
/// </summary>
public interface IProjectDetector
{
    string Id { get; }
    IReadOnlySet<string> TriggerFiles { get; }
    DetectedComponent? Detect(string rootPath, IReadOnlyDictionary<string, string> triggerFileContents);
}

/// <summary>
/// Suggested initialization action (read-only, requires approval to execute).
/// </summary>
public sealed record InitAction
{
    public required string Command { get; init; }
    public required string Purpose { get; init; }
    public required string WorkingDirectory { get; init; }
    public required bool RequiresNetwork { get; init; }
    public required bool WritesToDisk { get; init; }
    public required bool MayRunScripts { get; init; }
    public required ApprovalLevel Approval { get; init; }
    public IReadOnlyList<string> Risks { get; init; } = [];
}

/// <summary>
/// Approval level for initialization actions.
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter))]
public enum ApprovalLevel
{
    Automatic,
    OneTimeApproval,
    EveryTimeApproval,
}

/// <summary>
/// Initialization plan: read-only detected, actions require approval.
/// </summary>
public sealed record InitializationPlan
{
    public required string RootPath { get; init; }
    public required IReadOnlyList<InitAction> Actions { get; init; }
    public required IReadOnlyList<string> DetectedComponents { get; init; }
    public required IReadOnlyList<string> MissingTools { get; init; }
}

using AiKv.Core.Detection;

namespace AiKv.Indexing.Detection;

/// <summary>
/// Detects Node.js projects: package.json, framework, package manager.
/// </summary>
public sealed class NodeDetector : IProjectDetector
{
    public string Id => "node";
    public IReadOnlySet<string> TriggerFiles => new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "package.json" };

    public DetectedComponent? Detect(string rootPath, IReadOnlyDictionary<string, string> triggerFileContents)
    {
        if (!triggerFileContents.TryGetValue("package.json", out var content)) return null;

        var evidence = new List<string> { "package.json found" };
        string? framework = null;
        string? packageManager = null;

        if (content.Contains("\"next\"", StringComparison.OrdinalIgnoreCase)) { framework = "Next.js"; evidence.Add("next dependency"); }
        else if (content.Contains("\"react\"", StringComparison.OrdinalIgnoreCase)) { framework = "React"; evidence.Add("react dependency"); }
        else if (content.Contains("\"vue\"", StringComparison.OrdinalIgnoreCase)) { framework = "Vue"; evidence.Add("vue dependency"); }
        else if (content.Contains("\"express\"", StringComparison.OrdinalIgnoreCase)) { framework = "Express"; evidence.Add("express dependency"); }

        if (rootPath.Contains("pnpm-lock", StringComparison.OrdinalIgnoreCase) || File.Exists(Path.Combine(rootPath, "pnpm-lock.yaml")))
            packageManager = "pnpm";
        else if (File.Exists(Path.Combine(rootPath, "yarn.lock")))
            packageManager = "yarn";
        else
            packageManager = "npm";

        return new DetectedComponent
        {
            Id = "node-" + Path.GetFileName(rootPath),
            Path = rootPath,
            Language = "typescript",
            Framework = framework,
            BuildSystem = "npm-scripts",
            PackageManager = packageManager,
            Evidence = evidence,
        };
    }
}

/// <summary>
/// Detects Python projects: pyproject.toml, requirements.txt, setup.py.
/// </summary>
public sealed class PythonDetector : IProjectDetector
{
    public string Id => "python";
    public IReadOnlySet<string> TriggerFiles => new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        "pyproject.toml", "requirements.txt", "setup.py", "Pipfile"
    };

    public DetectedComponent? Detect(string rootPath, IReadOnlyDictionary<string, string> triggerFileContents)
    {
        var evidence = new List<string>();
        string? packageManager = null;

        if (triggerFileContents.ContainsKey("pyproject.toml")) { evidence.Add("pyproject.toml"); packageManager = "pip/poetry"; }
        if (triggerFileContents.ContainsKey("requirements.txt")) { evidence.Add("requirements.txt"); packageManager ??= "pip"; }
        if (triggerFileContents.ContainsKey("setup.py")) { evidence.Add("setup.py"); packageManager ??= "setuptools"; }
        if (triggerFileContents.ContainsKey("Pipfile")) { evidence.Add("Pipfile"); packageManager = "pipenv"; }

        if (evidence.Count == 0) return null;

        return new DetectedComponent
        {
            Id = "python-" + Path.GetFileName(rootPath),
            Path = rootPath,
            Language = "python",
            BuildSystem = packageManager,
            PackageManager = packageManager,
            Evidence = evidence,
        };
    }
}

/// <summary>
/// Detects .NET projects: *.sln, *.csproj, global.json.
/// </summary>
public sealed class DotNetDetector : IProjectDetector
{
    public string Id => "dotnet";
    public IReadOnlySet<string> TriggerFiles => new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        "global.json", "*.sln", "*.csproj"
    };

    public DetectedComponent? Detect(string rootPath, IReadOnlyDictionary<string, string> triggerFileContents)
    {
        var evidence = new List<string>();

        if (triggerFileContents.ContainsKey("global.json")) evidence.Add("global.json");
        if (triggerFileContents.Keys.Any(k => k.EndsWith(".sln", StringComparison.OrdinalIgnoreCase))) evidence.Add("*.sln");
        if (triggerFileContents.Keys.Any(k => k.EndsWith(".csproj", StringComparison.OrdinalIgnoreCase))) evidence.Add("*.csproj");

        if (evidence.Count == 0) return null;

        return new DetectedComponent
        {
            Id = "dotnet-" + Path.GetFileName(rootPath),
            Path = rootPath,
            Language = "csharp",
            Framework = "ASP.NET Core",
            BuildSystem = "MSBuild",
            PackageManager = "NuGet",
            Evidence = evidence,
        };
    }
}

/// <summary>
/// Detects Go, Rust, Java/Kotlin, C/C++ projects.
/// </summary>
public sealed class GoDetector : IProjectDetector
{
    public string Id => "go";
    public IReadOnlySet<string> TriggerFiles => new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "go.mod" };

    public DetectedComponent? Detect(string rootPath, IReadOnlyDictionary<string, string> triggerFileContents)
    {
        if (!triggerFileContents.ContainsKey("go.mod")) return null;
        return new DetectedComponent
        {
            Id = "go-" + Path.GetFileName(rootPath), Path = rootPath, Language = "go",
            BuildSystem = "Go Modules", PackageManager = "go", Evidence = ["go.mod found"],
        };
    }
}

public sealed class RustDetector : IProjectDetector
{
    public string Id => "rust";
    public IReadOnlySet<string> TriggerFiles => new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "Cargo.toml" };

    public DetectedComponent? Detect(string rootPath, IReadOnlyDictionary<string, string> triggerFileContents)
    {
        if (!triggerFileContents.ContainsKey("Cargo.toml")) return null;
        return new DetectedComponent
        {
            Id = "rust-" + Path.GetFileName(rootPath), Path = rootPath, Language = "rust",
            BuildSystem = "Cargo", PackageManager = "cargo", Evidence = ["Cargo.toml found"],
        };
    }
}

public sealed class JavaDetector : IProjectDetector
{
    public string Id => "java";
    public IReadOnlySet<string> TriggerFiles => new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        "pom.xml", "build.gradle", "build.gradle.kts", "settings.gradle"
    };

    public DetectedComponent? Detect(string rootPath, IReadOnlyDictionary<string, string> triggerFileContents)
    {
        var evidence = new List<string>();
        string? buildSystem = null;

        if (triggerFileContents.ContainsKey("pom.xml")) { evidence.Add("pom.xml"); buildSystem = "Maven"; }
        if (triggerFileContents.ContainsKey("build.gradle") || triggerFileContents.ContainsKey("build.gradle.kts"))
        { evidence.Add("build.gradle"); buildSystem ??= "Gradle"; }

        if (evidence.Count == 0) return null;

        return new DetectedComponent
        {
            Id = "java-" + Path.GetFileName(rootPath), Path = rootPath, Language = "java",
            BuildSystem = buildSystem, PackageManager = buildSystem, Evidence = evidence,
        };
    }
}

/// <summary>
/// Detects Unity, Unreal, Flutter projects.
/// </summary>
public sealed class UnityDetector : IProjectDetector
{
    public string Id => "unity";
    public IReadOnlySet<string> TriggerFiles => new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        "ProjectSettings/ProjectVersion.txt"
    };

    public DetectedComponent? Detect(string rootPath, IReadOnlyDictionary<string, string> triggerFileContents)
    {
        var key = triggerFileContents.Keys.FirstOrDefault(k =>
            k.Replace('\\', '/').Contains("ProjectSettings/ProjectVersion.txt", StringComparison.OrdinalIgnoreCase));
        if (key is null) return null;

        var version = "unknown";
        if (triggerFileContents[key].Contains("m_EditorVersion:", StringComparison.OrdinalIgnoreCase))
        {
            var idx = triggerFileContents[key].IndexOf("m_EditorVersion:");
            version = triggerFileContents[key][(idx + 17)..].Trim().Split('\n')[0].Trim();
        }

        return new DetectedComponent
        {
            Id = "unity-" + Path.GetFileName(rootPath), Path = rootPath, Language = "csharp",
            Framework = $"Unity {version}", BuildSystem = "Unity Editor", Evidence = ["ProjectVersion.txt found"],
        };
    }
}

public sealed class FlutterDetector : IProjectDetector
{
    public string Id => "flutter";
    public IReadOnlySet<string> TriggerFiles => new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "pubspec.yaml" };

    public DetectedComponent? Detect(string rootPath, IReadOnlyDictionary<string, string> triggerFileContents)
    {
        if (!triggerFileContents.ContainsKey("pubspec.yaml")) return null;
        return new DetectedComponent
        {
            Id = "flutter-" + Path.GetFileName(rootPath), Path = rootPath, Language = "dart",
            Framework = "Flutter", BuildSystem = "pub", Evidence = ["pubspec.yaml found"],
        };
    }
}

/// <summary>
/// Detects Docker, Terraform, CI config files.
/// </summary>
public sealed class DockerDetector : IProjectDetector
{
    public string Id => "docker";
    public IReadOnlySet<string> TriggerFiles => new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        "Dockerfile", "docker-compose.yml", "docker-compose.yaml", "compose.yaml"
    };

    public DetectedComponent? Detect(string rootPath, IReadOnlyDictionary<string, string> triggerFileContents)
    {
        var evidence = triggerFileContents.Keys
            .Where(k => TriggerFiles.Contains(k))
            .Select(k => $"{k} found")
            .ToList();

        if (evidence.Count == 0) return null;

        return new DetectedComponent
        {
            Id = "docker-" + Path.GetFileName(rootPath), Path = rootPath, Language = "dockerfile",
            BuildSystem = "Docker", Confidence = 0.8, Evidence = evidence,
        };
    }
}

using AiKv.Core.Detection;

namespace AiKv.Indexing.Detection;

/// <summary>
/// Runs all registered detectors against a directory.
/// Collects evidence, computes language stats, and detects monorepo structure.
/// </summary>
public sealed class ProjectDetectionEngine
{
    private readonly List<IProjectDetector> _detectors;

    public ProjectDetectionEngine(IEnumerable<IProjectDetector>? detectors = null)
    {
        _detectors = detectors?.ToList() ??
        [
            new NodeDetector(),
            new PythonDetector(),
            new DotNetDetector(),
            new GoDetector(),
            new RustDetector(),
            new JavaDetector(),
            new UnityDetector(),
            new FlutterDetector(),
            new DockerDetector(),
        ];
    }

    /// <summary>
    /// Detects all components in a directory tree. Read-only — never executes scripts.
    /// </summary>
    public DetectionResult Detect(string rootPath)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(rootPath);
        if (!Directory.Exists(rootPath))
            throw new DirectoryNotFoundException($"Directory not found: {rootPath}");

        var components = new List<DetectedComponent>();
        var languageStats = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

        // Scan top-level and one level deep for component roots
        var searchDirs = new List<string> { rootPath };
        searchDirs.AddRange(Directory.GetDirectories(rootPath, "*", SearchOption.TopDirectoryOnly)
            .Where(d => !ShouldSkipDir(d)));

        foreach (var dir in searchDirs.Distinct())
        {
            var triggerFiles = CollectTriggerFiles(dir);
            if (triggerFiles.Count == 0) continue;

            foreach (var detector in _detectors)
            {
                var component = detector.Detect(dir, triggerFiles);
                if (component is not null)
                {
                    components.Add(component);
                    var lang = component.Language;
                    languageStats[lang] = languageStats.GetValueOrDefault(lang) + 1;
                    break; // First match wins per directory
                }
            }
        }

        // Also count files by extension for language stats
        if (languageStats.Count == 0)
        {
            foreach (var file in Directory.EnumerateFiles(rootPath, "*.*", SearchOption.AllDirectories)
                .Take(500))
            {
                var ext = Path.GetExtension(file).ToLowerInvariant();
                var lang = ext switch
                {
                    ".cs" => "csharp", ".ts" or ".tsx" => "typescript",
                    ".js" or ".jsx" => "javascript", ".py" => "python",
                    ".go" => "go", ".rs" => "rust", ".java" => "java",
                    ".cpp" or ".cc" or ".cxx" => "cpp", ".c" => "c",
                    ".rb" => "ruby", ".php" => "php",
                    _ => null,
                };
                if (lang is not null)
                    languageStats[lang] = languageStats.GetValueOrDefault(lang) + 1;
            }
        }

        var isMonorepo = components.Count > 1 &&
            components.Select(c => c.Language).Distinct().Count() >= 2;

        return new DetectionResult
        {
            RootPath = rootPath,
            Components = components,
            LanguageStats = languageStats,
            IsMonorepo = isMonorepo,
        };
    }

    /// <summary>
    /// Generates an initialization plan from detection results.
    /// All actions require approval — detection is read-only.
    /// </summary>
    public InitializationPlan GeneratePlan(DetectionResult result)
    {
        var actions = new List<InitAction>();

        foreach (var comp in result.Components)
        {
            var (cmd, purpose, needsNet, writes, runsScripts, risks) = comp.PackageManager switch
            {
                "npm" => ("npm install", "Install Node.js dependencies", true, true, true,
                    ["May execute postinstall scripts", "Writes to node_modules"]),
                "pnpm" => ("pnpm install", "Install Node.js dependencies (pnpm)", true, true, true,
                    ["May execute postinstall scripts", "Writes to node_modules"]),
                "yarn" => ("yarn install", "Install Node.js dependencies (yarn)", true, true, true,
                    ["May execute postinstall scripts", "Writes to node_modules"]),
                "pip" => ("pip install -r requirements.txt", "Install Python dependencies", true, true, false,
                    ["Writes to site-packages"]),
                "pip/poetry" => ("poetry install", "Install Python dependencies (Poetry)", true, true, false,
                    ["Writes to virtual environment"]),
                "NuGet" => ("dotnet restore", "Restore NuGet packages", true, true, false,
                    ["Writes to obj/ directory"]),
                "go" => ("go mod download", "Download Go modules", true, true, false, []),
                "cargo" => ("cargo fetch", "Download Rust crates", true, true, false, []),
                "Maven" => ("mvn install", "Install Maven dependencies", true, true, false,
                    ["May compile code", "Writes to target/"]),
                "Gradle" => ("./gradlew build", "Build Gradle project", true, true, true,
                    ["May execute Gradle scripts", "Writes to build/"]),
                "pub" => ("flutter pub get", "Install Flutter dependencies", true, true, false, []),
                _ => (null, null, false, false, false, Array.Empty<string>()),
            };

            if (cmd is not null)
            {
                actions.Add(new InitAction
                {
                    Command = cmd,
                    Purpose = purpose!,
                    WorkingDirectory = comp.Path,
                    RequiresNetwork = needsNet,
                    WritesToDisk = writes,
                    MayRunScripts = runsScripts,
                    Approval = runsScripts ? ApprovalLevel.EveryTimeApproval : ApprovalLevel.OneTimeApproval,
                    Risks = risks,
                });
            }
        }

        return new InitializationPlan
        {
            RootPath = result.RootPath,
            Actions = actions,
            DetectedComponents = result.Components.Select(c => $"{c.Language} ({c.Framework ?? c.BuildSystem ?? "unknown"}) at {c.Path}").ToList(),
            MissingTools = result.MissingTools,
        };
    }

    private static Dictionary<string, string> CollectTriggerFiles(string dir)
    {
        var result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var file in Directory.EnumerateFiles(dir, "*.*", SearchOption.TopDirectoryOnly))
        {
            var name = Path.GetFileName(file);
            result[name] = File.Exists(file) ? File.ReadAllText(file) : "";
        }

        // Check for nested trigger files like ProjectSettings/ProjectVersion.txt
        var projectSettings = Path.Combine(dir, "ProjectSettings", "ProjectVersion.txt");
        if (File.Exists(projectSettings))
            result["ProjectSettings/ProjectVersion.txt"] = File.ReadAllText(projectSettings);

        // Check for *.sln and *.csproj
        foreach (var sln in Directory.EnumerateFiles(dir, "*.sln", SearchOption.TopDirectoryOnly))
            result[Path.GetFileName(sln)] = File.ReadAllText(sln);
        foreach (var csproj in Directory.EnumerateFiles(dir, "*.csproj", SearchOption.TopDirectoryOnly))
            result[Path.GetFileName(csproj)] = File.ReadAllText(csproj);

        return result;
    }

    private static bool ShouldSkipDir(string dir)
    {
        var name = Path.GetFileName(dir);
        return name.StartsWith('.') || name.Equals("node_modules", StringComparison.OrdinalIgnoreCase) ||
               name.Equals("bin", StringComparison.OrdinalIgnoreCase) ||
               name.Equals("obj", StringComparison.OrdinalIgnoreCase) ||
               name.Equals("target", StringComparison.OrdinalIgnoreCase) ||
               name.Equals("dist", StringComparison.OrdinalIgnoreCase) ||
               name.Equals("build", StringComparison.OrdinalIgnoreCase) ||
               name.Equals("vendor", StringComparison.OrdinalIgnoreCase);
    }
}

