using System.Net;
using System.Text.Json;

namespace AiKv.Core.Gateway;

/// <summary>
/// Configuration for the Gateway process.
/// </summary>
public sealed record GatewayConfig
{
    public required string ProviderBaseUrl { get; init; }
    public required string ProviderApiKey { get; init; }
    public int Port { get; init; } = 5218;
    public string Host { get; init; } = "127.0.0.1";
    public bool EnableCache { get; init; } = true;
    public bool EnableSingleFlight { get; init; } = true;
    public int MaxRequestSizeBytes { get; init; } = 10 * 1024 * 1024;
}

/// <summary>
/// Model usage statistics for a request.
/// </summary>
public sealed record ModelUsage
{
    public required int PromptTokens { get; init; }
    public required int CompletionTokens { get; init; }
    public required int TotalTokens { get; init; }
    public bool IsEstimated { get; init; }
}

/// <summary>
/// A logged model request with metadata.
/// </summary>
public sealed record ModelRequestLog
{
    public required DateTimeOffset Timestamp { get; init; }
    public required string Model { get; init; }
    public required string Endpoint { get; init; }
    public required ModelUsage Usage { get; init; }
    public bool Cached { get; init; }
    public bool Streaming { get; init; }
    public string? WorkspaceId { get; init; }
    public string? ContextPackageId { get; init; }
    public int StatusCode { get; init; }
    public long LatencyMs { get; init; }
}

/// <summary>
/// Raw exact cache entry: stores the exact request hash and response.
/// Only for safe, no-tool-call, deterministic requests.
/// </summary>
public sealed record RawCacheEntry
{
    public required string RequestHash { get; init; }
    public required string ResponseBody { get; init; }
    public required DateTimeOffset CreatedAt { get; init; }
    public required string Model { get; init; }
    public bool HasToolCalls { get; init; }
    public bool HasFunctionCalls { get; init; }
}

/// <summary>
/// Statistics for Gateway operations.
/// </summary>
public sealed record GatewayStats
{
    public required long TotalRequests { get; init; }
    public required long CacheHits { get; init; }
    public required long CacheMisses { get; init; }
    public required double CacheHitRate { get; init; }
    public required long TotalPromptTokens { get; init; }
    public required long TotalCompletionTokens { get; init; }
    public required long CachedTokensSaved { get; init; }
    public required double AvgLatencyMs { get; init; }
}

/// <summary>
/// Checks if a request is safe to cache (no tools, no functions, no high temperature).
/// </summary>
public static class CacheSafetyChecker
{
    public static bool IsCacheable(string requestBody, string model)
    {
        using var doc = JsonDocument.Parse(requestBody);
        var root = doc.RootElement;

        // Reject if tools or functions are present
        if (root.TryGetProperty("tools", out _) || root.TryGetProperty("functions", out _))
            return false;

        // Reject if temperature is too high
        if (root.TryGetProperty("temperature", out var temp) && temp.GetDouble() > 0.7)
            return false;

        // Reject if stream is true (streaming responses not cached in v1)
        if (root.TryGetProperty("stream", out var stream) && stream.GetBoolean())
            return false;

        // Reject if no-cache header is present
        if (root.TryGetProperty("metadata", out var meta) &&
            meta.TryGetProperty("no_cache", out var nc) && nc.GetBoolean())
            return false;

        return true;
    }

    public static bool HasToolCalls(string responseBody)
    {
        try
        {
            using var doc = JsonDocument.Parse(responseBody);
            if (doc.RootElement.TryGetProperty("choices", out var choices))
            {
                foreach (var choice in choices.EnumerateArray())
                {
                    if (choice.TryGetProperty("message", out var msg) &&
                        msg.TryGetProperty("tool_calls", out _))
                        return true;
                }
            }
            return false;
        }
        catch { return true; } // Treat unparseable as unsafe
    }
}

/// <summary>
/// SingleFlight: deduplicates concurrent identical requests.
/// Only for safe (no-tool-call) requests.
/// </summary>
public sealed class SingleFlight
{
    private readonly Dictionary<string, Task<string>> _inFlight = new();
    private readonly Lock _lock = new();

    public async Task<string> ExecuteAsync(string key, Func<Task<string>> factory)
    {
        Task<string>? existing;
        lock (_lock)
        {
            if (_inFlight.TryGetValue(key, out existing))
                return await existing;
        }

        var task = factory();
        lock (_lock) { _inFlight[key] = task; }

        try
        {
            return await task;
        }
        finally
        {
            lock (_lock) { _inFlight.Remove(key); }
        }
    }

    public int InFlightCount
    {
        get { lock (_lock) return _inFlight.Count; }
    }
}

using System.Text.Json;
using AiKv.Core.Caching;
using AiKv.Core.Gateway;

namespace AiKv.Tests;

public class GatewayTests
{
    [Fact]
    public void CacheSafetyChecker_IsCacheable_ShouldAcceptSimpleRequest()
    {
        var body = """{"model":"gpt-4","messages":[{"role":"user","content":"hello"}],"temperature":0.3}""";

        Assert.True(CacheSafetyChecker.IsCacheable(body, "gpt-4"));
    }

    [Fact]
    public void CacheSafetyChecker_IsCacheable_ShouldRejectTools()
    {
        var body = """{"model":"gpt-4","messages":[],"tools":[{"type":"function","function":{"name":"test"}}]}""";

        Assert.False(CacheSafetyChecker.IsCacheable(body, "gpt-4"));
    }

    [Fact]
    public void CacheSafetyChecker_IsCacheable_ShouldRejectHighTemperature()
    {
        var body = """{"model":"gpt-4","messages":[],"temperature":1.0}""";

        Assert.False(CacheSafetyChecker.IsCacheable(body, "gpt-4"));
    }

    [Fact]
    public void CacheSafetyChecker_IsCacheable_ShouldRejectStreaming()
    {
        var body = """{"model":"gpt-4","messages":[],"stream":true}""";

        Assert.False(CacheSafetyChecker.IsCacheable(body, "gpt-4"));
    }

    [Fact]
    public void CacheSafetyChecker_IsCacheable_ShouldRespectNoCacheFlag()
    {
        var body = """{"model":"gpt-4","messages":[],"metadata":{"no_cache":true}}""";

        Assert.False(CacheSafetyChecker.IsCacheable(body, "gpt-4"));
    }

    [Fact]
    public void CacheSafetyChecker_HasToolCalls_ShouldDetectToolCalls()
    {
        var body = """{"choices":[{"message":{"tool_calls":[{"id":"1","type":"function"}]}}]}""";

        Assert.True(CacheSafetyChecker.HasToolCalls(body));
    }

    [Fact]
    public void CacheSafetyChecker_HasToolCalls_ShouldReturnFalseForNormalResponse()
    {
        var body = """{"choices":[{"message":{"content":"hello"}}]}""";

        Assert.False(CacheSafetyChecker.HasToolCalls(body));
    }

    [Fact]
    public async Task SingleFlight_ShouldDeduplicateConcurrentRequests()
    {
        var sf = new SingleFlight();
        var callCount = 0;

        var task1 = sf.ExecuteAsync("key1", async () =>
        {
            await Task.Delay(50);
            Interlocked.Increment(ref callCount);
            return "result";
        });

        var task2 = sf.ExecuteAsync("key1", async () =>
        {
            Interlocked.Increment(ref callCount);
            return "should-not-run";
        });

        var results = await Task.WhenAll(task1, task2);

        Assert.Equal("result", results[0]);
        Assert.Equal("result", results[1]);
        Assert.Equal(1, callCount);
    }

    [Fact]
    public async Task SingleFlight_ShouldAllowDifferentKeys()
    {
        var sf = new SingleFlight();

        var r1 = await sf.ExecuteAsync("key1", () => Task.FromResult("result1"));
        var r2 = await sf.ExecuteAsync("key2", () => Task.FromResult("result2"));

        Assert.Equal("result1", r1);
        Assert.Equal("result2", r2);
    }

    [Fact]
    public void GatewayConfig_Default_ShouldBindLoopback()
    {
        var config = new GatewayConfig
        {
            ProviderBaseUrl = "https://api.openai.com",
            ProviderApiKey = "sk-test",
        };

        Assert.Equal("127.0.0.1", config.Host);
        Assert.Equal(5218, config.Port);
        Assert.True(config.EnableCache);
    }

    [Fact]
    public void ModelUsage_ShouldTrackTokens()
    {
        var usage = new ModelUsage
        {
            PromptTokens = 1000,
            CompletionTokens = 500,
            TotalTokens = 1500,
            IsEstimated = false,
        };

        Assert.Equal(1500, usage.TotalTokens);
        Assert.False(usage.IsEstimated);
    }

    [Fact]
    public void GatewayStats_ShouldCalculateHitRate()
    {
        var stats = new GatewayStats
        {
            TotalRequests = 100,
            CacheHits = 30,
            CacheMisses = 70,
            CacheHitRate = 0.3,
            TotalPromptTokens = 500000,
            TotalCompletionTokens = 100000,
            CachedTokensSaved = 150000,
            AvgLatencyMs = 850.5,
        };

        Assert.Equal(0.3, stats.CacheHitRate);
        Assert.Equal(150000, stats.CachedTokensSaved);
    }

    [Fact]
    public void RawCacheEntry_ShouldStoreResponseMetadata()
    {
        var entry = new RawCacheEntry
        {
            RequestHash = "sha256:abc",
            ResponseBody = """{"choices":[]}""",
            CreatedAt = DateTimeOffset.UtcNow,
            Model = "gpt-4",
            HasToolCalls = false,
            HasFunctionCalls = false,
        };

        Assert.False(entry.HasToolCalls);
        Assert.False(entry.HasFunctionCalls);
    }
}

