    [Fact]
    public void OpenAiCompatibleProvider_CanBeInstantiated()
    {
        var provider = new OpenAiCompatibleProvider("test", "https://api.test.com");
        Assert.Equal("test", provider.Id);
        Assert.Equal("1.0", provider.Version);
