using System.Text.Json.Serialization;

namespace AiKv.Core.Ecosystem;

/// <summary>
/// Plugin manifest with signature and permissions.
/// </summary>
public sealed record PluginManifest
{
    public required string Id { get; init; }
    public required string Name { get; init; }
    public required string Version { get; init; }
    public required string Author { get; init; }
    public string? Signature { get; init; }
    public bool IsSigned { get; init; }
    public bool IsEnabled { get; init; } = false;
    public required IReadOnlyList<PluginPermission> Permissions { get; init; }
    public string? Description { get; init; }
    public string? Homepage { get; init; }
}

/// <summary>
/// Permissions a plugin can request.
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter))]
public enum PluginPermission
{
    ReadFiles,
    WriteFiles,
    ExecuteProcess,
    NetworkAccess,
    ReadWorkspace,
    ModifyWorkspace,
    AccessCredentials,
    ExportContext,
}

/// <summary>
/// Team/enterprise sharing configuration.
/// </summary>
public sealed record TeamConfig
{
    public required string TeamId { get; init; }
    public required string Name { get; init; }
    public IReadOnlyList<string> SharedWorkspaceIds { get; init; } = [];
    public IReadOnlyList<string> MemberIds { get; init; } = [];
    public bool EnableSharedIndex { get; init; }
    public bool EnableAuditLog { get; init; }
}

/// <summary>
/// Enterprise policy configuration.
/// </summary>
public sealed record EnterprisePolicy
{
    public required string PolicyId { get; init; }
    public bool ForceCloudSendRestricted { get; init; }
    public bool ForceAuditLog { get; init; }
    public IReadOnlyList<string> AllowedProviders { get; init; } = [];
    public decimal? MaxDailyBudgetUsd { get; init; }
    public bool DisableThirdPartyPlugins { get; init; }
    public bool RequirePluginSignature { get; init; }
    public bool AllowIntranetDeployment { get; init; }
}

/// <summary>
/// Update channel configuration.
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter))]
public enum UpdateChannel
{
    Stable,
    Beta,
    Alpha,
    Nightly,
}

/// <summary>
/// Auto-update configuration.
/// </summary>
public sealed record UpdateConfig
{
    public required UpdateChannel Channel { get; init; }
    public bool AutoCheck { get; init; } = true;
    public bool AutoDownload { get; init; }
    public bool AutoInstall { get; init; }
    public bool BackupBeforeUpdate { get; init; } = true;
    public TimeSpan CheckInterval { get; init; } = TimeSpan.FromHours(12);
}

/// <summary>
/// Result of an update check.
/// </summary>
public sealed record UpdateCheckResult
{
    public required bool UpdateAvailable { get; init; }
    public string? LatestVersion { get; init; }
    public string? CurrentVersion { get; init; }
    public DateTimeOffset? ReleaseDate { get; init; }
    public string? ReleaseNotes { get; init; }
    public string? DownloadUrl { get; init; }
    public string? Checksum { get; init; }
}

using AiKv.Core.Ecosystem;

namespace AiKv.Tests;

public class EcosystemTests
{
    [Fact]
    public void PluginManifest_ShouldDefaultDisabled()
    {
        var manifest = new PluginManifest
        {
            Id = "test-plugin",
            Name = "Test Plugin",
            Version = "1.0.0",
            Author = "test",
            IsSigned = false,
            Permissions = [PluginPermission.ReadFiles],
        };

        Assert.False(manifest.IsEnabled);
        Assert.False(manifest.IsSigned);
        Assert.Single(manifest.Permissions);
    }

    [Fact]
    public void PluginManifest_Signed_ShouldHaveSignature()
    {
        var manifest = new PluginManifest
        {
            Id = "signed-plugin",
            Name = "Signed",
            Version = "1.0",
            Author = "official",
            IsSigned = true,
            Signature = "sha256:abc",
            Permissions = [PluginPermission.ReadWorkspace],
            IsEnabled = true,
        };

        Assert.True(manifest.IsSigned);
        Assert.NotNull(manifest.Signature);
        Assert.True(manifest.IsEnabled);
    }

    [Fact]
    public void EnterprisePolicy_ShouldEnforceDefaults()
    {
        var policy = new EnterprisePolicy
        {
            PolicyId = "enterprise-001",
            ForceCloudSendRestricted = true,
            ForceAuditLog = true,
            AllowedProviders = ["internal-llm"],
            DisableThirdPartyPlugins = true,
            RequirePluginSignature = true,
        };

        Assert.True(policy.ForceCloudSendRestricted);
        Assert.True(policy.DisableThirdPartyPlugins);
        Assert.Single(policy.AllowedProviders);
    }

    [Fact]
    public void EnterprisePolicy_ShouldNotWeakenLocalSecurity()
    {
        // Enterprise policy can add restrictions but cannot weaken the local security baseline.
        var policy = new EnterprisePolicy
        {
            PolicyId = "test",
            ForceCloudSendRestricted = true,
        };

        // Local security baseline: default only-read, local, least-exfiltration
        // Enterprise policy can only add more restrictions, not remove them.
        Assert.True(policy.ForceCloudSendRestricted);
    }

    [Fact]
    public void TeamConfig_ShouldShareWorkspaces()
    {
        var team = new TeamConfig
        {
            TeamId = "team-001",
            Name = "Dev Team",
            SharedWorkspaceIds = ["ws-1", "ws-2"],
            MemberIds = ["user-1", "user-2", "user-3"],
            EnableSharedIndex = true,
            EnableAuditLog = true,
        };

        Assert.Equal(2, team.SharedWorkspaceIds.Count);
        Assert.Equal(3, team.MemberIds.Count);
        Assert.True(team.EnableSharedIndex);
    }

    [Fact]
    public void UpdateConfig_ShouldDefaultToStableChannel()
    {
        var config = new UpdateConfig { Channel = UpdateChannel.Stable };

        Assert.True(config.AutoCheck);
        Assert.True(config.BackupBeforeUpdate);
        Assert.False(config.AutoInstall);
    }

    [Fact]
    public void UpdateCheckResult_ShouldIndicateAvailable()
    {
        var result = new UpdateCheckResult
        {
            UpdateAvailable = true,
            LatestVersion = "0.2.0",
            CurrentVersion = "0.1.0",
            ReleaseDate = DateTimeOffset.UtcNow,
            DownloadUrl = "https://example.com/download",
            Checksum = "sha256:def",
        };

        Assert.True(result.UpdateAvailable);
        Assert.NotNull(result.DownloadUrl);
    }

    [Fact]
    public void PluginPermission_ShouldHaveExpectedValues()
    {
        Assert.True(Enum.IsDefined(PluginPermission.ReadFiles));
        Assert.True(Enum.IsDefined(PluginPermission.WriteFiles));
        Assert.True(Enum.IsDefined(PluginPermission.ExecuteProcess));
        Assert.True(Enum.IsDefined(PluginPermission.NetworkAccess));
        Assert.True(Enum.IsDefined(PluginPermission.AccessCredentials));
    }

    [Fact]
    public void UpdateChannel_ShouldHaveExpectedValues()
    {
        Assert.Equal(4, Enum.GetNames<UpdateChannel>().Length);
    }
}

