    await File.WriteAllTextAsync(repomapPath, $"# Repository Map: {ws.Name}\n\n> Export is a placeholder.\n");

    return Results.Ok(new
    {
        workspaceId = id,
        exportedTo = exportDir,
        files = new[] { "workspace.json", "repomap.md" },
    });
});

