using System.Text.Json.Serialization;
using System.Text.RegularExpressions;

namespace AiKv.Core.Security;

/// <summary>
/// Exfiltration mode for a workspace.
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter))]
public enum ExfiltrationMode
{
    Standard,
    Restricted,
    PreviewRequired,
    Offline,
}

/// <summary>
/// Security policy for a workspace.
/// </summary>
public sealed record SecurityPolicy
{
    public required string Version { get; init; }
    public required ExfiltrationMode Mode { get; init; } = ExfiltrationMode.Standard;
    public IReadOnlySet<string> BlockedPaths { get; init; } = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    public IReadOnlySet<string> BlockedExtensions { get; init; } = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    public IReadOnlySet<string> BlockedPatterns { get; init; } = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
    public bool EnableSecretScan { get; init; } = true;
    public bool EnablePathTraversalCheck { get; init; } = true;
}

/// <summary>
/// Result of a security check on file content.
/// </summary>
public sealed record SecurityScanResult
{
    public required bool Passed { get; init; }
    public required IReadOnlyList<SecurityFinding> Findings { get; init; }
    public required string ScannerVersion { get; init; }
}

/// <summary>
/// A security finding (secret, sensitive data, etc.).
/// </summary>
public sealed record SecurityFinding
{
    public required SecurityFindingType Type { get; init; }
    public required string FilePath { get; init; }
    public required int Line { get; init; }
    public required string Description { get; init; }
}

[JsonConverter(typeof(JsonStringEnumConverter))]
public enum SecurityFindingType
{
    ApiKey,
    Password,
    PrivateKey,
    Certificate,
    Token,
    ConnectionString,
    PathTraversal,
    BlockedPath,
    BlockedExtension,
}

/// <summary>
/// Default sensitive file patterns.
/// </summary>
public static class DefaultSensitivePatterns
{
    public static readonly IReadOnlySet<string> SensitiveFiles = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        ".env", ".env.local", ".env.production", ".env.staging",
        "id_rsa", "id_ed25519", "id_ecdsa",
        "credentials.json", "service-account.json",
        "secrets.yaml", "secrets.yml", "secrets.json",
        "keystore", "keystore.jks",
    };

    public static readonly IReadOnlySet<string> SensitiveExtensions = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
    {
        ".pem", ".key", ".p12", ".pfx", ".crt", ".cer", ".der",
        ".mobileprovision",
    };
}

/// <summary>
/// Scans file content for secrets and sensitive data.
/// </summary>
public sealed partial class SecretScanner
{
    public const string Version = "secret-scanner-v1";

    public SecurityScanResult Scan(string filePath, string content)
    {
        var findings = new List<SecurityFinding>();
        var lines = content.Split('\n');

        for (var i = 0; i < lines.Length; i++)
        {
            var line = lines[i].TrimEnd('\r');

            // API keys
            if (ApiKeyRegex().IsMatch(line))
                findings.Add(new SecurityFinding { Type = SecurityFindingType.ApiKey, FilePath = filePath, Line = i + 1, Description = "Potential API key detected" });

            // Passwords
            if (PasswordRegex().IsMatch(line))
                findings.Add(new SecurityFinding { Type = SecurityFindingType.Password, FilePath = filePath, Line = i + 1, Description = "Potential password in assignment" });

            // Private keys
            if (PrivateKeyRegex().IsMatch(line))
                findings.Add(new SecurityFinding { Type = SecurityFindingType.PrivateKey, FilePath = filePath, Line = i + 1, Description = "Private key block detected" });

            // Connection strings with credentials
            if (ConnectionStringRegex().IsMatch(line))
                findings.Add(new SecurityFinding { Type = SecurityFindingType.ConnectionString, FilePath = filePath, Line = i + 1, Description = "Connection string with credentials" });

            // Bearer tokens
            if (BearerTokenRegex().IsMatch(line))
                findings.Add(new SecurityFinding { Type = SecurityFindingType.Token, FilePath = filePath, Line = i + 1, Description = "Bearer token detected" });
        }

        return new SecurityScanResult
        {
            Passed = findings.Count == 0,
            Findings = findings,
            ScannerVersion = Version,
        };
    }

    /// <summary>
    /// Checks if a file path matches sensitive patterns.
    /// </summary>
    public static bool IsSensitiveFile(string filePath)
    {
        var fileName = Path.GetFileName(filePath);
        var ext = Path.GetExtension(filePath);

        return DefaultSensitivePatterns.SensitiveFiles.Contains(fileName) ||
               DefaultSensitivePatterns.SensitiveExtensions.Contains(ext);
    }

    [GeneratedRegex(@"(?i)(api[_-]?key|apikey)\s*[:=]\s*['""]?[a-zA-Z0-9]{20,}")]
    private static partial Regex ApiKeyRegex();

    [GeneratedRegex(@"(?i)password\s*[:=]\s*['""]?[^\s'""$]{6,}")]
    private static partial Regex PasswordRegex();

    [GeneratedRegex(@"-----BEGIN\s+(RSA\s+|EC\s+|OPENSSH\s+)?PRIVATE\s+KEY-----")]
    private static partial Regex PrivateKeyRegex();

    [GeneratedRegex(@"(?i)(server|data\s+source)\s*=\s*[^;]*;\s*password\s*=\s*[^\s;]+")]
    private static partial Regex ConnectionStringRegex();

    [GeneratedRegex(@"(?i)bearer\s+[a-zA-Z0-9\-._~+\/]+=*")]
    private static partial Regex BearerTokenRegex();
}

/// <summary>
/// Enforces security policy on file paths and content before cloud send.
/// </summary>
public sealed class SecurityPolicyEnforcer
{
    private readonly SecurityPolicy _policy;
    private readonly SecretScanner _scanner = new();

    public SecurityPolicyEnforcer(SecurityPolicy? policy = null)
    {
        _policy = policy ?? new SecurityPolicy { Version = "sec-v1" };
    }

    /// <summary>
    /// Checks if a file path is allowed for cloud send.
    /// </summary>
    public bool IsPathAllowed(string filePath)
    {
        var fileName = Path.GetFileName(filePath);
        var ext = Path.GetExtension(filePath);

        if (_policy.BlockedExtensions.Contains(ext)) return false;
        if (_policy.BlockedPaths.Any(p => filePath.Contains(p, StringComparison.OrdinalIgnoreCase))) return false;
        if (SecretScanner.IsSensitiveFile(filePath)) return false;

        return true;
    }

    /// <summary>
    /// Checks if cloud send is allowed for the workspace.
    /// </summary>
    public bool IsCloudSendAllowed() => _policy.Mode != ExfiltrationMode.Offline;

    /// <summary>
    /// Scans content for secrets before cloud send.
    /// </summary>
    public SecurityScanResult ScanContent(string filePath, string content)
    {
        if (!_policy.EnableSecretScan)
            return new SecurityScanResult { Passed = true, Findings = [], ScannerVersion = SecretScanner.Version };

        return _scanner.Scan(filePath, content);
    }

    /// <summary>
    /// Full pre-send check: path + content scan + mode.
    /// </summary>
    public (bool allowed, SecurityScanResult? scanResult, string? reason) CheckBeforeSend(string filePath, string content)
    {
        if (!IsCloudSendAllowed())
            return (false, null, "Workspace is in Offline mode");

        if (!IsPathAllowed(filePath))
            return (false, null, $"File path blocked by policy: {filePath}");

        var scan = ScanContent(filePath, content);
        if (!scan.Passed)
            return (false, scan, $"Secret scan failed: {scan.Findings.Count} finding(s)");

        if (_policy.Mode == ExfiltrationMode.PreviewRequired)
            return (true, scan, "Preview required before send");

        return (true, scan, null);
    }
}

using AiKv.Core.Security;

namespace AiKv.Tests;

public class SecurityTests
{
    [Fact]
    public void SecretScanner_ShouldDetectApiKey()
    {
        var scanner = new SecretScanner();
        var result = scanner.Scan("config.env", "api_key=sk-1234567890abcdefghijklmnopqrstuvwxyz");

        Assert.False(result.Passed);
        Assert.Contains(result.Findings, f => f.Type == SecurityFindingType.ApiKey);
    }

    [Fact]
    public void SecretScanner_ShouldDetectPassword()
    {
        var scanner = new SecretScanner();
        var result = scanner.Scan("db.config", "password=mysecretpass123");

        Assert.False(result.Passed);
        Assert.Contains(result.Findings, f => f.Type == SecurityFindingType.Password);
    }

    [Fact]
    public void SecretScanner_ShouldDetectPrivateKey()
    {
        var scanner = new SecretScanner();
        var content = "-----BEGIN RSA PRIVATE KEY-----\nMIIEpAIBAAKCAQEA...\n-----END RSA PRIVATE KEY-----";

        var result = scanner.Scan("key.pem", content);

        Assert.False(result.Passed);
        Assert.Contains(result.Findings, f => f.Type == SecurityFindingType.PrivateKey);
    }

    [Fact]
    public void SecretScanner_ShouldDetectBearerToken()
    {
        var scanner = new SecretScanner();
        var result = scanner.Scan("request.txt", "Authorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...");

        Assert.False(result.Passed);
        Assert.Contains(result.Findings, f => f.Type == SecurityFindingType.Token);
    }

    [Fact]
    public void SecretScanner_ShouldPassCleanContent()
    {
        var scanner = new SecretScanner();
        var result = scanner.Scan("app.ts", "export function hello() { return 'world'; }");

        Assert.True(result.Passed);
        Assert.Empty(result.Findings);
    }

    [Fact]
    public void SecretScanner_IsSensitiveFile_ShouldDetectEnvFiles()
    {
        Assert.True(SecretScanner.IsSensitiveFile(".env"));
        Assert.True(SecretScanner.IsSensitiveFile(".env.local"));
        Assert.True(SecretScanner.IsSensitiveFile("id_rsa"));
        Assert.True(SecretScanner.IsSensitiveFile("cert.pem"));
    }

    [Fact]
    public void SecretScanner_IsSensitiveFile_ShouldNotFlagNormalFiles()
    {
        Assert.False(SecretScanner.IsSensitiveFile("app.ts"));
        Assert.False(SecretScanner.IsSensitiveFile("README.md"));
        Assert.False(SecretScanner.IsSensitiveFile("config.json"));
    }

    [Fact]
    public void SecurityPolicyEnforcer_IsPathAllowed_ShouldBlockSensitiveFiles()
    {
        var enforcer = new SecurityPolicyEnforcer();

        Assert.False(enforcer.IsPathAllowed(".env"));
        Assert.False(enforcer.IsPathAllowed("certs/server.pem"));
        Assert.True(enforcer.IsPathAllowed("src/app.ts"));
    }

    [Fact]
    public void SecurityPolicyEnforcer_OfflineMode_ShouldBlockAll()
    {
        var policy = new SecurityPolicy { Version = "v1", Mode = ExfiltrationMode.Offline };
        var enforcer = new SecurityPolicyEnforcer(policy);

        Assert.False(enforcer.IsCloudSendAllowed());
    }

    [Fact]
    public void SecurityPolicyEnforcer_StandardMode_ShouldAllow()
    {
        var policy = new SecurityPolicy { Version = "v1", Mode = ExfiltrationMode.Standard };
        var enforcer = new SecurityPolicyEnforcer(policy);

        Assert.True(enforcer.IsCloudSendAllowed());
    }

    [Fact]
    public void SecurityPolicyEnforcer_CheckBeforeSend_ShouldBlockSecrets()
    {
        var enforcer = new SecurityPolicyEnforcer();
        var (allowed, scan, reason) = enforcer.CheckBeforeSend("config.txt", "api_key=sk-1234567890abcdefghijklmnopqrstuvwxyz");

        Assert.False(allowed);
        Assert.NotNull(scan);
        Assert.False(scan!.Passed);
    }

    [Fact]
    public void SecurityPolicyEnforcer_CheckBeforeSend_ShouldBlockSensitivePath()
    {
        var enforcer = new SecurityPolicyEnforcer();
        var (allowed, _, reason) = enforcer.CheckBeforeSend(".env", "DATABASE_URL=postgres://localhost");

        Assert.False(allowed);
        Assert.Contains("blocked", reason!, StringComparison.OrdinalIgnoreCase);
    }

    [Fact]
    public void SecurityPolicyEnforcer_CheckBeforeSend_ShouldAllowCleanFile()
    {
        var enforcer = new SecurityPolicyEnforcer();
        var (allowed, scan, reason) = enforcer.CheckBeforeSend("src/app.ts", "export const x = 1;");

        Assert.True(allowed);
        Assert.NotNull(scan);
        Assert.True(scan!.Passed);
    }

    [Fact]
    public void SecurityPolicyEnforcer_PreviewRequired_ShouldAllowButFlag()
    {
        var policy = new SecurityPolicy { Version = "v1", Mode = ExfiltrationMode.PreviewRequired };
        var enforcer = new SecurityPolicyEnforcer(policy);
        var (allowed, _, reason) = enforcer.CheckBeforeSend("src/app.ts", "export const x = 1;");

        Assert.True(allowed);
        Assert.Contains("Preview required", reason);
    }

    [Fact]
    public void SecurityPolicyEnforcer_BlockedExtensions_ShouldBlock()
    {
        var policy = new SecurityPolicy
        {
            Version = "v1",
            BlockedExtensions = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { ".log", ".tmp" },
        };
        var enforcer = new SecurityPolicyEnforcer(policy);

        Assert.False(enforcer.IsPathAllowed("app.log"));
        Assert.False(enforcer.IsPathAllowed("temp.tmp"));
        Assert.True(enforcer.IsPathAllowed("app.ts"));
    }

    [Fact]
    public void SecurityScanResult_ShouldIncludeScannerVersion()
    {
        var scanner = new SecretScanner();
        var result = scanner.Scan("test.txt", "clean content");

        Assert.Equal("secret-scanner-v1", result.ScannerVersion);
    }
}

using System.Text.Json.Serialization;

namespace AiKv.Core.Tokens;

/// <summary>
/// Tokenizer contract: converts text to token count.
/// Supports pluggable implementations (BPE, word-level, char-based).
/// </summary>
public interface ITokenizer
{
    string Id { get; }
    string Version { get; }
    int CountTokens(string text);
    int CountTokensForMessages(IReadOnlyList<string> messages);
}

/// <summary>
/// Rough char-based tokenizer (chars / 4).
/// Used as fallback when no model-specific tokenizer is available.
/// </summary>
public sealed class CharEstimateTokenizer : ITokenizer
{
    public string Id => "char-estimate";
    public string Version => "v1";
    private const double CharsPerToken = 4.0;

    public int CountTokens(string text) =>
        string.IsNullOrEmpty(text) ? 0 : (int)Math.Ceiling(text.Length / CharsPerToken);

    public int CountTokensForMessages(IReadOnlyList<string> messages) =>
        messages.Sum(CountTokens);
}

/// <summary>
/// Word-boundary tokenizer: splits on whitespace and punctuation.
/// More accurate than char-estimate for English text.
/// </summary>
public sealed partial class WordBoundaryTokenizer : ITokenizer
{
    public string Id => "word-boundary";
    public string Version => "v1";

    public int CountTokens(string text)
    {
        if (string.IsNullOrEmpty(text)) return 0;
        var matches = TokenRegex().Matches(text);
        return matches.Count;
    }

    public int CountTokensForMessages(IReadOnlyList<string> messages) =>
        messages.Sum(CountTokens);

    [GeneratedRegex(@"\b\w+\b|[^\w\s]")]
    private static partial Regex TokenRegex();
}

/// <summary>
/// BPE-like tokenizer: splits on common code boundaries.
/// Better for source code than word-boundary.
/// </summary>
public sealed partial class CodeTokenizer : ITokenizer
{
    public string Id => "code-tokenizer";
    public string Version => "v1";

    public int CountTokens(string text)
    {
        if (string.IsNullOrEmpty(text)) return 0;

        var count = 0;
        var matches = CodeTokenRegex().Matches(text);
        count += matches.Count;

        // Count unmatched characters as individual tokens
        var matchedLength = matches.Sum(m => m.Length);
        var unmatched = text.Length - matchedLength;
        count += (int)Math.Ceiling(unmatched / 4.0);

        return count;
    }

    public int CountTokensForMessages(IReadOnlyList<string> messages) =>
        messages.Sum(CountTokens);

    [GeneratedRegex(@"\b\w+\b|::|=>|->|<=|>=|==|!=|\+\+|--|&&|\|\||::|[{}()\[\];,.<>+\-*/%&|^!?=:\""'#@]")]
    private static partial Regex CodeTokenRegex();
}

/// <summary>
/// Tokenizer registry: maps model IDs to tokenizers.
/// Falls back to char-estimate when no match is found.
/// </summary>
public sealed class TokenizerRegistry
{
    private readonly Dictionary<string, ITokenizer> _modelMap = new(StringComparer.OrdinalIgnoreCase);
    private readonly ITokenizer _default;

    public TokenizerRegistry(ITokenizer? defaultTokenizer = null)
    {
        _default = defaultTokenizer ?? new CharEstimateTokenizer();
    }

    /// <summary>
    /// Registers a tokenizer for a model ID pattern.
    /// </summary>
    public void Register(string modelPattern, ITokenizer tokenizer)
    {
        _modelMap[modelPattern] = tokenizer;
    }

    /// <summary>
    /// Gets the best matching tokenizer for a model ID.
    /// </summary>
    public ITokenizer GetForModel(string modelId)
    {
        // Exact match
        if (_modelMap.TryGetValue(modelId, out var exact))
            return exact;

        // Prefix match
        foreach (var (pattern, tokenizer) in _modelMap)
        {
            if (modelId.StartsWith(pattern, StringComparison.OrdinalIgnoreCase))
                return tokenizer;
        }

        return _default;
    }

    /// <summary>
    /// Count tokens for a model.
    /// </summary>
    public int CountTokens(string modelId, string text) =>
        GetForModel(modelId).CountTokens(text);

    /// <summary>
    /// Default tokenizer.
    /// </summary>
    public ITokenizer Default => _default;
}

using AiKv.Core.Tokens;

namespace AiKv.Tests;

public class TokenizerTests
{
    [Fact]
    public void CharEstimateTokenizer_ShouldEstimateByChars()
    {
        var tokenizer = new CharEstimateTokenizer();
        var tokens = tokenizer.CountTokens("hello world"); // 11 chars / 4 ≈ 3

        Assert.True(tokens >= 2 && tokens <= 3);
    }

    [Fact]
    public void CharEstimateTokenizer_ShouldReturnZeroForEmpty()
    {
        var tokenizer = new CharEstimateTokenizer();

        Assert.Equal(0, tokenizer.CountTokens(""));
        Assert.Equal(0, tokenizer.CountTokens(null!));
    }

    [Fact]
    public void WordBoundaryTokenizer_ShouldCountWords()
    {
        var tokenizer = new WordBoundaryTokenizer();
        var tokens = tokenizer.CountTokens("hello world foo bar");

        Assert.Equal(4, tokens);
    }

    [Fact]
    public void WordBoundaryTokenizer_ShouldCountPunctuation()
    {
        var tokenizer = new WordBoundaryTokenizer();
        var tokens = tokenizer.CountTokens("x = 1;");

        // x, =, 1, ; → 4 tokens
        Assert.True(tokens >= 4);
    }

    [Fact]
    public void CodeTokenizer_ShouldHandleCodeBoundaries()
    {
        var tokenizer = new CodeTokenizer();
        var tokens = tokenizer.CountTokens("const x = () => { return 1; };");

        Assert.True(tokens > 5);
    }

    [Fact]
    public void CodeTokenizer_ShouldCountOperators()
    {
        var tokenizer = new CodeTokenizer();
        var tokens1 = tokenizer.CountTokens("a=>b");
        var tokens2 = tokenizer.CountTokens("a->b");
        var tokens3 = tokenizer.CountTokens("a==b");

        Assert.True(tokens1 > 0);
        Assert.True(tokens2 > 0);
        Assert.True(tokens3 > 0);
    }

    [Fact]
    public void TokenizerRegistry_ShouldFallbackToDefault()
    {
        var registry = new TokenizerRegistry();

        var tokenizer = registry.GetForModel("unknown-model");

        Assert.Equal("char-estimate", tokenizer.Id);
    }

    [Fact]
    public void TokenizerRegistry_ShouldMatchExactModelId()
    {
        var registry = new TokenizerRegistry();
        var codeTokenizer = new CodeTokenizer();
        registry.Register("gpt-4", codeTokenizer);

        var tokenizer = registry.GetForModel("gpt-4");

        Assert.Equal("code-tokenizer", tokenizer.Id);
    }

    [Fact]
    public void TokenizerRegistry_ShouldMatchPrefix()
    {
        var registry = new TokenizerRegistry();
        var wordTokenizer = new WordBoundaryTokenizer();
        registry.Register("claude", wordTokenizer);

        var tokenizer = registry.GetForModel("claude-3-opus");

        Assert.Equal("word-boundary", tokenizer.Id);
    }

    [Fact]
    public void TokenizerRegistry_CountTokens_ShouldUseMatchedTokenizer()
    {
        var registry = new TokenizerRegistry();
        registry.Register("gpt-4", new CodeTokenizer());

        var tokens = registry.CountTokens("gpt-4", "const x = 1;");

        Assert.True(tokens > 0);
    }

    [Fact]
    public void TokenizerRegistry_ShouldUseCustomDefault()
    {
        var wordTokenizer = new WordBoundaryTokenizer();
        var registry = new TokenizerRegistry(wordTokenizer);

        var tokenizer = registry.GetForModel("unknown");

        Assert.Equal("word-boundary", tokenizer.Id);
    }

    [Fact]
    public void CharEstimateTokenizer_CountTokensForMessages_ShouldSumAll()
    {
        var tokenizer = new CharEstimateTokenizer();
        var total = tokenizer.CountTokensForMessages(["hello", "world foo"]);

        Assert.True(total > 0);
    }

    [Fact]
    public void CodeTokenizer_ShouldReturnZeroForEmpty()
    {
        var tokenizer = new CodeTokenizer();

        Assert.Equal(0, tokenizer.CountTokens(""));
    }

    [Fact]
    public void TokenizerVersions_ShouldBeSet()
    {
        Assert.Equal("v1", new CharEstimateTokenizer().Version);
        Assert.Equal("v1", new WordBoundaryTokenizer().Version);
        Assert.Equal("v1", new CodeTokenizer().Version);
    }
}

