using AiKv.Core.Gateway;
using AiKv.Core.Gateway.Server;

namespace AiKv.Cli.Commands;

public static class GatewayCommands
{
    public static async Task<int> HandleAsync(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Usage: aikv gateway <start|status|stop> [options]");
            return 1;
        }

        return args[0] switch
        {
            "start" => Start(args.AsSpan(1).ToArray()),
            "status" => Status(),
            "stop" => Stop(),
            _ => 1,
        };
    }

    private static int Start(string[] args)
    {
        var baseUrl = GetOpt(args, "--provider-url");
        var apiKey = GetOpt(args, "--provider-key");
        var port = GetOpt(args, "--port") ?? "5218";

        if (string.IsNullOrEmpty(baseUrl))
        {
            Console.Error.WriteLine("Error: --provider-url=<url> is required");
            Console.Error.WriteLine("Example: aikv gateway start --provider-url=https://api.openai.com --provider-key=sk-xxx");
            return 1;
        }

        if (string.IsNullOrEmpty(apiKey))
        {
            Console.Error.WriteLine("Warning: --provider-key not set; Gateway will forward without auth header");
        }

        var config = new GatewayConfig
        {
            ProviderBaseUrl = baseUrl,
            ProviderApiKey = apiKey ?? "",
            Port = int.Parse(port, System.Globalization.CultureInfo.InvariantCulture),
        };

        Console.Error.WriteLine($"Starting AI_KV Gateway on http://{config.Host}:{config.Port}");
        Console.Error.WriteLine($"  Provider: {config.ProviderBaseUrl}");
        Console.Error.WriteLine($"  Cache: {config.EnableCache}");
        Console.Error.WriteLine($"  SingleFlight: {config.EnableSingleFlight}");
        Console.Error.WriteLine("  Press Ctrl+C to stop.");

        using var cts = new CancellationTokenSource();
        Console.CancelKeyPress += (_, e) => { e.Cancel = true; cts.Cancel(); };

        try
        {
            using var server = new GatewayServer(config);
            var statsTask = Task.Run(async () =>
            {
                while (!cts.Token.IsCancellationRequested)
                {
                    await Task.Delay(TimeSpan.FromSeconds(30), cts.Token);
                    var stats = server.GetStats();
                    Console.Error.WriteLine($"[Stats] Requests: {stats.TotalRequests}, Cache hit: {stats.CacheHitRate:P1}, Avg latency: {stats.AvgLatencyMs:F0}ms");
                }
            }, cts.Token);

            server.StartAsync(cts.Token).GetAwaiter().GetResult();
        }
        catch (OperationCanceledException)
        {
            Console.Error.WriteLine("Gateway stopped.");
        }

        return 0;
    }

    private static int Status()
    {
        Console.WriteLine("""{"status": "not_running", "message": "Gateway is not started. Use 'aikv gateway start' to begin."}""");
        return 0;
    }

    private static int Stop()
    {
        Console.Error.WriteLine("Gateway stop: Send Ctrl+C to the running gateway process.");
        return 0;
    }

    private static string? GetOpt(string[] args, string prefix) =>
        args.FirstOrDefault(a => a.StartsWith(prefix + "=", StringComparison.OrdinalIgnoreCase))?[prefix.Length..];
}

using AiKv.Indexing.Detection;

namespace AiKv.Cli.Commands;

public static class DetectCommands
{
    public static int Handle(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Usage: aikv detect <path> [--plan]");
            return 1;
        }

        var path = args[0];
        var showPlan = args.Contains("--plan", StringComparer.OrdinalIgnoreCase);
        var outputJson = args.Contains("--output=json", StringComparer.OrdinalIgnoreCase) ||
                         args.Contains("--json", StringComparer.OrdinalIgnoreCase);

        if (!Directory.Exists(path))
        {
            Console.Error.WriteLine($"Error: Directory not found: {path}");
            return 1;
        }

        var engine = new ProjectDetectionEngine();
        var result = engine.Detect(path);

        if (showPlan)
        {
            var plan = engine.GeneratePlan(result);

            if (outputJson)
            {
                var json = System.Text.Json.JsonSerializer.Serialize(new
                {
                    rootPath = plan.RootPath,
                    components = plan.DetectedComponents,
                    actions = plan.Actions.Select(a => new
                    {
                        command = a.Command,
                        purpose = a.Purpose,
                        workingDirectory = a.WorkingDirectory,
                        requiresNetwork = a.RequiresNetwork,
                        writesToDisk = a.WritesToDisk,
                        mayRunScripts = a.MayRunScripts,
                        approval = a.Approval.ToString(),
                        risks = a.Risks,
                    }),
                    missingTools = plan.MissingTools,
                }, new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
                Console.WriteLine(json);
            }
            else
            {
                Console.WriteLine($"Project: {result.RootPath}");
                Console.WriteLine($"  Monorepo: {result.IsMonorepo}");
                Console.WriteLine($"  Components ({result.Components.Count}):");
                foreach (var comp in result.Components)
                    Console.WriteLine($"    {comp.Language} ({comp.Framework ?? comp.BuildSystem ?? "unknown"}) — {comp.Path}");
                Console.WriteLine();
                Console.WriteLine($"Initialization Plan ({plan.Actions.Count} actions):");
                foreach (var action in plan.Actions)
                {
                    Console.WriteLine($"  [{action.Approval}] {action.Command}");
                    Console.WriteLine($"    Purpose: {action.Purpose}");
                    Console.WriteLine($"    Network: {action.RequiresNetwork}, Writes: {action.WritesToDisk}, Scripts: {action.MayRunScripts}");
                    if (action.Risks.Count > 0)
                        Console.WriteLine($"    Risks: {string.Join(", ", action.Risks)}");
                }
            }
        }
        else
        {
            if (outputJson)
            {
                var json = System.Text.Json.JsonSerializer.Serialize(new
                {
                    rootPath = result.RootPath,
                    isMonorepo = result.IsMonorepo,
                    components = result.Components.Select(c => new
                    {
                        id = c.Id, path = c.Path, language = c.Language,
                        framework = c.Framework, buildSystem = c.BuildSystem,
                        packageManager = c.PackageManager, confidence = c.Confidence,
                    }),
                    languageStats = result.LanguageStats,
                }, new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
                Console.WriteLine(json);
            }
            else
            {
                Console.WriteLine($"Project: {result.RootPath}");
                Console.WriteLine($"  Monorepo: {result.IsMonorepo}");
                Console.WriteLine($"  Components ({result.Components.Count}):");
                foreach (var comp in result.Components)
                {
                    Console.WriteLine($"    {comp.Language} ({comp.Framework ?? comp.BuildSystem ?? "unknown"})");
                    Console.WriteLine($"      Path: {comp.Path}");
                    Console.WriteLine($"      Evidence: {string.Join(", ", comp.Evidence)}");
                }
                if (result.LanguageStats.Count > 0)
                {
                    Console.WriteLine("  Language Stats:");
                    foreach (var kv in result.LanguageStats)
                        Console.WriteLine($"    {kv.Key}: {kv.Value}");
                }
            }
        }

        return 0;
    }
}

