    [Fact]
    public void ContextEngine_WithoutSecurityPolicy_ShouldDefaultSafe()
    {
        var engine = new ContextEngine();

        var manifest = engine.Build(
            new ContextBuildRequest
            {
                WorkspaceId = Core.Identifiers.WorkspaceId.New(),
                IndexSnapshotId = Core.Identifiers.IndexSnapshotId.New(),
                Task = "Fix bug",
            },
            () => [],
            path => "",
            path => "sha256:abc");

        Assert.True(manifest.Safety.CloudSendAllowed);
        Assert.True(manifest.Safety.SecretsScanPassed);
    }

    [Fact]
    public void ContextEngine_ShouldUpdateVersion()
    {
        var engine = new ContextEngine();

        var manifest = engine.Build(
            new ContextBuildRequest
            {
                WorkspaceId = Core.Identifiers.WorkspaceId.New(),
                IndexSnapshotId = Core.Identifiers.IndexSnapshotId.New(),
                Task = "Fix bug",
            },
            () => [],
            path => "",
            path => "sha256:abc");

        Assert.Equal("0.2.0", manifest.ContextEngineVersion);
    }
}

using System.Text.Json;
using AiKv.Core.Gateway;
using AiKv.Core.Tokens;

namespace AiKv.Core.Gateway.Streaming;

/// <summary>
/// SSE (Server-Sent Events) frame for streaming responses.
/// </summary>
public sealed record SseFrame
{
    public required string Event { get; init; }
    public required string Data { get; init; }
    public string? Id { get; init; }

    public string ToSseString()
    {
        var sb = new System.Text.StringBuilder();
        if (!string.IsNullOrEmpty(Event))
            sb.Append("event: ").Append(Event).Append('\n');
        if (!string.IsNullOrEmpty(Id))
            sb.Append("id: ").Append(Id).Append('\n');
        sb.Append("data: ").Append(Data).Append("\n\n");
        return sb.ToString();
    }
}

/// <summary>
/// Parses OpenAI-compatible SSE stream chunks.
/// Extracts delta content and usage information.
/// </summary>
public static class SseStreamParser
{
    /// <summary>
    /// Parses a single SSE data line (the part after "data: ").
    /// Returns null for [DONE] or unparseable lines.
    /// </summary>
    public static StreamChunk? ParseChunk(string dataLine)
    {
        if (string.IsNullOrWhiteSpace(dataLine)) return null;
        if (dataLine.Trim() == "[DONE]") return null;

        try
        {
            using var doc = JsonDocument.Parse(dataLine);
            var root = doc.RootElement;

            var choices = root.TryGetProperty("choices", out var c) ? c : default;
            if (choices.ValueKind != JsonValueKind.Array || choices.GetArrayLength() == 0)
                return new StreamChunk { Delta = "", FinishReason = null, Usage = null };

            var firstChoice = choices[0];
            var delta = firstChoice.TryGetProperty("delta", out var d) &&
                        d.TryGetProperty("content", out var content)
                ? content.GetString() ?? ""
                : "";
            var finishReason = firstChoice.TryGetProperty("finish_reason", out var fr)
                ? fr.GetString()
                : null;

            ModelUsageInfo? usage = null;
            if (root.TryGetProperty("usage", out var u))
            {
                usage = new ModelUsageInfo
                {
                    PromptTokens = u.TryGetProperty("prompt_tokens", out var pt) ? pt.GetInt32() : 0,
                    CompletionTokens = u.TryGetProperty("completion_tokens", out var ct) ? ct.GetInt32() : 0,
                    TotalTokens = u.TryGetProperty("total_tokens", out var tt) ? tt.GetInt32() : 0,
                };
            }

            return new StreamChunk { Delta = delta, FinishReason = finishReason, Usage = usage };
        }
        catch
        {
            return null;
        }
    }

    /// <summary>
    /// Parses a full SSE response body (multiple "data: ..." lines).
    /// </summary>
    public static ParsedStreamResult ParseStream(string sseBody)
    {
        var contentBuilder = new System.Text.StringBuilder();
        ModelUsageInfo? usage = null;
        string? finishReason = null;

        var lines = sseBody.Split('\n');
        foreach (var line in lines)
        {
            if (!line.StartsWith("data: ", StringComparison.Ordinal)) continue;
            var data = line["data: ".Length..];
            var chunk = ParseChunk(data);
            if (chunk is null) continue;

            contentBuilder.Append(chunk.Delta);
            if (chunk.FinishReason is not null)
                finishReason = chunk.FinishReason;
            if (chunk.Usage is not null)
                usage = chunk.Usage;
        }

        return new ParsedStreamResult
        {
            Content = contentBuilder.ToString(),
            FinishReason = finishReason,
            Usage = usage,
        };
    }
}

/// <summary>
/// A parsed chunk from an SSE stream.
/// </summary>
public sealed record StreamChunk
{
    public required string Delta { get; init; }
    public string? FinishReason { get; init; }
    public ModelUsageInfo? Usage { get; init; }
}

/// <summary>
/// Result of parsing a complete SSE stream.
/// </summary>
public sealed record ParsedStreamResult
{
    public required string Content { get; init; }
    public string? FinishReason { get; init; }
    public ModelUsageInfo? Usage { get; init; }
}

using AiKv.Core.Gateway.Streaming;

namespace AiKv.Tests;

public class SseStreamParserTests
{
    [Fact]
    public void ParseChunk_ShouldExtractDeltaContent()
    {
        var data = """{"choices":[{"delta":{"content":"Hello"},"finish_reason":null}]}""";

        var chunk = SseStreamParser.ParseChunk(data);

        Assert.NotNull(chunk);
        Assert.Equal("Hello", chunk!.Delta);
        Assert.Null(chunk.FinishReason);
    }

    [Fact]
    public void ParseChunk_ShouldExtractFinishReason()
    {
        var data = """{"choices":[{"delta":{},"finish_reason":"stop"}]}""";

        var chunk = SseStreamParser.ParseChunk(data);

        Assert.NotNull(chunk);
        Assert.Equal("", chunk!.Delta);
        Assert.Equal("stop", chunk.FinishReason);
    }

    [Fact]
    public void ParseChunk_ShouldExtractUsage()
    {
        var data = """{"choices":[{"delta":{},"finish_reason":"stop"}],"usage":{"prompt_tokens":10,"completion_tokens":5,"total_tokens":15}}""";

        var chunk = SseStreamParser.ParseChunk(data);

        Assert.NotNull(chunk);
        Assert.NotNull(chunk!.Usage);
        Assert.Equal(10, chunk.Usage!.PromptTokens);
        Assert.Equal(15, chunk.Usage.TotalTokens);
    }

    [Fact]
    public void ParseChunk_ShouldReturnNullForDone()
    {
        var chunk = SseStreamParser.ParseChunk("[DONE]");

        Assert.Null(chunk);
    }

    [Fact]
    public void ParseChunk_ShouldReturnNullForEmpty()
    {
        Assert.Null(SseStreamParser.ParseChunk(""));
        Assert.Null(SseStreamParser.ParseChunk("   "));
    }

    [Fact]
    public void ParseChunk_ShouldReturnNullForInvalidJson()
    {
        Assert.Null(SseStreamParser.ParseChunk("not json"));
    }

    [Fact]
    public void ParseStream_ShouldConcatenateDeltas()
    {
        var sseBody = """
            data: {"choices":[{"delta":{"content":"Hello"},"finish_reason":null}]}

            data: {"choices":[{"delta":{"content":" "},"finish_reason":null}]}

            data: {"choices":[{"delta":{"content":"World"},"finish_reason":null}]}

            data: {"choices":[{"delta":{},"finish_reason":"stop"}]}

            data: [DONE]

            """;

        var result = SseStreamParser.ParseStream(sseBody);

        Assert.Equal("Hello World", result.Content);
        Assert.Equal("stop", result.FinishReason);
    }

    [Fact]
    public void ParseStream_ShouldExtractUsageFromFinalChunk()
    {
        var sseBody = """
            data: {"choices":[{"delta":{"content":"Hi"},"finish_reason":null}]}

            data: {"choices":[{"delta":{},"finish_reason":"stop"}],"usage":{"prompt_tokens":5,"completion_tokens":1,"total_tokens":6}}

            data: [DONE]

            """;

        var result = SseStreamParser.ParseStream(sseBody);

        Assert.NotNull(result.Usage);
        Assert.Equal(6, result.Usage!.TotalTokens);
    }

    [Fact]
    public void ParseStream_ShouldHandleEmptyStream()
    {
        var result = SseStreamParser.ParseStream("");

        Assert.Equal("", result.Content);
        Assert.Null(result.FinishReason);
        Assert.Null(result.Usage);
    }

    [Fact]
    public void SseFrame_ToSseString_ShouldFormatCorrectly()
    {
        var frame = new SseFrame { Event = "message", Data = """{"content":"hi"}""", Id = "1" };

        var sse = frame.ToSseString();

        Assert.Contains("event: message", sse);
        Assert.Contains("id: 1", sse);
        Assert.Contains("data: ", sse);
        Assert.EndsWith("\n\n", sse);
    }

    [Fact]
    public void SseFrame_ToSseString_ShouldWorkWithoutEventOrId()
    {
        var frame = new SseFrame { Event = "", Data = """{"content":"hi"}""" };

        var sse = frame.ToSseString();

        Assert.DoesNotContain("event:", sse);
        Assert.DoesNotContain("id:", sse);
        Assert.Contains("data: ", sse);
    }
}

