namespace AiKv.Tests;

/// <summary>
/// Integration tests verifying ContextEngine + Cache + Tokenizer + Security
/// work together in realistic scenarios.
/// </summary>
public class ContextEngineRealWorldTests
{
    [Fact]
    public void RealWorld_MultiFileProject_ContextBuild_WithCaching()
    {
        var registry = new TokenizerRegistry();
        registry.Register("gpt-4", new CodeTokenizer());
        var engine = new ContextEngine(registry);
        var cache = new ContextPackageCache();

        var files = new List<IndexedFileInfo>
        {
            new() { Path = "src/auth/AuthService.ts", NormalizedPath = "src/auth/AuthService.ts", Language = "typescript", Size = 800, Symbols = ["AuthService", "login", "refreshToken"] },
            new() { Path = "src/auth/TokenManager.ts", NormalizedPath = "src/auth/TokenManager.ts", Language = "typescript", Size = 500, Symbols = ["TokenManager", "getToken", "refreshToken"] },
            new() { Path = "src/api/UserController.ts", NormalizedPath = "src/api/UserController.ts", Language = "typescript", Size = 600, Symbols = ["UserController", "getUser"] },
            new() { Path = "src/db/Database.ts", NormalizedPath = "src/db/Database.ts", Language = "typescript", Size = 400, Symbols = ["Database", "query"] },
            new() { Path = "src/utils/logger.ts", NormalizedPath = "src/utils/logger.ts", Language = "typescript", Size = 200, Symbols = ["Logger"] },
            new() { Path = "README.md", NormalizedPath = "README.md", Language = "markdown", Size = 2000, Symbols = [] },
            new() { Path = "package.json", NormalizedPath = "package.json", Language = "json", Size = 500, Symbols = [] },
        };

        var contentMap = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            ["src/auth/AuthService.ts"] = "export class AuthService { login() {} refreshToken() {} }",
            ["src/auth/TokenManager.ts"] = "export class TokenManager { getToken() {} refreshToken() {} }",
            ["src/api/UserController.ts"] = "export class UserController { getUser() {} }",
            ["src/db/Database.ts"] = "export class Database { query() {} }",
            ["src/utils/logger.ts"] = "export class Logger { log() {} }",
            ["README.md"] = "# Project\n\nThis is a test project.",
            ["package.json"] = """{"name":"test","dependencies":{"express":"4.0"}}""",
        };

        var wsId = WorkspaceId.New();
        var snapId = IndexSnapshotId.New();

        // First build — should populate cache
        var key = CacheKey.Build("Fix refreshToken in AuthService", snapId.Value, "deterministic-v1", 3, 80000, 90000, null, null);
        var wasCached = cache.TryGetOrBuild(key, () => engine.Build(
            new ContextBuildRequest { WorkspaceId = wsId, IndexSnapshotId = snapId, Task = "Fix refreshToken in AuthService", ModelId = "gpt-4" },
            () => files,
            path => contentMap.TryGetValue(path, out var c) ? c : "",
            path => "sha256:abc"), out var manifest1);

        Assert.False(wasCached); // First time — builds
        Assert.NotEmpty(manifest1!.SelectedFiles);
        Assert.Contains(manifest1.SelectedFiles, f => f.Path.Contains("AuthService"));

        // Second build with same key — should hit cache
        var wasCached2 = cache.TryGetOrBuild(key, () => engine.Build(
            new ContextBuildRequest { WorkspaceId = wsId, IndexSnapshotId = snapId, Task = "Fix refreshToken in AuthService", ModelId = "gpt-4" },
            () => files,
            path => contentMap.TryGetValue(path, out var c) ? c : "",
            path => "sha256:abc"), out var manifest2);

        Assert.True(wasCached2); // Cache hit
        Assert.Same(manifest1, manifest2);
    }

    [Fact]
    public void RealWorld_SecurityBlocksApiKeyInSelectedFile()
    {
        var policy = new Core.Security.SecurityPolicy { Version = "sec-v1" };
        var engine = new ContextEngine(securityPolicy: policy);

        var files = new List<IndexedFileInfo>
        {
            new() { Path = "config/settings.ts", NormalizedPath = "config/settings.ts", Language = "typescript", Size = 100, Symbols = ["Settings"] },
        };

        var manifest = engine.Build(
            new ContextBuildRequest
            {
                WorkspaceId = WorkspaceId.New(),
                IndexSnapshotId = IndexSnapshotId.New(),
                Task = "Fix Settings in config/settings.ts",
            },
            () => files,
            path => "export const API_KEY = 'sk-1234567890abcdefghijklmnopqrstuv';",
            path => "sha256:abc");

        // Security scan should have found the API key
        Assert.False(manifest.Safety.SecretsScanPassed);
        Assert.NotNull(manifest.Safety.SensitiveExclusions);
        Assert.NotEmpty(manifest.Safety.SensitiveExclusions!);
    }

    [Fact]
    public void RealWorld_TokenizerAffectsBudgetReporting()
    {
        var registry = new TokenizerRegistry();
        registry.Register("gpt-4", new CodeTokenizer());
        registry.Register("claude", new WordBoundaryTokenizer());
        var engine = new ContextEngine(registry);

        var wsId = WorkspaceId.New();
        var snapId = IndexSnapshotId.New();
        var files = new List<IndexedFileInfo>
        {
            new() { Path = "app.ts", NormalizedPath = "app.ts", Language = "typescript", Size = 100, Symbols = ["App"] },
        };
        var content = "export class App { run() { console.log('hello world'); } }";

        var manifestGpt4 = engine.Build(
            new ContextBuildRequest { WorkspaceId = wsId, IndexSnapshotId = snapId, Task = "Fix App", ModelId = "gpt-4" },
            () => files, path => content, path => "h");

        var manifestClaude = engine.Build(
            new ContextBuildRequest { WorkspaceId = wsId, IndexSnapshotId = snapId, Task = "Fix App", ModelId = "claude-3-opus" },
            () => files, path => content, path => "h");

        Assert.Equal("code-tokenizer", manifestGpt4.Budget.Tokenizer);
        Assert.Equal("word-boundary", manifestClaude.Budget.Tokenizer);
    }

    [Fact]
    public void RealWorld_OfflineMode_BlocksCloudSend()
    {
        var policy = new Core.Security.SecurityPolicy { Version = "sec-v1", Mode = Core.Security.ExfiltrationMode.Offline };
        var engine = new ContextEngine(securityPolicy: policy);

        var manifest = engine.Build(
            new ContextBuildRequest
            {
                WorkspaceId = WorkspaceId.New(),
                IndexSnapshotId = IndexSnapshotId.New(),
                Task = "Any task",
            },
            () => [],
            path => "",
            path => "h");

        Assert.False(manifest.Safety.CloudSendAllowed);
    }

    [Fact]
    public void RealWorld_Explain_ProducesMeaningfulOutput()
    {
        var registry = new TokenizerRegistry();
        var engine = new ContextEngine(registry);

        var files = new List<IndexedFileInfo>
        {
            new() { Path = "src/auth.ts", NormalizedPath = "src/auth.ts", Language = "typescript", Size = 500, Symbols = ["AuthService"] },
            new() { Path = "src/unused.ts", NormalizedPath = "src/unused.ts", Language = "typescript", Size = 1000, Symbols = ["Unused"] },
        };

        var manifest = engine.Build(
            new ContextBuildRequest
            {
                WorkspaceId = WorkspaceId.New(),
                IndexSnapshotId = IndexSnapshotId.New(),
                Task = "Fix AuthService in src/auth.ts",
            },
            () => files,
            path => $"export class {path} {{ }}",
            path => "sha256:abc");

        var explanations = Context.Explain.ContextExplainer.Explain(manifest);
        var misses = Context.Explain.ContextExplainer.DetectPotentialMisses(manifest);
        var budget = Context.Explain.ContextExplainer.BudgetSummary(manifest);

        Assert.NotEmpty(explanations);
        Assert.Contains(budget, b => b.Contains("已用") || b.Contains("hard"));
    }
}

using System.Text;
using AiKv.Core.Context;
using AiKv.Core.Identifiers;
using AiKv.Context.Chunking;

namespace AiKv.Context.Payload;

/// <summary>
/// Generates Context Package Payload from a Manifest and file contents.
/// Payload contains actual code content, separated from Manifest metadata.
/// </summary>
public sealed class PayloadGenerator
{
    private readonly ChunkingStrategy _chunker = new();

    /// <summary>
    /// Generates a Payload from a Manifest and content provider.
    /// </summary>
    public ContextPackagePayload Generate(
        ContextPackageManifest manifest,
        Func<string, string> contentProvider)
    {
        var items = new List<PayloadItem>();
        var totalTokens = 0;

        foreach (var file in manifest.SelectedFiles)
        {
            var content = contentProvider(file.Path);
            if (string.IsNullOrEmpty(content)) continue;

            var chunks = _chunker.Chunk(file.Path, content, file.Mode, 10000);

            foreach (var chunk in chunks)
            {
                items.Add(new PayloadItem
                {
                    Path = file.Path,
                    Mode = file.Mode,
                    Content = chunk.Content,
                    StartLine = chunk.StartLine > 0 ? chunk.StartLine : null,
                    EndLine = chunk.EndLine > 0 ? chunk.EndLine : null,
                });
                totalTokens += chunk.EstimatedTokens;
            }
        }

        return new ContextPackagePayload
        {
            ContextPackageId = manifest.Id.Value,
            Format = PayloadFormat.Markdown,
            Items = items,
            TotalEstimatedTokens = totalTokens,
        };
    }

    /// <summary>
    /// Generates a Markdown-formatted payload string.
    /// </summary>
    public string GenerateMarkdown(
        ContextPackageManifest manifest,
        Func<string, string> contentProvider)
    {
        var sb = new StringBuilder();

        sb.AppendLine($"# Context Package: {manifest.Id.Value}");
        sb.AppendLine();
        sb.AppendLine($"**Task:** {manifest.Task.OriginalText}");
        sb.AppendLine($"**Budget:** {manifest.Budget.ActualEstimate} / {manifest.Budget.ContextTarget} tokens");
        sb.AppendLine($"**Engine:** {manifest.ContextEngineVersion}");
        sb.AppendLine();

        foreach (var file in manifest.SelectedFiles)
        {
            var content = contentProvider(file.Path);
            if (string.IsNullOrEmpty(content)) continue;

            var ext = Path.GetExtension(file.Path).TrimStart('.');
            sb.AppendLine($"## {file.Path}");
            sb.AppendLine();
            sb.AppendLine($"- Mode: {file.Mode}");
            sb.AppendLine($"- Score: {file.Score:F2}");
            sb.AppendLine($"- Reasons: {string.Join(", ", file.Reasons)}");
            sb.AppendLine();

            if (file.Mode == SelectionMode.Full)
            {
                sb.AppendLine($"```{ext}");
                sb.AppendLine(content);
                sb.AppendLine("```");
            }
            else if (file.Mode == SelectionMode.Chunks && file.Ranges is not null)
            {
                var lines = content.Split('\n');
                foreach (var range in file.Ranges)
                {
                    var start = Math.Max(0, range.StartLine - 1);
                    var end = Math.Min(lines.Length, range.EndLine);
                    sb.AppendLine($"```{ext} (lines {range.StartLine}-{range.EndLine})");
                    sb.AppendLine(string.Join('\n', lines[start..end]));
                    sb.AppendLine("```");
                    sb.AppendLine();
                }
            }
            else
            {
                // Outline / Summary / Metadata — just include the chunked content
                var chunks = _chunker.Chunk(file.Path, content, file.Mode, 5000);
                foreach (var chunk in chunks)
                {
                    sb.AppendLine($"```{ext}");
                    sb.AppendLine(chunk.Content);
                    sb.AppendLine("```");
                    sb.AppendLine();
                }
            }

            sb.AppendLine();
        }

        if (manifest.ExcludedCandidates.Count > 0)
        {
            sb.AppendLine("## Excluded");
            sb.AppendLine();
            foreach (var e in manifest.ExcludedCandidates)
            {
                sb.AppendLine($"- {e.Path} (score: {e.Score:F2}) — {e.Reason}");
            }
        }

        return sb.ToString();
    }
}

using AiKv.Context.Payload;
using AiKv.Core.Context;
using AiKv.Core.Identifiers;
using AiKv.Storage;

namespace AiKv.Context.Export;

/// <summary>
/// File export protocol: writes .aikv/ directory with workspace.json,
/// latest-context.manifest.json, latest-context.md, and repomap.md.
/// Default export location is AI_KV data directory.
/// Only writes to repository .aikv/ when explicitly enabled by user.
/// </summary>
public sealed class FileExporter
{
    private readonly AppDataDirectory _appData;

    public FileExporter(AppDataDirectory? appData = null)
    {
        _appData = appData ?? new AppDataDirectory();
    }

    /// <summary>
    /// Exports a context package to the AI_KV data directory.
    /// </summary>
    public async Task<string> ExportAsync(
        ContextPackageManifest manifest,
        Func<string, string> contentProvider,
        string? workspaceId = null)
    {
        var exportDir = GetExportDir(workspaceId ?? manifest.WorkspaceId.Value);
        Directory.CreateDirectory(exportDir);

        // 1. workspace.json
        var workspaceJson = new
        {
            workspaceId = manifest.WorkspaceId.Value,
            indexSnapshotId = manifest.IndexSnapshotId.Value,
            schemaVersion = manifest.SchemaVersion,
            engineVersion = manifest.ContextEngineVersion,
        };
        await File.WriteAllTextAsync(
            Path.Combine(exportDir, "workspace.json"),
            System.Text.Json.JsonSerializer.Serialize(workspaceJson, new System.Text.Json.JsonSerializerOptions { WriteIndented = true }));

        // 2. latest-context.manifest.json
        var manifestJson = System.Text.Json.JsonSerializer.Serialize(manifest, new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
        await File.WriteAllTextAsync(
            Path.Combine(exportDir, "latest-context.manifest.json"),
            manifestJson);

        // 3. latest-context.md
        var generator = new PayloadGenerator();
        var markdown = generator.GenerateMarkdown(manifest, contentProvider);
        await File.WriteAllTextAsync(
            Path.Combine(exportDir, "latest-context.md"),
            markdown);

        // 4. repomap.md
        var repomap = GenerateRepoMap(manifest);
        await File.WriteAllTextAsync(
            Path.Combine(exportDir, "repomap.md"),
            repomap);

        return exportDir;
    }

    /// <summary>
    /// Exports to a repository's .aikv/ directory (requires explicit user opt-in).
    /// Also generates a .gitignore entry suggestion.
    /// </summary>
    public async Task<string> ExportToRepositoryAsync(
        string repositoryRoot,
        ContextPackageManifest manifest,
        Func<string, string> contentProvider)
    {
        var aikvDir = Path.Combine(repositoryRoot, ".aikv");
        Directory.CreateDirectory(aikvDir);

        // Write files
        var exportDir = await ExportAsync(manifest, contentProvider, manifest.WorkspaceId.Value);

        // Copy to .aikv/
        foreach (var file in Directory.GetFiles(exportDir))
        {
            File.Copy(file, Path.Combine(aikvDir, Path.GetFileName(file)), overwrite: true);
        }

        // Suggest .gitignore entry
        var gitignorePath = Path.Combine(repositoryRoot, ".gitignore");
        var gitignoreContent = File.Exists(gitignorePath) ? await File.ReadAllTextAsync(gitignorePath) : "";
        if (!gitignoreContent.Contains(".aikv/", StringComparison.Ordinal))
        {
            await File.AppendAllTextAsync(gitignorePath, "\n.aikv/\n");
        }

        return aikvDir;
    }

    /// <summary>
    /// Reads the latest exported manifest from the export directory.
    /// </summary>
    public ContextPackageManifest? ReadLatestManifest(string workspaceId)
    {
        var path = Path.Combine(GetExportDir(workspaceId), "latest-context.manifest.json");
        if (!File.Exists(path)) return null;

        var json = File.ReadAllText(path);
        return System.Text.Json.JsonSerializer.Deserialize<ContextPackageManifest>(json);
    }

    private string GetExportDir(string workspaceId) =>
        Path.Combine(_appData.Root, "exports", workspaceId);

    private static string GenerateRepoMap(ContextPackageManifest manifest)
    {
        var sb = new System.Text.StringBuilder();
        sb.AppendLine("# Repository Map");
        sb.AppendLine();
        sb.AppendLine($"Generated from Context Package: {manifest.Id.Value}");
        sb.AppendLine($"Task: {manifest.Task.OriginalText}");
        sb.AppendLine();

        if (manifest.SelectedFiles.Count > 0)
        {
            sb.AppendLine("## Files in Context");
            sb.AppendLine();
            foreach (var f in manifest.SelectedFiles)
            {
                sb.AppendLine($"- {f.Path} [{f.Mode}] (score: {f.Score:F2})");
            }
            sb.AppendLine();
        }

        if (manifest.ExcludedCandidates.Count > 0)
        {
            sb.AppendLine("## Excluded Files");
            sb.AppendLine();
            foreach (var e in manifest.ExcludedCandidates)
            {
                sb.AppendLine($"- {e.Path} (score: {e.Score:F2}) — {e.Reason}");
            }
        }

        return sb.ToString();
    }
}

using AiKv.Context.Export;
using AiKv.Context.Payload;
using AiKv.Core.Context;
using AiKv.Core.Identifiers;

namespace AiKv.Tests;

public class PayloadAndExportTests
{
    private static ContextPackageManifest CreateManifest() => new()
    {
        Id = ContextPackageId.Parse("ctx_test001"),
        WorkspaceId = WorkspaceId.Parse("ws_test001"),
        IndexSnapshotId = IndexSnapshotId.Parse("idx_test001"),
        Task = new TaskInfo { OriginalText = "Fix login bug", QueryParserVersion = "v1" },
        Ranking = new RankingInfo { ProfileId = "v1", ProfileVersion = 1 },
        Budget = new BudgetInfo
        {
            ModelContextWindow = 128000, AgentReservedTokens = 10000, ResponseReservedTokens = 8000,
            ContextTarget = 80000, ContextHardLimit = 90000, SafetyMargin = 10000, ActualEstimate = 500,
        },
        SelectedFiles =
        [
            new SelectedFile
            {
                Path = "src/auth.ts", ContentHash = "h1", Mode = SelectionMode.Full,
                Score = 0.95, Reasons = ["Symbol match"],
            },
            new SelectedFile
            {
                Path = "src/utils.ts", ContentHash = "h2", Mode = SelectionMode.Outline,
                Score = 0.60, Reasons = ["Path match"],
            },
        ],
        ExcludedCandidates =
        [
            new ExcludedCandidate { Path = "README.md", Score = 0.1, Reason = "Low score" },
        ],
        Safety = new SafetyInfo { CloudSendAllowed = true, SecretsScanPassed = true },
        ContextEngineVersion = "0.2.0",
        ChunkingStrategyVersion = "v1",
        TokenBudgetPolicyVersion = "v1",
        CreatedAt = DateTimeOffset.UtcNow,
    };

    [Fact]
    public void PayloadGenerator_Generate_ShouldCreatePayloadItems()
    {
        var generator = new PayloadGenerator();
        var manifest = CreateManifest();
        var contentMap = new Dictionary<string, string>
        {
            ["src/auth.ts"] = "export class Auth { login() {} }",
            ["src/utils.ts"] = "export function log(msg: string) { console.log(msg); }",
        };

        var payload = generator.Generate(manifest, path => contentMap.GetValueOrDefault(path, ""));

        Assert.NotEmpty(payload.Items);
        Assert.True(payload.TotalEstimatedTokens > 0);
        Assert.Equal(PayloadFormat.Markdown, payload.Format);
    }

    [Fact]
    public void PayloadGenerator_GenerateMarkdown_ShouldContainFileContents()
    {
        var generator = new PayloadGenerator();
        var manifest = CreateManifest();
        var contentMap = new Dictionary<string, string>
        {
            ["src/auth.ts"] = "export class Auth { login() {} }",
            ["src/utils.ts"] = "export function log() {}",
        };

        var markdown = generator.GenerateMarkdown(manifest, path => contentMap.GetValueOrDefault(path, ""));

        Assert.Contains("Context Package: ctx_test001", markdown);
        Assert.Contains("src/auth.ts", markdown);
        Assert.Contains("export class Auth", markdown);
        Assert.Contains("Excluded", markdown);
        Assert.Contains("README.md", markdown);
    }

    [Fact]
    public void PayloadGenerator_GenerateMarkdown_ShouldHandleEmptyContent()
    {
        var generator = new PayloadGenerator();
        var manifest = CreateManifest();

        var markdown = generator.GenerateMarkdown(manifest, path => "");

        Assert.Contains("Context Package", markdown);
        // Empty content files should be skipped
        Assert.DoesNotContain("export class", markdown);
    }

    [Fact]
    public async Task FileExporter_ExportAsync_ShouldCreateFiles()
    {
        using var tempDir = new TempDir();
        var appData = new Storage.AppDataDirectory(tempDir.Path);
        var exporter = new FileExporter(appData);
        var manifest = CreateManifest();
        var contentMap = new Dictionary<string, string>
        {
            ["src/auth.ts"] = "export class Auth { }",
            ["src/utils.ts"] = "export function log() { }",
        };

        var exportDir = await exporter.ExportAsync(manifest, path => contentMap.GetValueOrDefault(path, ""));

        Assert.True(Directory.Exists(exportDir));
        Assert.True(File.Exists(Path.Combine(exportDir, "workspace.json")));
        Assert.True(File.Exists(Path.Combine(exportDir, "latest-context.manifest.json")));
        Assert.True(File.Exists(Path.Combine(exportDir, "latest-context.md")));
        Assert.True(File.Exists(Path.Combine(exportDir, "repomap.md")));
    }

    [Fact]
    public async Task FileExporter_ExportAsync_ManifestShouldBeReadable()
    {
        using var tempDir = new TempDir();
        var appData = new Storage.AppDataDirectory(tempDir.Path);
        var exporter = new FileExporter(appData);
        var manifest = CreateManifest();

        await exporter.ExportAsync(manifest, path => "content", manifest.WorkspaceId.Value);

        var readBack = exporter.ReadLatestManifest(manifest.WorkspaceId.Value);

        Assert.NotNull(readBack);
        Assert.Equal(manifest.Id.Value, readBack!.Id.Value);
        Assert.Equal(manifest.Task.OriginalText, readBack.Task.OriginalText);
    }

    [Fact]
    public async Task FileExporter_ExportToRepositoryAsync_ShouldCreateAikvDir()
    {
        using var tempDir = new TempDir();
        using var repoDir = new TempDir();
        var appData = new Storage.AppDataDirectory(tempDir.Path);
        var exporter = new FileExporter(appData);
        var manifest = CreateManifest();

        var aikvDir = await exporter.ExportToRepositoryAsync(repoDir.Path, manifest, path => "content");

        Assert.True(Directory.Exists(aikvDir));
        Assert.True(File.Exists(Path.Combine(aikvDir, "workspace.json")));
        Assert.True(File.Exists(Path.Combine(aikvDir, "latest-context.md")));

        // .gitignore should contain .aikv/
        var gitignore = File.ReadAllText(Path.Combine(repoDir.Path, ".gitignore"));
        Assert.Contains(".aikv/", gitignore);
    }

    [Fact]
    public async Task FileExporter_ExportToRepositoryAsync_ShouldNotDuplicateGitignoreEntry()
    {
        using var tempDir = new TempDir();
        using var repoDir = new TempDir();
        await File.WriteAllTextAsync(Path.Combine(repoDir.Path, ".gitignore"), ".aikv/\n");

        var appData = new Storage.AppDataDirectory(tempDir.Path);
        var exporter = new FileExporter(appData);
        var manifest = CreateManifest();

        await exporter.ExportToRepositoryAsync(repoDir.Path, manifest, path => "content");

        var gitignore = await File.ReadAllTextAsync(Path.Combine(repoDir.Path, ".gitignore"));
