using System.Text.Json;
using System.Text.Json.Serialization;

namespace AiKv.Core.Configuration;

/// <summary>
/// AI_KV configuration file model.
/// Stored as .aikv-config.json in the AI_KV data directory.
/// </summary>
public sealed record AiKvConfig
{
    [JsonPropertyName("version")]
    public string Version { get; init; } = "1";

    [JsonPropertyName("defaultModel")]
    public string? DefaultModel { get; init; }

    [JsonPropertyName("defaultBudget")]
    public BudgetConfig? DefaultBudget { get; init; }

    [JsonPropertyName("security")]
    public SecurityConfig? Security { get; init; }

    [JsonPropertyName("gateway")]
    public GatewayConfigFile? Gateway { get; init; }

    [JsonPropertyName("indexing")]
    public IndexingConfig? Indexing { get; init; }
}

public sealed record BudgetConfig
{
    [JsonPropertyName("modelContextWindow")]
    public int ModelContextWindow { get; init; } = 128000;

    [JsonPropertyName("agentReservedTokens")]
    public int AgentReservedTokens { get; init; } = 18000;

    [JsonPropertyName("responseReservedTokens")]
    public int ResponseReservedTokens { get; init; } = 12000;

    [JsonPropertyName("targetRatio")]
    public double TargetRatio { get; init; } = 0.625;

    [JsonPropertyName("hardLimitRatio")]
    public double HardLimitRatio { get; init; } = 0.703;

    [JsonPropertyName("safetyMargin")]
    public int SafetyMargin { get; init; } = 10000;
}

public sealed record SecurityConfig
{
    [JsonPropertyName("mode")]
    [JsonConverter(typeof(JsonStringEnumConverter))]
    public Security.ExfiltrationMode Mode { get; init; } = Security.ExfiltrationMode.Standard;

    [JsonPropertyName("enableSecretScan")]
    public bool EnableSecretScan { get; init; } = true;

    [JsonPropertyName("blockedExtensions")]
    public IReadOnlyList<string>? BlockedExtensions { get; init; }
}

public sealed record GatewayConfigFile
{
    [JsonPropertyName("enabled")]
    public bool Enabled { get; init; }

    [JsonPropertyName("port")]
    public int Port { get; init; } = 5218;

    [JsonPropertyName("providerUrl")]
    public string? ProviderUrl { get; init; }

    [JsonPropertyName("enableCache")]
    public bool EnableCache { get; init; } = true;

    [JsonPropertyName("enableSingleFlight")]
    public bool EnableSingleFlight { get; init; } = true;
}

public sealed record IndexingConfig
{
    [JsonPropertyName("maxDepth")]
    public int MaxDepth { get; init; } = 50;

    [JsonPropertyName("maxFileCount")]
    public int MaxFileCount { get; init; } = 500000;

    [JsonPropertyName("maxFileSizeMb")]
    public int MaxFileSizeMb { get; init; } = 100;

    [JsonPropertyName("followSymlinks")]
    public bool FollowSymlinks { get; init; }
}

/// <summary>
/// Loads and saves AI_KV configuration.
/// </summary>
public sealed class ConfigManager
{
    private static readonly JsonSerializerOptions _jsonOpts = new() { WriteIndented = true };
    private readonly string _configPath;

    public ConfigManager(string? configDir = null)
    {
        var dir = configDir ?? Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData, Environment.SpecialFolderOption.DoNotVerify),
            "AI_KV");
        _configPath = Path.Combine(dir, "config", ".aikv-config.json");
    }

    public AiKvConfig Load()
    {
        if (!File.Exists(_configPath)) return new AiKvConfig();
        var json = File.ReadAllText(_configPath);
        return JsonSerializer.Deserialize<AiKvConfig>(json, _jsonOpts) ?? new AiKvConfig();
    }

    public void Save(AiKvConfig config)
    {
        var dir = Path.GetDirectoryName(_configPath);
        if (dir is not null) Directory.CreateDirectory(dir);
        var json = JsonSerializer.Serialize(config, _jsonOpts);
        File.WriteAllText(_configPath, json);
    }

    public bool Exists => File.Exists(_configPath);
    public string ConfigPath => _configPath;
}

using AiKv.Core.Configuration;

namespace AiKv.Tests;

public class ConfigManagerTests
{
    [Fact]
    public void ConfigManager_Load_ShouldReturnDefault_WhenNotExists()
    {
        using var temp = new TempDir();
        var manager = new ConfigManager(temp.Path);

        var config = manager.Load();

        Assert.Equal("1", config.Version);
        Assert.Null(config.DefaultModel);
    }

    [Fact]
    public void ConfigManager_SaveAndLoad_ShouldRoundTrip()
    {
        using var temp = new TempDir();
        var manager = new ConfigManager(temp.Path);

        var config = new AiKvConfig
        {
            DefaultModel = "gpt-4",
            DefaultBudget = new BudgetConfig { ModelContextWindow = 64000, SafetyMargin = 5000 },
            Security = new SecurityConfig { Mode = AiKv.Core.Security.ExfiltrationMode.Restricted },
            Gateway = new GatewayConfigFile { Enabled = true, Port = 8080, ProviderUrl = "https://api.test.com" },
        };

        manager.Save(config);
        Assert.True(manager.Exists);

        var loaded = manager.Load();

        Assert.Equal("gpt-4", loaded.DefaultModel);
        Assert.Equal(64000, loaded.DefaultBudget!.ModelContextWindow);
        Assert.Equal(AiKv.Core.Security.ExfiltrationMode.Restricted, loaded.Security!.Mode);
        Assert.True(loaded.Gateway!.Enabled);
        Assert.Equal(8080, loaded.Gateway.Port);
    }

    [Fact]
    public void ConfigManager_Exists_ShouldBeFalse_WhenNotCreated()
    {
        using var temp = new TempDir();
        var manager = new ConfigManager(temp.Path);

        Assert.False(manager.Exists);
    }

    [Fact]
    public void AiKvConfig_Default_ShouldHaveVersion1()
    {
        var config = new AiKvConfig();
        Assert.Equal("1", config.Version);
    }

    [Fact]
    public void BudgetConfig_Default_ShouldHaveStandardValues()
    {
        var budget = new BudgetConfig();
        Assert.Equal(128000, budget.ModelContextWindow);
        Assert.Equal(10000, budget.SafetyMargin);
    }

    [Fact]
    public void SecurityConfig_Default_ShouldBeStandard()
    {
        var sec = new SecurityConfig();
        Assert.Equal(AiKv.Core.Security.ExfiltrationMode.Standard, sec.Mode);
        Assert.True(sec.EnableSecretScan);
    }

    [Fact]
    public void GatewayConfigFile_Default_ShouldNotBeEnabled()
    {
        var gw = new GatewayConfigFile();
        Assert.False(gw.Enabled);
        Assert.Equal(5218, gw.Port);
    }

    [Fact]
    public void IndexingConfig_Default_ShouldHaveReasonableLimits()
    {
        var idx = new IndexingConfig();
        Assert.Equal(50, idx.MaxDepth);
        Assert.Equal(500000, idx.MaxFileCount);
    }

    private sealed class TempDir : IDisposable
    {
        public string Path { get; }
        public TempDir()
        {
            Path = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "aikv_cfg_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(Path);
        }
