}

using AiKv.Core.Repository;
using AiKv.Core.Workspaces;

namespace AiKv.Context.Integration;

/// <summary>
/// Integrates Git diff into Context Build requests.
/// Uses GitProcessWrapper to get changed files, then passes them to ContextEngine.
/// </summary>
public sealed class GitDiffProvider
{
    private readonly GitProcessWrapper _git;

    public GitDiffProvider(GitProcessWrapper? git = null)
    {
        _git = git ?? new GitProcessWrapper();
    }

    /// <summary>
    /// Gets the list of files changed since the last commit (unstaged + staged).
    /// </summary>
    public async Task<IReadOnlyList<string>> GetChangedFilesAsync(string workspaceRoot, CancellationToken ct = default)
    {
        if (!Directory.Exists(Path.Combine(workspaceRoot, ".git")))
            return [];

        var statusResult = await _git.StatusAsync(workspaceRoot, ct);
        if (!statusResult.Success) return [];

        var files = new List<string>();
        foreach (var line in statusResult.Output.Split('\n', StringSplitOptions.RemoveEmptyEntries))
        {
            var trimmed = line.Trim();
            if (trimmed.Length < 3) continue;

            // git status --porcelain format: XY filename
            var filePath = trimmed[2..].Trim().Trim('"');
            files.Add(filePath.Replace('\\', '/'));
        }
        return files;
    }

    /// <summary>
    /// Gets files changed in the last N commits.
    /// </summary>
    public async Task<IReadOnlyList<string>> GetRecentDiffFilesAsync(string workspaceRoot, int commitCount = 1, CancellationToken ct = default)
    {
        if (!Directory.Exists(Path.Combine(workspaceRoot, ".git")))
            return [];

        await using var conn = default;
        var diffResult = await _git.ExecuteAsync(workspaceRoot,
            ["diff", $"HEAD~{commitCount}..HEAD", "--name-only"],
            timeout: TimeSpan.FromSeconds(30), ct: ct);

        if (!diffResult.Success) return [];

        return diffResult.Output
            .Split('\n', StringSplitOptions.RemoveEmptyEntries)
            .Select(f => f.Trim().Replace('\\', '/'))
            .ToList();
    }

    /// <summary>
    /// Gets the current HEAD commit hash.
    /// </summary>
    public async Task<string?> GetHeadCommitAsync(string workspaceRoot, CancellationToken ct = default)
    {
        if (!Directory.Exists(Path.Combine(workspaceRoot, ".git")))
            return null;

        var result = await _git.ExecuteAsync(workspaceRoot, ["rev-parse", "HEAD"], ct: ct);
        return result.Success ? result.Output.Trim() : null;
    }
}

using AiKv.Context.Integration;
using AiKv.Core.Repository;

namespace AiKv.Tests;

public class GitDiffProviderTests
{
    [Fact]
    public async Task GitDiffProvider_GetChangedFilesAsync_ShouldReturnEmpty_WhenNotGitRepo()
    {
        using var temp = new TempDir();
        var provider = new GitDiffProvider();

        var files = await provider.GetChangedFilesAsync(temp.Path);

        Assert.Empty(files);
    }

    [Fact]
    public async Task GitDiffProvider_GetRecentDiffFilesAsync_ShouldReturnEmpty_WhenNotGitRepo()
    {
        using var temp = new TempDir();
        var provider = new GitDiffProvider();

        var files = await provider.GetRecentDiffFilesAsync(temp.Path);

        Assert.Empty(files);
    }

    [Fact]
    public async Task GitDiffProvider_GetHeadCommitAsync_ShouldReturnNull_WhenNotGitRepo()
    {
        using var temp = new TempDir();
        var provider = new GitDiffProvider();

        var commit = await provider.GetHeadCommitAsync(temp.Path);

        Assert.Null(commit);
    }

    [Fact]
    public async Task GitDiffProvider_GetChangedFilesAsync_ShouldWork_WithRealGitRepo()
    {
        // Create a real git repo in temp
        using var temp = new TempDir();
        await InitGitRepoAsync(temp.Path);

        // Create and commit a file
        await File.WriteAllTextAsync(Path.Combine(temp.Path, "app.ts"), "export const x = 1;");
        await RunGitAsync(temp.Path, ["add", "."]);
        await RunGitAsync(temp.Path, ["commit", "-m", "initial"]);

        // Modify the file (creates unstaged change)
        await File.WriteAllTextAsync(Path.Combine(temp.Path, "app.ts"), "export const x = 2;");

        var provider = new GitDiffProvider();
        var files = await provider.GetChangedFilesAsync(temp.Path);

        Assert.NotEmpty(files);
        Assert.Contains(files, f => f.Contains("app.ts"));
    }

    [Fact]
    public async Task GitDiffProvider_GetHeadCommitAsync_ShouldReturnHash_WithRealGitRepo()
    {
        using var temp = new TempDir();
        await InitGitRepoAsync(temp.Path);
        await File.WriteAllTextAsync(Path.Combine(temp.Path, "test.txt"), "test");
        await RunGitAsync(temp.Path, ["add", "."]);
        await RunGitAsync(temp.Path, ["commit", "-m", "test"]);

        var provider = new GitDiffProvider();
        var commit = await provider.GetHeadCommitAsync(temp.Path);

        Assert.NotNull(commit);
        Assert.True(commit!.Length >= 7); // Git short hash
    }

    private static async Task InitGitRepoAsync(string path)
    {
        await RunGitAsync(path, ["init"]);
        await RunGitAsync(path, ["config", "user.email", "test@test.com"]);
        await RunGitAsync(path, ["config", "user.name", "Test"]);
    }

    private static async Task RunGitAsync(string workingDir, string[] args)
    {
        var git = new GitProcessWrapper();
        await git.ExecuteAsync(workingDir, args, timeout: TimeSpan.FromSeconds(10));
    }

    private sealed class TempDir : IDisposable
    {
        public string Path { get; }
        public TempDir()
        {
            Path = System.IO.Path.Combine(System.IO.Path.GetTempPath(), "aikv_git_" + Guid.NewGuid().ToString("N"));
            Directory.CreateDirectory(Path);
        }
        public void Dispose()
        {
            if (Directory.Exists(Path)) Directory.Delete(Path, true);
        }
    }
}

using AiKv.Core.Configuration;
using AiKv.Core.Security;
using System.Text.Json;

namespace AiKv.Cli.Commands;

public static class ConfigCommands
{
    private static readonly JsonSerializerOptions _jsonOpts = new() { WriteIndented = true };

    public static int Handle(string[] args)
    {
        if (args.Length == 0)
        {
            Console.WriteLine("Usage: aikv config <show|set|init> [options]");
            return 1;
        }

        return args[0] switch
        {
            "show" => Show(),
            "init" => Init(),
            "set" => Set(args.AsSpan(1).ToArray()),
            _ => 1,
        };
    }

    private static int Show()
    {
        var manager = new ConfigManager();
        var config = manager.Load();

        Console.WriteLine($"Config file: {manager.ConfigPath}");
        Console.WriteLine($"Exists: {manager.Exists}");
        Console.WriteLine();
        Console.WriteLine($"Version: {config.Version}");
        Console.WriteLine($"Default model: {config.DefaultModel ?? "(none)"}");

        if (config.DefaultBudget is not null)
        {
            var b = config.DefaultBudget;
            Console.WriteLine($"Budget:");
            Console.WriteLine($"  Model context window: {b.ModelContextWindow}");
            Console.WriteLine($"  Agent reserved: {b.AgentReservedTokens}");
            Console.WriteLine($"  Response reserved: {b.ResponseReservedTokens}");
            Console.WriteLine($"  Target ratio: {b.TargetRatio}");
            Console.WriteLine($"  Hard limit ratio: {b.HardLimitRatio}");
            Console.WriteLine($"  Safety margin: {b.SafetyMargin}");
        }

        if (config.Security is not null)
        {
            var s = config.Security;
            Console.WriteLine($"Security:");
            Console.WriteLine($"  Mode: {s.Mode}");
            Console.WriteLine($"  Secret scan: {s.EnableSecretScan}");
            if (s.BlockedExtensions is not null)
                Console.WriteLine($"  Blocked extensions: {string.Join(", ", s.BlockedExtensions)}");
        }

        if (config.Gateway is not null)
        {
            var g = config.Gateway;
            Console.WriteLine($"Gateway:");
            Console.WriteLine($"  Enabled: {g.Enabled}");
            Console.WriteLine($"  Port: {g.Port}");
            Console.WriteLine($"  Provider URL: {g.ProviderUrl ?? "(none)"}");
            Console.WriteLine($"  Cache: {g.EnableCache}");
        }

        if (config.Indexing is not null)
        {
            var i = config.Indexing;
            Console.WriteLine($"Indexing:");
            Console.WriteLine($"  Max depth: {i.MaxDepth}");
            Console.WriteLine($"  Max file count: {i.MaxFileCount}");
            Console.WriteLine($"  Max file size (MB): {i.MaxFileSizeMb}");
            Console.WriteLine($"  Follow symlinks: {i.FollowSymlinks}");
        }

        return 0;
    }

    private static int Init()
    {
        var manager = new ConfigManager();
        if (manager.Exists)
        {
            Console.Error.WriteLine("Config file already exists. Use 'aikv config set' to modify.");
            return 1;
        }

        var config = new AiKvConfig
        {
            DefaultModel = null,
            DefaultBudget = new BudgetConfig(),
            Security = new SecurityConfig(),
            Indexing = new IndexingConfig(),
        };

        manager.Save(config);
        Console.WriteLine($"Config file created: {manager.ConfigPath}");
        return 0;
    }

    private static int Set(string[] args)
    {
        if (args.Length < 2)
        {
            Console.Error.WriteLine("Usage: aikv config set <key> <value>");
            Console.Error.WriteLine("Keys: defaultModel, security.mode, gateway.enabled, gateway.port, gateway.providerUrl");
            return 1;
        }

        var key = args[0];
        var value = args[1];
        var manager = new ConfigManager();
        var config = manager.Load();

        switch (key.ToLowerInvariant())
        {
            case "defaultmodel":
                config = config with { DefaultModel = value };
                break;
            case "security.mode":
                if (Enum.TryParse<ExfiltrationMode>(value, ignoreCase: true, out var mode))
                    config = config with { Security = (config.Security ?? new SecurityConfig()) with { Mode = mode } };
                else
                {
                    Console.Error.WriteLine($"Invalid mode. Valid: Standard, Restricted, PreviewRequired, Offline");
                    return 1;
                }
                break;
            case "gateway.enabled":
                config = config with { Gateway = (config.Gateway ?? new GatewayConfigFile()) with { Enabled = bool.Parse(value) } };
                break;
            case "gateway.port":
                config = config with { Gateway = (config.Gateway ?? new GatewayConfigFile()) with { Port = int.Parse(value) } };
                break;
            case "gateway.providerurl":
                config = config with { Gateway = (config.Gateway ?? new GatewayConfigFile()) with { ProviderUrl = value } };
                break;
            default:
                Console.Error.WriteLine($"Unknown key: {key}");
                return 1;
        }

        manager.Save(config);
        Console.WriteLine($"Set {key} = {value}");
        return 0;
    }
}

