using AiKv.Storage;
using AiKv.Storage.Database;
using AiKv.Storage.Database.Migrations;
using AiKv.Storage.Search;
using AiKv.Core.Identifiers;

namespace AiKv.Cli.Commands;

public static class SearchCommands
{
    public static async Task<int> HandleAsync(string[] args)
    {
        if (args.Length == 0)
        {
            Console.Error.WriteLine("Usage: aikv search <query> [--workspace=<id>] [--limit=N] [--output=json]");
            return 1;
        }

        var query = args[0];
        var wsId = GetOpt(args, "--workspace");
        var limitStr = GetOpt(args, "--limit") ?? "50";
        var outputJson = HasFlag(args, "--output=json") || HasFlag(args, "--json");
        var limit = int.Parse(limitStr, System.Globalization.CultureInfo.InvariantCulture);

        var appData = new AppDataDirectory();
        var dbPath = appData.GetWorkspaceDatabasePath("main");
        var factory = new SqliteConnectionFactory(dbPath);
        var runner = new MigrationRunner(factory, dbPath,
        [
            new Migration0001Initial(),
            new Migration0002Fts5(),
        ]);
        runner.Migrate();

        // If workspace specified, get its active snapshot
        IndexSnapshotId? snapshotId = null;
        if (!string.IsNullOrEmpty(wsId))
        {
            snapshotId = await GetActiveSnapshotIdAsync(factory, wsId);
            if (snapshotId is null)
            {
                Console.Error.WriteLine($"No active index snapshot found for workspace: {wsId}");
                Console.Error.WriteLine("Run 'aikv index build --id=<workspace-id>' first.");
                return 1;
            }
        }

        var fts = new Fts5Index(factory);
        var results = await fts.SearchAsync(snapshotId ?? IndexSnapshotId.New(), query, limit);

        if (results.Count == 0)
        {
            if (outputJson)
                Console.WriteLine("[]");
            else
                Console.WriteLine("No results found.");
            return 0;
        }

        if (outputJson)
        {
            var json = System.Text.Json.JsonSerializer.Serialize(results.Select(r => new
            {
                path = r.Path,
                language = r.Language,
                snippet = r.Snippet,
            }), new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
            Console.WriteLine(json);
        }
        else
        {
            Console.WriteLine($"Search results for \"{query}\" ({results.Count} matches):");
            Console.WriteLine();
            foreach (var r in results)
            {
                Console.WriteLine($"  [{r.Language}] {r.Path}");
                Console.WriteLine($"    {r.Snippet}");
                Console.WriteLine();
            }
        }

        return 0;
    }

    private static async Task<IndexSnapshotId?> GetActiveSnapshotIdAsync(SqliteConnectionFactory factory, string workspaceId)
    {
        await using var conn = factory.CreateOpenConnection();
        using var cmd = conn.CreateCommand();
        cmd.CommandText = "SELECT id FROM index_snapshots WHERE workspace_id = $ws AND status = 'Active' LIMIT 1;";
        cmd.Parameters.AddWithValue("$ws", workspaceId);
        await using var reader = await cmd.ExecuteReaderAsync();
        if (await reader.ReadAsync())
            return IndexSnapshotId.Parse(reader.GetString(0));
        return null;
    }

    private static string? GetOpt(string[] args, string prefix) =>
        args.FirstOrDefault(a => a.StartsWith(prefix + "=", StringComparison.OrdinalIgnoreCase))?[prefix.Length..];

    private static bool HasFlag(string[] args, string flag) =>
        args.Contains(flag, StringComparer.OrdinalIgnoreCase);
}

