using AiKv.Core.Parsing;
using AiKv.Core.Parsing.Outline;
using AiKv.Core.Parsing.RepoMap;
using AiKv.Indexing.Parsing;
using AiKv.Indexing.Parsing.Cache;

namespace AiKv.Cli.Commands;

public static class RepoMapCommands
{
    public static int Handle(string[] args)
    {
        if (args.Length == 0)
        {
            Console.Error.WriteLine("Usage: aikv repomap <directory> [--max-tokens=N] [--output=json]");
            return 1;
        }

        var dir = args[0];
        var maxTokensStr = args.SkipWhile(a => a != "--max-tokens").Skip(1).FirstOrDefault();
        var maxTokens = maxTokensStr is not null
            ? int.Parse(maxTokensStr, System.Globalization.CultureInfo.InvariantCulture)
            : 4000;
        var outputJson = args.Contains("--output=json", StringComparer.OrdinalIgnoreCase) ||
                         args.Contains("--json", StringComparer.OrdinalIgnoreCase);

        if (!Directory.Exists(dir))
        {
            Console.Error.WriteLine($"Error: Directory not found: {dir}");
            return 1;
        }

        var files = new List<(string relativePath, FileOutline outline)>();
        var cache = new ParserCache();
        var enumerator = new AiKv.Indexing.Scanning.DirectoryEnumerator();

        foreach (var file in enumerator.EnumerateAsync(dir).GetAwaiter().GetResult())
        {
            if (file.IsDirectory) continue;
            var ext = file.Extension ?? "";
            if (ext is not (".cs" or ".ts" or ".tsx" or ".js" or ".py" or ".md") ) continue;

            var fullPath = file.Path;
            if (!File.Exists(fullPath)) continue;

            var content = File.ReadAllText(fullPath);
            var relativePath = AiKv.Core.Paths.PathNormalizer.GetRelativePath(dir, fullPath);

            ICodeParser? parser = ext switch
            {
                ".cs" => new CSharpRegexParser(),
                ".ts" or ".tsx" or ".js" => new TypeScriptRegexParser(),
                ".py" => new PythonRegexParser(),
                ".md" => new MarkdownParser(),
                _ => new TextParser(),
            };

            var hash = $"file:{fullPath}:{file.LastModified.Ticks}";
            var result = cache.GetOrParse(content, fullPath, hash, parser);
            var outline = DeterministicOutlineGenerator.Generate(result, relativePath);
            files.Add((relativePath, outline));
        }

        var repomap = RepoMapGenerator.Generate(dir, files, maxTokens);

        if (outputJson)
        {
            var json = System.Text.Json.JsonSerializer.Serialize(new
            {
                rootPath = repomap.RootPath,
                totalFiles = repomap.TotalFiles,
                totalSymbols = repomap.TotalSymbols,
                estimatedTokens = repomap.EstimatedTokens,
                root = new
                {
                    name = repomap.Root.Name,
                    type = repomap.Root.Type.ToString(),
                    children = repomap.Root.Children.Select(c => new
                    {
                        name = c.Name,
                        path = c.Path,
                        type = c.Type.ToString(),
                        symbolCount = c.SymbolCount,
                        keySymbols = c.KeySymbols.Select(s => new { name = s.Name, kind = s.Kind.ToString(), line = s.StartLine }),
                    }),
                },
            }, _jsonOpts);
            Console.WriteLine(json);
        }
        else
        {
            Console.WriteLine($"Repository Map: {repomap.RootPath}");
            Console.WriteLine($"  Files: {repomap.TotalFiles}");
            Console.WriteLine($"  Symbols: {repomap.TotalSymbols}");
            Console.WriteLine($"  Est. Tokens: {repomap.EstimatedTokens}");
            Console.WriteLine();
            Console.WriteLine("Structure:");
            foreach (var child in repomap.Root.Children)
            {
                Console.WriteLine($"  [{child.Type}] {child.Name} ({child.SymbolCount} symbols)");
                foreach (var sym in child.KeySymbols)
                    Console.WriteLine($"    {sym.Kind,-15} L{sym.StartLine,4}  {sym.Name}");
            }
        }

        return 0;
    }

    private static readonly System.Text.Json.JsonSerializerOptions _jsonOpts = new() { WriteIndented = true };
}

using AiKv.Storage;

namespace AiKv.Cli.Commands;

public static class CleanCommands
{
    public static int Handle(string[] args)
    {
        var what = args.FirstOrDefault() ?? "temp";
        var dryRun = args.Contains("--dry-run", StringComparer.OrdinalIgnoreCase);

        var appData = new AppDataDirectory();

        return what switch
        {
            "temp" => CleanTemp(appData, dryRun),
            "cache" => CleanCache(appData, dryRun),
            "exports" => CleanExports(appData, dryRun),
            "all" => CleanAll(appData, dryRun),
            _ => PrintUsage(),
        };
    }

    private static int CleanTemp(AppDataDirectory appData, bool dryRun)
    {
        var tempDir = appData.TempPath;
        if (!Directory.Exists(tempDir))
        {
            Console.WriteLine("Temp directory is empty.");
            return 0;
        }

        var files = Directory.GetFiles(tempDir, "*", SearchOption.AllDirectories);
        Console.WriteLine($"Temp files: {files.Length}");

        if (dryRun)
        {
            Console.WriteLine("[dry-run] Would delete all temp files.");
            return 0;
        }

        foreach (var file in files)
        {
            try { File.Delete(file); }
            catch { }
        }

        Console.WriteLine($"Deleted {files.Length} temp files.");
        return 0;
    }

    private static int CleanCache(AppDataDirectory appData, bool dryRun)
    {
        var cacheDir = appData.CachePath;
        if (!Directory.Exists(cacheDir))
        {
            Console.WriteLine("Cache directory is empty.");
            return 0;
        }

        var files = Directory.GetFiles(cacheDir, "*", SearchOption.AllDirectories);
        var totalSize = files.Sum(f => new FileInfo(f).Length);
        Console.WriteLine($"Cache files: {files.Length}");
        Console.WriteLine($"Cache size: {totalSize / 1024.0 / 1024.0:F2} MB");

        if (dryRun)
        {
            Console.WriteLine("[dry-run] Would delete all cache files.");
            return 0;
        }

        foreach (var file in files)
        {
            try { File.Delete(file); }
            catch { }
        }

        Console.WriteLine($"Deleted {files.Length} cache files ({totalSize / 1024.0 / 1024.0:F2} MB).");
        return 0;
    }

    private static int CleanExports(AppDataDirectory appData, bool dryRun)
    {
        var exportsDir = Path.Combine(appData.Root, "exports");
        if (!Directory.Exists(exportsDir))
        {
            Console.WriteLine("Exports directory is empty.");
            return 0;
        }

        var dirs = Directory.GetDirectories(exportsDir);
        Console.WriteLine($"Export directories: {dirs.Length}");

        if (dryRun)
        {
            Console.WriteLine("[dry-run] Would delete all export directories.");
            return 0;
        }

        foreach (var dir in dirs)
        {
            try { Directory.Delete(dir, recursive: true); }
            catch { }
        }

        Console.WriteLine($"Deleted {dirs.Length} export directories.");
        return 0;
    }

    private static int CleanAll(AppDataDirectory appData, bool dryRun)
    {
        Console.WriteLine("Cleaning all...");
        CleanTemp(appData, dryRun);
        Console.WriteLine();
        CleanCache(appData, dryRun);
        Console.WriteLine();
        CleanExports(appData, dryRun);
        Console.WriteLine();
        Console.WriteLine("Clean complete.");
        return 0;
    }

    private static int PrintUsage()
    {
        Console.WriteLine("Usage: aikv clean <temp|cache|exports|all> [--dry-run]");
        Console.WriteLine();
        Console.WriteLine("Options:");
        Console.WriteLine("  temp      Clean temporary files");
        Console.WriteLine("  cache     Clean cache files");
        Console.WriteLine("  exports   Clean exported context packages");
        Console.WriteLine("  all       Clean everything above");
        Console.WriteLine("  --dry-run Show what would be deleted without actually deleting");
        return 1;
    }
}

